using VsBotKit.Panel;

namespace VsBotKit;

/// <summary>
/// РОЛЬ, КОТОРАЯ ПРОСТО ЖИВЁТ — общие ручки для всех, кто зовёт
/// <see cref="Presets.Survive"/>.
///
/// ЗАЧЕМ ЭТОТ КЛАСС ПОЯВИЛСЯ. Пресет выживания подключает КАЖДОЙ роли четыре
/// способности, которые тратят чужое добро и лезут людям на глаза: точку
/// возрождения (тратит временную шестерёнку), приветствие эмоцией, фонарь в
/// левой руке (игра берёт за него 20% скорости голода) и «что делать без дела»
/// (умеет уйти бродить и даже выйти из игры). Ручки для всего этого были
/// заведены у ОДНОГО Копателя. Заказчик, выбравший Жителя или Продавца,
/// получал бота, который к ночи берёт факел и машет покупателям, а выключить
/// это из окна управления было нечем — настройки просто не существовало.
///
/// Сюда же переехало «слушать ли приказы из игрового чата»: без этой ручки
/// чужой игрок командует ботом, а закрыть чат мог только Копатель.
///
/// Класс — ПОЛИТИКА и ничего больше: он не умеет ни здороваться, ни носить
/// фонарь, а только доносит решения роли до способностей библиотеки. Каждая
/// ручка живёт в ОДНОМ месте — здесь, — и в панели появляется сама
/// (<see cref="RoleKnobs"/> читает публичные свойства роли отражением).
///
/// Роль-наследник обязана в конце своего <c>Configure</c> позвать
/// <see cref="ОбщиеНастройкиГотовы"/> — иначе ручки останутся мёртвым грузом,
/// и об этом будет сказано вслух, а не замолчано.
///
/// НОМЕРА МЕСТ (<c>Order</c>) ЗДЕСЬ — ОБЩИЕ НА ВСЕХ, и в них нарочно оставлены
/// дыры. Пока Выживальщик жил отдельной веткой (наследовал BotRole), одни и те
/// же семь ручек боя были заведены дважды, и номера у двух копий разошлись.
/// Сведя копии в одну, номера взяли из БОЛЬШЕЙ роли — у Выживальщика ручек под
/// сотню, и его раскладка в окне не сдвинулась ни на строку. Дыры (4…5, 8…9,
/// 20…23) — это места, куда роль-наследник вставляет своё, не двигая общего:
/// у Выживальщика там стоят «СтавитьФакелы» («работа» 4) и «ИскатьСундукиРядом»
/// («склад» 3). (Примеры пришлось поменять: прежние двое, «СобиратьЕду» и
/// «ДержатьсяОтЧужого», сами уехали сюда волнами 09.09 — и строка, называвшая
/// их ручками одной роли, стала бы неправдой в тот же день.)
/// </summary>
public abstract class LivingRole : BotRole, IWorkRunnerRole
{
    private VsBot? бот;

    /// <summary>
    /// Бот, которому эта роль служит; null — роль ещё не собрана.
    ///
    /// Нужен наследнику ровно затем же, зачем базе: донести повёрнутую ручку до
    /// механизма. Заводить в каждой роли своё поле «бот» — значит завести
    /// столько же мест, где оно может остаться пустым.
    /// </summary>
    protected VsBot? Бот => бот;

    // ---------------- склад и дом ----------------

    /// <summary>
    /// СКЛАД: куда носить добытое и откуда брать недостающее. Не задан —
    /// склада нет, и бот об этом честно скажет, а не промолчит. Взять его
    /// можно и словом «!склад тут», стоя у сундука; а у Выживальщика есть
    /// сверх того своя ручка «ИскатьСундукиРядом» — с ней он при входе в мир
    /// САМ берёт под склад ближний сундук, если своего склада ему не задали.
    ///
    /// ПРО ВЫЖИВАЛЬЩИКА СКАЗАНО ЗДЕСЬ НАРОЧНО, хоть ручка эта и не общая.
    /// Приёмка 29.08: окно (этой самой строкой) говорило «склада нет», а
    /// presets/digger.json — «Пока склада нет, бот ищет сундук рядом»; прав был
    /// пресет, и человек, читавший окно, ждал молчания от бота, который тем
    /// временем брал сундук сам и рисовал в панели точку, которой хозяин не
    /// вписывал. Один вопрос обязан иметь один ответ, где бы его ни задали.
    ///
    /// Координаты ИГРОВЫЕ — те самые, что игра показывает игроку (258, 111,
    /// −260). Внутри мир живёт в абсолютных (512258, 111, 511740), и перевод
    /// делается в одном месте, <see cref="ДонестиОбщее"/>, — там же, где
    /// переводится <see cref="Дом"/>. Живой случай: заказчик задал склад в
    /// панели, отправил бота разгружаться и получил «склад не задан — некуда
    /// нести», а числа с экрана игры, положенные в Depot без перевода, увели
    /// бы его за полмиллиона блоков.
    ///
    /// ПОЧЕМУ ЭТА РУЧКА ЗДЕСЬ, А НЕ У ОДНОГО КОПАТЕЛЯ. Заказчик просил
    /// дословно: «сохранение склада и дома давай на одной странице настроек —
    /// в настройки роли». Ручка жила в <c>SurvivorRole</c>, и ключа «Склад» не
    /// было ВОВСЕ в трёх готовых ботах из шести — «ai», «guard», «trader»: то
    /// есть для хозяина стражника, продавца и ИИ этой настройки НЕ
    /// СУЩЕСТВОВАЛО (закон 1), а задать склад им можно было только словом в
    /// чат. При этом сам склад (<see cref="Depot"/>) общий у всех давно —
    /// стражник с него кормится, продавец сдаёт на него выручку, — и все
    /// прочие ручки склада (СкладНеДальшеЧем, СекундНаРейс, опись) уже жили
    /// здесь. Порознь стояла ровно точка.
    ///
    /// ПРОСТОЕ СВОЙСТВО, БЕЗ СВОЕГО СЕТТЕРА — так же, как <see cref="Дом"/>.
    /// Донесение зовёт единственная дверь (<see cref="Донести"/>) на каждый
    /// поворот любой ручки и на вход в мир; второй путь «из сеттера» был бы
    /// второй дверью в ту же комнату.
    ///
    /// «RoleTab = true» — ЭТО ВТОРАЯ ПОЛОВИНА ТОЙ ЖЕ ПРОСЬБЫ, и без неё первая
    /// не стоила ничего. Переехать в <c>LivingRole</c> значило попасть ко всем
    /// ролям — и разом ВЫПАСТЬ с вкладки «Настройка роли», которую заказчик
    /// назвал вслух: делил её один признак «своё у роли», а общая ручка своей
    /// не станет никогда. Метка говорит окну, что крутят эту точку ЗДЕСЬ, не
    /// притворяясь при этом «своей» (см. <see cref="KnobPlaceAttribute.RoleTab"/>).
    /// </summary>
    [KnobPlace("склад", Order = 1, Main = true, RoleTab = true)]
    public GamePos? Склад { get; set; }

    /// <summary>
    /// ДОМ: куда прятаться в бурю, где спать, куда идти без дела и где ставить
    /// точку возрождения. Не задан — дома нет, и всё перечисленное честно
    /// откажется работать.
    ///
    /// Координаты ИГРОВЫЕ — те самые, что игра показывает игроку (258, 111,
    /// −260). Внутри мир живёт в абсолютных (512258, 111, 511740), и перевод
    /// делается в одном месте, <see cref="ДонестиОбщее"/>. Раньше у Жителя
    /// здесь стояли МИРОВЫЕ координаты, и человек, вписавший в панель числа с
    /// экрана игры, отправлял бота домой за полмиллиона блоков.
    ///
    /// «RoleTab = true» — ТОЧКА КРУТИТСЯ НА ВКЛАДКЕ «НАСТРОЙКА РОЛИ», прямо
    /// под <see cref="Склад"/>: «сохранение склада и дома давай на одной
    /// странице настроек — в настройки роли». Разлучи их вкладками — и просьба
    /// не выполнена, даже если раздел и номера совпадают.
    /// </summary>
    [KnobPlace("склад", Order = 2, Main = true, RoleTab = true)]
    public GamePos? Дом { get; set; }

    /// <summary>
    /// БРАТЬ ПОД СКЛАД СОСЕДНИЕ СУНДУКИ в этом радиусе от заданной точки,
    /// блоков. 0 — только сама точка.
    ///
    /// Живой случай: сундук у дома один и он полон, а рядом стоят ещё три —
    /// вписать в панель можно только ОДНУ точку, и бот докладывал «склад
    /// полон», стоя вплотную к трём пустым ящикам. Человеку проще поставить
    /// сундуки в ряд, чем вводить координаты каждого.
    ///
    /// СОСЕДИ НЕ ЗАПОМИНАЮТСЯ, ИХ ИЩУТ ЗАНОВО КАЖДЫЙ ОБХОД (Depot.Points) —
    /// сундук могли сломать или поставить новый. Отсюда и всё остальное: «где
    /// склад» у роли живёт ОДНОЙ точкой, которая переживает перезапуск, а
    /// сколько сундуков под ней — считает эта ручка.
    ///
    /// ПОЧЕМУ ЗДЕСЬ, А НЕ У ОДНОГО КОПАТЕЛЯ, ГДЕ ОНА ЖИЛА ДО 29.08. Слово
    /// «!склад тут» переехало ко всем живущим ролям вместе с самой точкой
    /// «Склад», а эта ручка осталась у копателя — то есть у стражника,
    /// продавца и ИИ радиус соседей был ВЕЧНЫМ НУЛЁМ. Живьём это значило вот
    /// что: стражник говорил «!склад тут», слышал «взял сундуков: 16» — и на
    /// первый же поворот любой ручки в панели (донесение сводит склад к
    /// заданной точке) оставался с ОДНИМ сундуком. Ручка, которой у роли нет,
    /// не «стоит по умолчанию» — её для хозяина не существует (закон 1).
    ///
    /// «RoleTab = true» — по той же причине, что у <see cref="Склад"/> и
    /// <see cref="Дом"/>: радиус без точки бессмыслен, и человек ищет его там
    /// же, где задал точку. Общей ручка стала — своей она уже не будет никогда,
    /// а вкладку заказчик назвал вслух.
    /// </summary>
    [KnobPlace("склад", Order = 4, RoleTab = true)]
    public int СоседниеСундукиВРадиусе { get; set; } = 6;

    /// <summary>
    /// САМ ИДТИ РАЗГРУЖАТЬСЯ ПРИ ПОЛНЫХ СУМКАХ — и возвращаться к делу.
    ///
    /// Заказчик просил дословно: «когда заполнены все слоты — бот идёт
    /// разгружаться, тоже галочка в настройках», и следом: «инвентарь у бота
    /// полный и он не идет». До этой галочки на склад бота отправлял только
    /// человек — командой «!разгрузка»; сам он с полной сумкой продолжал
    /// ломать породу, а выломанное падало на землю и там оставалось.
    ///
    /// ПЕРЕЕХАЛА СЮДА 09.09 ОТ ВЫЖИВАЛЬЩИКА ВСЛЕД ЗА СВОЕЙ ТОЧКОЙ. Сама точка
    /// «Склад», радиус соседних сундуков и слово «!склад тут» стали общими
    /// ещё 29.08; способность (<see cref="BehaviorHaulWhenFull"/>) пресет
    /// выживания подключает КАЖДОМУ боту — а включить её могла одна роль из
    /// пяти. Стражник, которому заказчик велел «кушать со склада», сундук
    /// имел, дойти до него с полной сумкой не мог, и сказать ему об этом было
    /// нечем (закон 1).
    ///
    /// ЗАВОДСКОЕ ЗДЕСЬ «НЕТ», А НЕ «ДА», И ЭТО ЕДИНСТВЕННОЕ ЧЕСТНОЕ ЧИСЛО.
    /// Из семи ручек этой волны только у неё умолчание роли РАСХОДИЛОСЬ с тем,
    /// что механизм имел без неё: <c>BehaviorHaulWhenFull.Enabled</c> — «нет»,
    /// и пресет выживания гасит способность отдельной строкой. Приедь сюда
    /// «да» — продавец, ИИ и бот под внешним управлением с завтрашнего дня
    /// уходили бы от прилавка к сундукам МОЛЧА, у всякого, кто этой ручки не
    /// крутил (о лавочнике так и сказано у самой способности). Своё «да»
    /// выживальщик ставит в конструкторе, рядом с причиной.
    ///
    /// Выключить это стоит там, где склад далеко, а работа дороже груза: бот
    /// прерывает карьер, уходит на склад и возвращается — рейс на триста
    /// блоков может стоить дороже недобранной сумки.
    ///
    /// «RoleTab = true» — по той же причине, что у <see cref="Склад"/> и
    /// <see cref="СоседниеСундукиВРадиусе"/>: разгрузку человек крутит рядом с
    /// той самой точкой, куда бот носит. Общей ручка стала — своей она уже не
    /// будет никогда (<c>RoleCatalog.OnlyHere</c>), а вкладку заказчик назвал
    /// вслух, и обещание «пятеро соседей склада стоят на месте» держит стенд
    /// <c>ВкладкаНастройкаРолиTests.Соседи_склада_остались_на_вкладке_роли_у_копателя</c>.
    /// </summary>
    [KnobPlace("склад", Order = 5, Main = true, RoleTab = true)]
    public bool РазгружатьсяСам { get; set; }

    /// <summary>
    /// ПРИ СКОЛЬКИХ СВОБОДНЫХ МЕСТАХ ПОРА НА СКЛАД. 0 — только когда сумка
    /// забита начисто.
    ///
    /// Порог общий на весь бот: по нему же ходит на склад наряд за рудой. Три
    /// места из тридцати двух — это запас на последнюю жилу и на то, что
    /// упадёт под ноги по дороге; ноль означает, что бот ломает породу в
    /// никуда до самого последнего слота.
    ///
    /// Сумка, забитая СВОИМ (кирка, факелы, еда), рейса не вызывает ни при
    /// каком пороге — нести туда нечего.
    ///
    /// ПЕРЕЕХАЛА СЮДА 09.09 ВМЕСТЕ С ГАЛОЧКОЙ ВЫШЕ, и разрыв закрыла, а не
    /// открыла: число живёт в СКЛАДЕ (<see cref="Depot.HaulWhenFreeSlots"/>),
    /// склад есть у каждого бота, и по этому же порогу ходит поручение за
    /// материалом — то есть у четырёх ролей из пяти он и так работал, только
    /// повернуть его было нечем. Заводское то же, что у механизма (3), значит
    /// переезд не переменил НИ ОДНОГО числа никому.
    /// </summary>
    [KnobPlace("склад", Order = 6, RoleTab = true)]
    public int РазгружатьсяПриСвободныхМестах { get; set; } = 3;

    /// <summary>
    /// Через сколько секунд пробовать снова, если рейс не удался: сундук полон,
    /// до склада не дойти, в заданной точке не хранилище.
    ///
    /// Пауза нужна потому, что неудача сама не проходит: сумка как была полной,
    /// так и осталась. Без паузы бот отбирал бы тело у работы каждые полсекунды
    /// и ходил бы к тому же полному сундуку, а возврат к прерванному бросил бы
    /// карьер уже на третьем таком заходе как безнадёжный.
    ///
    /// Переехала сюда 09.09 третьей в семье и стоит с ней рядом (номера 5, 6 и
    /// 7): все три — про один рейс, и искать их человек будет в одном месте.
    /// Заводское то же, что у механизма (<c>BehaviorHaulWhenFull.RetrySeconds</c>
    /// — 60), значит переезд не переменил ничего.
    /// </summary>
    [KnobPlace("склад", Order = 7, RoleTab = true)]
    public int ПовторРазгрузкиЧерезСекунд { get; set; } = 60;

    /// <summary>
    /// Держать точку возрождения дома. Ставится ВРЕМЕННОЙ ШЕСТЕРЁНКОЙ
    /// (gear-temporal), и та при этом ТРАТИТСЯ — потому по умолчанию выключено.
    /// Шестерёнку бот возьмёт со склада, если она там лежит; больше её взять
    /// негде — в мире она не растёт и не крафтится.
    /// </summary>
    [KnobPlace("склад", Order = 8)]
    public bool ОтмечатьДом { get; set; }

    /// <summary>
    /// Дальше этого ради отметки дома не ходить, блоков. Дорога домой через
    /// полкарты — тоже риск, и он может стоить дороже самой точки.
    ///
    /// ПЕРЕЕХАЛА СЮДА 08.09 ОТ ВЫЖИВАЛЬЩИКА, И РАЗРЫВ ЗАКРЫЛА, А НЕ ОТКРЫЛА:
    /// саму галочку («ОтмечатьДом», номер 8 выше) и точку дома доносила уже
    /// база, а цена дороги за ней оставалась у одной роли — то есть стражнику,
    /// продавцу и ИИ окно показывало «отмечать дом: да» и не давало сказать,
    /// как далеко за этим идти. Способность подключена пресетом выживания
    /// КАЖДОМУ боту (Presets.Survive), значит и ручка общая.
    ///
    /// Номер прежний (9): раскладку этого ящика человек выучил, и переезд ради
    /// порядка не вправе двигать ему поля.
    /// </summary>
    [KnobPlace("склад", Order = 9)]
    public double ДомДальше { get; set; } = 500;

    /// <summary>
    /// С какого расстояния точка возрождения считается домашней, блоков.
    /// Сервер ставит её в позицию ИГРОКА, а не ровно в заданную клетку, —
    /// без допуска бот переставлял бы её шестерёнкой каждую минуту.
    ///
    /// Переехала сюда 08.09 парой к <see cref="ДомДальше"/> и стоит с ней
    /// рядом (номера 9 и 10): обе — про одну точку возрождения, и искать их
    /// человек будет в одном месте.
    /// </summary>
    [KnobPlace("склад", Order = 10)]
    public double ДопускДома { get; set; } = 4;

    /// <summary>
    /// СПАТЬ НОЧЬЮ В КРОВАТИ.
    ///
    /// Способность подключена пресетом выживания КАЖДОМУ боту и включена, а
    /// ручки у неё не было НИ У ОДНОЙ РОЛИ: ни выключить, ни спросить в окне,
    /// спит ли бот вообще, было нечем. Жалоба заказчика 16.08 — «не ложится
    /// спать» — читалась как поломка ровно потому, что настройки не
    /// существовало, а способность о своих отказах молчала.
    ///
    /// ОДНОГО ДОМА ДЛЯ СНА МАЛО. Нужна КРОВАТЬ (в игре это блок с
    /// sleepEfficiency; точка дома её не заменяет), ночь, усталость выше 8 и
    /// отсутствие бури — полный список в <see cref="BehaviorSleepAtNight"/>.
    /// Чего не хватает, бот называет сам, в журнале, ночью.
    /// </summary>
    [KnobPlace("склад", Order = 14, Main = true)]
