    ///
    /// ПОЧЕМУ ЭТО ЖИВЁТ ЗДЕСЬ, А НЕ У КАЖДОЙ РОЛИ. Ручка была заведена ДВАЖДЫ —
    /// у Выживальщика (по умолчанию да, место «люди» 1) и у MCP (по умолчанию
    /// нет, место «люди» 0) — при одном и том же смысле. Разные умолчания тут
    /// НОРМАЛЬНЫ и сохранены (в проверках мода лишний шум мешает, см.
