    /// бот входит в мир, сказано в первой мысли (LlmRole.FirstThought). Обещать
    /// «выключил — молчит» было бы враньём: за слова там отвечает модель.
    /// </summary>
    [KnobPlace("люди", Order = 1)]
    public bool Здороваться { get; set; } = true;

    /// <summary>
