    ///
    /// Фраза — ПОЛИТИКА роли, а «сказать её или смолчать» — общий механизм, и
    /// поэтому они разнесены. Пока приветствие целиком лежало в
    /// <c>OnJoinedAsync</c> каждой роли, Продавец здоровался безусловно, а
    /// ручка у соседей называлась одинаково и работала по-разному.
    /// </summary>
    protected virtual string? ФразаПриВходе(VsBot bot) => null;

    /// <summary>
    /// ВХОД В МИР: сказать своё приветствие, если роль его завела и человек его
    /// не выключил.
    ///
    /// Роль-наследник, у которой при входе есть и другие дела (донести склад,
    /// поднять разговор), перекрывает этот метод и зовёт
    /// <c>base.OnJoinedAsync(bot)</c> — иначе ручка «Здороваться» у неё станет
    /// мёртвым грузом, а мёртвая ручка врёт человеку в окне управления.
    ///
    /// ОБА УСЛОВИЯ ЗДЕСЬ ЖИВЫЕ, И ЭТО ПРОВЕРЕНО, А НЕ ОБЕЩАНО. Приёмка нашла,
    /// что затвор не сторожил никто: убери отсюда «Здороваться &amp;&amp;» — и весь
    /// прогон оставался зелёным, то есть снятая в окне галочка ничего не
    /// выключала. Теперь обе половины (галочка и «фраза непуста») закреплены
    /// проверками по САМОМУ ЧАТУ (<see cref="VsBot.OnSay"/>), а не по свойству
    /// роли: свойство — намерение, а человек видит строку в чате. Без второй
    /// половины бот слал бы в чат пустую строку и считал, что поздоровался.
    /// </summary>
    public override Task OnJoinedAsync(VsBot bot) =>
        Здороваться && ФразаПриВходе(bot) is { Length: > 0 } фраза
            // ВЕЖЛИВОСТЬ, А НЕ ОТЧЁТ: радиотишина эту строку не глушит. Выключать
            // её есть чем — самой галочкой «Здороваться», и вторая ручка для
            // того же дела была бы второй копией одной механики
            ? bot.SayAsync(фраза, reason: SayReason.Вежливость)
            : Task.CompletedTask;

