    /// перевернуться несколько раз, а каждый переворот — это перенос вещи на
    /// сервер. Ноль означает «решать по самой границе», как было.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 18)]
    public double ДержатьФонарьПослеРассветаЧасов { get; set; } = 1;

    /// <summary>
    /// НЕ ПЕРЕИГРЫВАТЬ РЕШЕНИЕ О ФОНАРЕ ЧАЩЕ, чем раз в столько секунд —
