    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 19)]
    public double НеТрогатьФонарьСекунд { get; set; } = 20;

    // ---------------- что держать при себе и чем жертвовать ----------------

    /// <summary>
    /// СВОЙ РАЗДЕЛ ПАНЕЛИ. Фонарь, инструменты и «что выбрасывать» — это не
    /// работа, не безопасность и не люди; без своего раздела всё это уезжало
    /// в «Прочее» или, того хуже, в «Безопасность» по слову «голод» в описании.
    /// Заголовок и строка «что внутри» повторены у КАЖДОЙ ручки раздела
    /// нарочно: панель берёт их у первой встреченной, а порядок отражения
    /// менять не нам.
    ///
    /// ПОЧЕМУ ИМЯ РАЗДЕЛА ЛЕЖИТ ЗДЕСЬ, А НЕ В ПАНЕЛИ. Общий список разделов
    /// (KnobHelp.Sections) — это то, что панель знает без ролей; раздел,
    /// который завела роль, живёт у роли. Раздел один на всех, поэтому и место
    /// у него одно: Выживальщик берёт эти же три строки отсюда, а не заводит
    /// свою копию, которая однажды разошлась бы по заголовку.
    /// </summary>
    public const string Снаряжение = "снаряжение";

    /// <summary>Заголовок раздела «Снаряжение» — см. <see cref="Снаряжение"/>.</summary>
    public const string СнаряжениеЗаголовок = "Снаряжение";

    /// <summary>
    /// Строка «что внутри» для раздела «Снаряжение».
