    /// из припасов». Настройка была и стояла ровно тут — но раздел назывался
    /// одним лишь «снаряжением», и человек, искавший слово «припасы», прошёл
    /// мимо. Настройка, которую не нашли, ничем не отличается от настройки,
    /// которой нет.
    /// </summary>
    public const string СнаряжениеОписание =
        "запасы (припасы): что держать в руках и в сумках, чем пополнять " +
        "недостающее — крафтом или добычей, чем жертвовать, когда места нет";

    /// <summary>
    /// СКОЛЬКО ФАКЕЛОВ ДЕРЖАТЬ ПРИ СЕБЕ. Ноль — не требовать вовсе.
    ///
    /// По умолчанию ноль, и это прямое указание заказчика: «факелы нафиг».
    /// Живьём требование стоило ему каждого наряда — работа не начиналась
    /// вовсе, пока в сумке не наберётся шестнадцать факелов: «[наряд] запасов
    /// не хватает: torch: 0/16». Ставить факелы в ходах бот при этом не
    /// разучился (ручка Выживальщика «СтавитьФакелы») — он просто не
    /// отказывается работать без них.
    ///
    /// ПОЧЕМУ ОНА ЗДЕСЬ, А НЕ У ВЫЖИВАЛЬЩИКА, ГДЕ ЖИЛА ДО 09.09. Читатель у неё
    /// один и он общий: <see cref="Stock.Require"/> — тот же самый механизм, в
    /// который сосед по разделу «ДержатьЛестниц» (тоже неподвижное требование,
    /// тоже fetch: false) доносится из этого файла и у всех пяти ролей. Разницы
    /// в механике между «держать 4 лестницы» и «держать 8 факелов» нет ни
    /// одной, а ручка была у одного.
    ///
    /// И ОБ ЭТОМ УЖЕ ГОВОРИЛИ ВСЛУХ ДВА ЧУЖИХ МЕСТА, оба общие. Подпись
    /// «ДержатьСверхЗапасаПроцентов» (этот же раздел) отсылает человека:
    /// «нужен счёт — впишите вещь в запас („ЗапасПоРасходу: torch“ или
    /// „ДержатьФакелов“)», а <see cref="Upkeep"/> держит на этой самой ручке
    /// свою заставу против двух голосов за один род — и называет её в разборе
    /// поимённо (<c>Upkeep.Поставить</c>; в журнал при споре уходит общее
    /// «обнулите ту ручку, которая держит род неподвижным»). До переезда
    /// подпись обещала стражнику, продавцу, ИИ и MCP ручку, которой у них не
    /// было вовсе.
    ///
    /// ЗАВОДСКОЙ НОЛЬ ничего никому не меняет: ноль СНИМАЕТ требование, и роль,
    /// которая факелов не жжёт, о них и не узнает.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 2)]
    public int ДержатьФакелов { get; set; }

    /// <summary>
    /// СКОЛЬКО ЛЕСТНИЦ ДЕРЖАТЬ ПРИ СЕБЕ. Ноль — не требовать вовсе.
    ///
    /// ПРЯМОЙ ЗАКАЗ: «к запасам нужно добавить лестницы вертикальные, бот должен
    /// носить их с собой и/или крафтить». Лечит он вот эту строку живого
    /// журнала — она повторилась дважды за ночь, в 01:33 и в 09:20:
    ///     [стройка] наверх на 2 бл: на подъём с 2 бл нужно 2 блоков под столб
    ///               или 1 лестниц, а есть блоков 0 и лестниц 0; готовой стены
    ///               под лестницу нет; и ступеней не вырубить
    /// Подниматься по лестнице бот умел давно (<see cref="Scaffolding"/>,
    /// <see cref="Climbing"/>) — лестниц не было В ЗАПАСАХ, и просить их было
    /// нечем.
    ///
    /// ПОЧЕМУ ЧЕТЫРЕ. Лестницы вешают ЧЕРЕЗ ОДНУ (правило игры, см.
    /// <see cref="Scaffolding.EveryOtherBlock"/>), значит четыре штуки — это
    /// восемь блоков подъёма: обе живые ямы (2 и 4 бл) закрываются с запасом.
    /// Стоят они дёшево: ванильный рецепт даёт три лестницы из восьми палок, а
    /// палки бот и так собирает по дороге.
    ///
    /// В МИРЕ ЛЕСТНИЦЫ НЕ ДОБЫВАЮТСЯ, и это не забывчивость: выломать лестницу
    /// можно только из чужой (а то и своей вчерашней) шахты, и живой игрок так
    /// не делает. Их либо делают, либо берут из сундука — за материалом же
    /// (палки, доски) бот сходит сам, если разрешено «ДобыватьНедостающее».
    ///
    /// ЗДЕСЬ, У ОБЩЕЙ РОДНИ, ЗАВОДСКОЙ НОЛЬ — тем же порядком, что и у списка
    /// инструментов: продавцу за прилавком лестница ни к чему, и требовать её у
    /// всех подряд значило бы гонять лавочника за палками. Своё число ставит та
    /// роль, которой оно нужно (у Выживальщика — в конструкторе).
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 3)]
    public int ДержатьЛестниц { get; set; }

    // ---- ЗАПАС ПО РАСХОДУ: три ручки, и стоять они обязаны рядом ----
    // Одна называет пары, две другие — числа к ним. Разведи их по разным местам
    // окна, и человек, нашедший «ЗапасПоРасходу», не найдёт, чем крутить
    // количество. Порядок у всех трёх один нарочно: они и есть одна настройка,
    // разбитая на части.

    /// <summary>
    /// ЧТО ДЕРЖАТЬ ПРО ЗАПАС ПО РАСХОДУ: «чем пользуюсь — то и держу».
    ///
    /// ЗАКАЗ 26.08, СЛОВА ЗАКАЗЧИКА ДОСЛОВНО: «также больше бы логики, чтобы
    /// бот сам понимал чего ему не достает и крафтил, например стрелы».
    ///
    /// КАК ПИСАТЬ. Через запятую — пары «расходник к тому, чем его тратят»:
    ///     arrow к bow          — стрелы, пока при мне лук
    ///     bandage к ...        — бинты, пока при мне то, чем лечатся
    ///     torch                — без «к»: повод один — сам расход
    /// Пусто — правило выключено, и ничего сверх неподвижных требований бот не
    /// держит.
    ///
    /// СКОЛЬКО — НЕ ЗДЕСЬ. Числа считаются по расходу
    /// (<see cref="Upkeep.Reserve"/>): сколько истрачено за
    /// «ЗапасНаМинутРасхода», столько и носим — не меньше «ЗапасНаПервыйРаз» и
    /// не больше полной стопки по реестру. Поэтому в строке нет ни одного
    /// количества: впиши его человек сюда, и запас снова стал бы неподвижным,
    /// то есть ровно тем, от чего уходим.
    ///
    /// ПОЧЕМУ КОДЫ, А НЕ РУССКИЕ СЛОВА. У инструментов русское слово переводит
    /// САМА ИГРА (в реестре у кирки стоит вид Pickaxe), и потому «кирка, лопата»
    /// написать можно. Для стрел и факелов такого перечисления в игре нет, и
    /// словарь «стрелы = arrow» был бы выдуманным списком — это в проекте прямо
    /// запрещено, и горели на этом трижды. Коды человек и так видит в окне
    /// («Запасы: ladder 8/64») и в соседней ручке «ДержатьПриСебе»
    /// («pickaxe, shovel, axe, torch»).
    ///
    /// РОД, А НЕ ПОЛНЫЙ КОД: «arrow» — это все четырнадцать материалов стрел
    /// сразу, а «arrowhead» под него НЕ подходит (мерка — семья кода, а не
    /// подстрока: иначе бот с сумкой наконечников считал бы себя со стрелами).
    ///
    /// ЗАВОДСКОЕ ПУСТО У ОБЩЕЙ РОДНИ — тем же порядком, что у списка
    /// инструментов и у лестниц: продавцу за прилавком стрелы ни к чему. Своё
    /// пишет та роль, которой оно нужно.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание,
        Order = 2, Main = true)]
    public string ЗапасПоРасходу { get; set; } = "";

    /// <summary>
    /// НА СКОЛЬКО МИНУТ РАСХОДА ДЕРЖАТЬ ЗАПАС.
    ///
    /// Читается буквально: «сколько трачу за полчаса — столько и ношу». Другого
    /// смысла в числе нет, и это нарочно: человек, крутящий ползунок, обязан
    /// понимать ответ бота без калькулятора.
    ///
    /// БОЛЬШЕ — НЕ ЛУЧШЕ. Заказчик уже жаловался на метания за припасами;
    /// поставить сюда несколько часов значит велеть боту носить всё, что он
    /// потратил за смену, то есть превратить его в хомяка. Верхний край всё
    /// равно держит полная стопка по реестру, но до неё бот дойдёт быстрее, чем
    /// хочется.
    ///
    /// Ноль означал бы «расхода не помню вовсе», то есть вечное
    /// «ЗапасНаПервыйРаз»; снизу поэтому минута.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 2)]
    public int ЗапасНаМинутРасхода { get; set; } = 30;

    /// <summary>
    /// СКОЛЬКО ДЕРЖАТЬ, ПОКА НЕ ТРАТИЛ НИ РАЗУ.
    ///
    /// Без этого числа правило не заводится вовсе: чтобы начать тратить стрелы,
    /// их надо сперва иметь, а у пустого колчана расход нулевой. Это та самая
    /// первая горсть, с которой живой игрок уходит из дома.
    ///
    /// Оно же остаётся НИЖНИМ КРАЕМ и потом: истратил бот за полчаса две
    /// стрелы — это не повод ходить с двумя.
    ///
    /// Ноль — законный выбор («ничего заранее не держу, только по расходу»),
    /// поэтому снизу не единица, а ноль.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 2)]
    public int ЗапасНаПервыйРаз { get; set; } = 16;

    /// <summary>
    /// НУЖЕН ЛИ БОТУ ЛУК — то есть считать ли его НЕХВАТКОЙ и добывать наравне
    /// с киркой и лопатой.
    ///
    /// ЧТО ЭТО ЧИНИТ, ДОСЛОВНО. Стрелы бот держать умел давно: соседняя строка
    /// «ЗапасПоРасходу: arrow к bow» так и читается — «стрелы, пока при мне
    /// лук». А САМ ЛУК не просил никто и никогда. Выходило кольцо, из которого
    /// бот не мог выйти сам: лука нет — значит повода держать стрелы нет —
    /// значит стрел нет — значит и лук ни к чему. Весь дальний бой, вся охота
    /// издали и весь разговор про колокола держались на том, что лук боту
    /// КТО-ТО ПОЛОЖИТ. Эта галочка убирает «кто-то».
    ///
    /// ОТКУДА ОН ВОЗЬМЁТСЯ. Отсюда — ниоткуда: здесь только сказано «он мне
    /// нужен». Дальше работает та же цепочка, что и на кирку: запасы считают
    /// нехватку, снабжение идёт по звеньям «сумки → склад → дом → крафт →
    /// добыть рядом», а рецепт берётся ИЗ РЕЕСТРА СЕРВЕРА. В ванильной игре
    /// 1.22.7 это выходит «простой лук» — ТРИ палки и три бечёвки, а бечёвка
    /// это четыре льняных волокна; ни одного из этих чисел в нашем коде нет и
    /// быть не должно (правило 6), их присылает сервер вместе с рецептами.
    ///
    /// ПРО «ТРИ» ОТДЕЛЬНО, потому что это живой урок волны 27.08. Заказ этой
    /// волны называл ЧЕТЫРЕ палки, я переписал число с его слов — и живой бот
    /// поправил обоих в первую же минуту прогона: «Для bow-crude не хватает:
    /// stick 0/3, rope 0/3». Узор рецепта в игре «_ST S_T _ST» даёт ровно по
    /// три. Ровно так в этом проекте и горели на выдуманных списках: число,
    /// переписанное с чужих слов, ничем не лучше выдуманного.
    ///
    /// ПОЧЕМУ ОТДЕЛЬНАЯ ГАЛОЧКА, А НЕ СЛОВО В «ДержатьПриСебе». Потому что
    /// список инструментов понимает человеческие имена вещей ИЗ ЯЗЫКА ИГРЫ, а
    /// в русском языке игры «Лук» — ЭТО ОВОЩ (<c>item-vegetable-onion = Лук</c>),
    /// оружие же называется «Простой лук». Напиши человек «лук» — бот честно
    /// ответил бы «это не инструмент» и не взял бы ничего, а виноватым выглядел
    /// бы он. Галочка этой ловушки не знает вовсе.
    ///
    /// ЗАВОДСКОЕ «НЕТ» У ОБЩЕЙ РОДНИ — тем же порядком, что у лестниц и у
    /// списка инструментов: лавочнику за прилавком лук ни к чему, а сбор льна
    /// и палок — это настоящие полчаса ходьбы. Своё «да» ставит та роль,
    /// которой лук нужен.
    ///
    /// СТРЕЛЯТЬ ИЗ НЕГО — СОСЕДНЯЯ РУЧКА, «СтрелятьИзЛука» (раздел
    /// «безопасность»). Здесь решается только «доставать ли», там — «пускать
    /// ли в дело»: это разные вопросы, и снятая галочка боя не мешает боту
    /// иметь лук для охоты.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание,
        Order = 2, Main = true)]
    public bool НуженЛук { get; set; }

    /// <summary>
    /// МЫТЬ ЛИ ЛОТКОМ, когда нужного нет ни в сумке, ни в мире.
    ///
    /// ЧТО ЭТО ОТКРЫВАЕТ. Ровно ту дверь, в которую упирались две волны подряд.
    /// Соседняя галочка «НуженЛук» велит боту добыть лук — а лук держится на
    /// тетиве, тетива на льняных волокнах, и по реестру блоков волокна падают
    /// РОВНО С ОДНОГО блока: со спелого льна crop-flax-9. Зимой его нет нигде,
    /// и обе волны написали в отчёт «flaxfibers в зимнем мире взять негде».
    /// Это неправда: лоток достаёт волокна из КОСТЯНОЙ ЗЕМЛИ (pan.json,
    /// panningDrops), и время года тут ни при чём. Костяная земля лежала в
    /// четырнадцати блоках от точки входа всё это время.
    ///
    /// ЧЕСТНАЯ ЦЕНА, ЧТОБЫ НИКТО НЕ ЖДАЛ ЧУДА. За одну промывку выпадает НЕ
    /// БОЛЬШЕ ОДНОЙ вещи, и волокно достаётся примерно в одном случае из
    /// девяти (0,111 — считает <c>Panning.ChancePerPan</c> по таблице ассета, а
    /// не по числу «0,15» из неё: перебор идёт до первого попадания, и кость с
    /// шансом 0,3 часть бросков забирает). На три мотка тетивы — около ста
    /// десяти промывок, то есть примерно тринадцать блоков костяной земли и
    /// семь минут одного лишь держания кнопки, не считая ходьбы.
    ///
