    /// сервер её не делает и безголовый бот промыл бы и на суше — но живой
    /// игрок не может, значит не может и бот (закон 5).
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание,
        Order = 3, Main = true)]
    public bool МытьЛоткомКогдаИначеНегде { get; set; } = true;

