    public int ПромывокЗаЗаход { get; set; } = 25;

    /// <summary>
    /// СКОЛЬКО ДЕРЖАТЬ СВЕРХ ЗАПАСА, ПРОЦЕНТОВ, — А ОСТАЛЬНОЕ НА СКЛАД.
    ///
    /// ЧТО ЭТО ЧИНИТ. «Запас» до сих пор был только НИЖНИМ краем: бот знал,
    /// сколько ему НАДО, и не знал, сколько ему МНОГО. Всё подобранное с земли
    /// оседало в сумке навсегда — отстрелянные стрелы, лишние лестницы, — и
    /// разгрузка не помогала: эти вещи она считала нужными и отвечала «в сумке
    /// только своё — нести нечего». Теперь всё, что выше запаса и этой
    /// прибавки, склад увозит в сундук и говорит об этом числом. При запасе 64
    /// и прибавке 25 % бот держит 80, и на двух сотнях стрел выходит: «отнёс на
    /// склад лишние 120 (arrow-flint), таких при себе осталось 80» и следом
    /// «по запасу „arrow“ держу 80, при мне сейчас 80».
    ///
    /// ПРИМЕР ЗДЕСЬ ПОПРАВЛЕН 26.08: стояло «лишние 137, оставил 64» — то есть
    /// пример противоречил заводскому числу СВОЕЙ ЖЕ ручки (при 25 % остаётся
    /// 80, а не 64) сразу в шести местах.
    ///
    /// ЗАЧЕМ ПРИБАВКА, А НЕ ГОЛЫЙ ЗАПАС. Бот, оставшийся без стрел посреди
    /// охоты, хуже бота с лишними двадцатью. Она же служит порогом рейса: пока
    /// излишек меньше прибавки, бот с места не сходит.
    ///
    /// ПРОЦЕНТЫ, А НЕ ШТУКИ. Одна ручка на все запасы разом: стрелам при
    /// требовании 64 четверть даёт 80, кирке при требовании 1 — ту же кирку
    /// (обычное округление, а не вверх). Впиши сюда «16 штук», и бот таскал бы
    /// семнадцать кирок, буквально исполняя настройку.
    ///
    /// НОЛЬ ЗАКОНЕН: «держу ровно столько, сколько велено, остальное на склад».
    /// Верхнего края нет: 400 означают «сдаю только то, что впятеро выше
    /// запаса» — это почти «не сдаю ничего», и такой выбор за человеком.
    ///
    /// ЧЕГО РУЧКА НЕ КАСАЕТСЯ: вещей, про которые в запасах не сказано ни
    /// слова. Кирка, факел и еда остаются при боте по маске «ОставлятьПриСебе»
    /// и по прочности — там счёта нет и взять его неоткуда. Нужен счёт —
    /// впишите вещь в запас («ЗапасПоРасходу: torch» или «ДержатьФакелов»).
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание, Order = 2)]
    public int ДержатьСверхЗапасаПроцентов { get; set; } = 25;

    /// <summary>
    /// ДЕЛАТЬ НЕДОСТАЮЩЕЕ ПО РЕЦЕПТУ: кирку, факелы, лестницы, покрытие дороги.
    ///
    /// ПОЧЕМУ ЗОВЁТСЯ ИМЕННО ТАК. Прежнее имя — «КрафтитьПоПотребности», и
    /// заказчик её не нашёл: «Не нашел настройку где указывается крафт
    /// недостающих вещей из припасов». Слово «потребность» в панели не
    /// встречается больше нигде, а «недостающее» стоит парой строк ниже
    /// («ДобыватьНедостающее») — эти двое и есть ответ на вопрос «чем пополнять
    /// запасы: сделать или сходить взять», и стоять они обязаны рядом и
    /// называться одинаково. Старое имя понимается (<see cref="KnobWasNamedAttribute"/>),
    /// чужие пресеты не слетят.
    ///
    /// ЧТО ОНА ВЫКЛЮЧАЕТ НА САМОМ ДЕЛЕ. Крафт по потребности живёт в трёх
    /// местах, и все три доносятся отсюда: запасы (<see cref="Stock.MayCraft"/>),
    /// снабжение (<see cref="Supply.MayCraft"/>) и дорога
    /// (<see cref="Roads.MayCraft"/>). Про снабжение стоит сказать отдельно:
    /// цепочка «где взять недостающее» завелась прошлой волной, а ручку до неё
    /// не довели вовсе — снятая галочка НЕ ВЫКЛЮЧАЛА крафт, потому что
    /// снабжение крафтило по своему заводскому «да».
    ///
    /// Выключать стоит там, где уходить с места нельзя вовсе.
    /// </summary>
    [KnobWasNamed("КрафтитьПоПотребности",
        Why = "стоит парой с «ДобыватьНедостающее» — сделать или сходить взять; " +
              "значение то же, флаг")]
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание,
        Order = 4, Main = true)]
    public bool КрафтитьНедостающее { get; set; } = true;

    /// <summary>
    /// ХОДИТЬ ЗА НЕДОСТАЮЩИМ В МИР: собирать палки с кустов и камни с земли,
