    public bool ДобыватьНедостающее { get; set; } = true;

    /// <summary>
    /// ДОДЕЛЫВАТЬ НАЧАТОЕ, ПОКА ДЕЛАТЬ НЕЧЕГО: собрать инструмент из того, что
    /// уже вытесано и лежит в сумке.
    ///
    /// ЖИВОЙ СЛУЧАЙ, РАДИ КОТОРОГО ЗАВЕДЕНА (журнал 16.08, 13:11:51). Бот
    /// вытесал лезвие ножа — «в сумке прибавилось: knifeblade-peridotite x1»,
    /// — не нашёл палки, цепочка честно оборвалась, и лезвие пролежало в сумке
    /// до конца вечера. Заказчик дословно: «недостающие инструменты, которые он
    /// начал один раз делать и не сделал (вырезал из камня, но не скрафтил с
    /// палкой в инвентаре)», «почему он не делал крафт инструментов в простое».
    ///
    /// ЧТО ИМЕННО ОНА ВКЛЮЧАЕТ. Способность <see cref="BehaviorFinishStarted"/>
