    public bool ДоделыватьНачатое { get; set; } = true;

    /// <summary>
    /// СХОДИТЬ ЗА НЕДОСТАЮЩИМ СНАРЯЖЕНИЕМ, ПОКА ДЕЛАТЬ НЕЧЕГО.
