    /// Pickaxe: 0/1, Shovel: 0/1, Axe: 0/1, Knife: 0/1», — и закончил словами
    /// «ходить за материалом — наряд: в простое я за этим не хожу; не занимаю
    /// тело и жду». И ждал. Без кирки он не копает, не столбится и не
    /// выбирается из ямы; драться ему было нечем. За девять минут он умер
    /// дважды. Заказчик: «револьвер опять не так работает, бот же умрет».
    ///
    /// ЧЕГО НЕ ХВАТАЛО — НЕ МЕХАНИЗМА, А ПОВОДА. Добор запасов
    /// (<see cref="Stock.ReplenishAsync"/>) в проекте есть и работает, но его
    /// звали ТОЛЬКО ПЕРЕД НАРЯДОМ. Между нарядами о нём не вспоминал никто.
    ///
    /// ЧЕМ ЭТА РУЧКА ОТЛИЧАЕТСЯ ОТ «ДоделыватьНачатое», И ПОЧЕМУ ИХ ДВЕ. Та
