    public bool СнаряжатьсяВПростое { get; set; } = true;

    /// <summary>
    /// В КАКОМ РАДИУСЕ ВОКРУГ СЕБЯ ИСКАТЬ МАТЕРИАЛ, блоков.
    ///
    /// ПОЧЕМУ ЭТО ЧИСЛО СТАЛО ВИДНЫМ ЧЕЛОВЕКУ ИМЕННО СЕЙЧАС. До волны 22.08 оно
    /// было внутренним делом поручений: «обойди округу и поищи». Теперь по нему
    /// решается ОТКАЗ, который человек читает в окне управления, — «в этой
    /// местности этого не найти: принесите». Разбор «что из чего»
    /// (<see cref="Stock.PlanFor"/>) спрашивает <see cref="Errands.NearbyNow"/>
    /// прежде, чем обещать поход, и тем самым берёт ту породу камня, которая
    /// вокруг ЕСТЬ, а не ту, чей код короче. Число, от которого зависит слово
    /// «нет», обязано поворачиваться рукой.
    ///
    /// СОРОК ВОСЕМЬ — не вкус, а прежнее заводское значение механизма, и оно же
    /// цена вопроса: один обзор такой округи — это около полутора сотен тысяч
    /// клеток, миллисекунды; вчетверо больший радиус стоит в шестнадцать раз
    /// дороже, а спрашивают его на каждый разбор. Больше ставят тому, кто
    /// работает в скудной местности и готов платить временем; меньше — тому,
    /// кто не должен отходить от места вовсе.
    ///
    /// ДВА ЧИТАТЕЛЯ, И ОБА ОДНО И ТО ЖЕ ЧИСЛО: им меряет и разбор («есть ли это
    /// рядом»), и само поручение («что ломать»). Разъедься они — бот обещал бы
    /// поход туда, куда потом не дошёл бы, и наоборот.
    /// </summary>
    [KnobPlace(Снаряжение, Title = СнаряжениеЗаголовок, About = СнаряжениеОписание,
        Order = 7, Main = true)]
    public int ИскатьМатериалВРадиусе { get; set; } = 48;

    /// <summary>
    /// ОБКАПЫВАТЬ РАДИ ЦЕЛЬНОГО БЛОКА — снимать соседей так, чтобы блок падал
    /// ЦЕЛЫМ, а не рассыпался тем, что с него обычно валится.
    ///
    /// ИМЯ У РУЧКИ СМЕНИЛОСЬ 28.08, И ВОТ ПОЧЕМУ. Звалась она
    /// «ДобыватьЦельныйКамень», а правит НЕ КАМНЕМ: правило внутри
    /// (<see cref="WholeStone.OnlyByIsolation"/>) не спрашивает материал вовсе,
    /// оно спрашивает «есть ли у блока BreakIfFloating и нет ли просимого среди
    /// его обычных выпадений». В ванили 1.22.7 под это попадают, кроме породы
    /// (проверено по assets/survival/blocktypes):
    ///   • <c>rottenlog-*</c>   — с удара падает только insect-grub;
    ///   • <c>termitemound-*</c> — только insect-termite;
    ///   • ВСЕ НЕСОРТНЫЕ РУДЫ (<c>ore-ungraded.json</c>: flint, lignite,
    ///     bituminouscoal, anthracite, quartz, cinnabar, borax, sylvite,
    ///     alum, corundum, olivine, sulfur и прочие из
    ///     worldproperties/block/ore-ungraded.json). У них выпадение
    ///     <c>ore-{type}</c> КОРОЧЕ кода блока: с
    ///     <c>ore-bituminouscoal-shale</c> падает <c>ore-bituminouscoal</c>,
    ///     без породы в имени. Значит просьба по ПОЛНОМУ коду блока —
    ///     «!добудь ore-bituminouscoal-shale» — тоже зовёт обкапывание.
    ///     Здесь стоял один <c>ore-flint-*</c>, и это была неправда по объёму:
    ///     кремень — не исключение, а первый в списке из полутора десятков.
    /// То есть «!принеси rottenlog-east 1» тоже заставляет бота обкопать
    /// соседей вокруг бревна. Ручка с прежним именем такого объёма не обещала,
    /// и человек его по имени не опознал бы.
    ///
    /// СОРТНЫЕ руды (<c>ore-graded.json</c>) сюда НЕ попадают: их выпадение
    /// <c>ore-{grade}-{type}-{rock}</c> повторяет код блока целиком, просимое
    /// падает с одного удара, и правило до обкапывания не доходит.
    ///
    /// МЕТЕОРИТ ЗДЕСЬ СТОЯЛ ОШИБОЧНО И УБРАН: с <c>meteorite-iron</c> падает
    /// предмет <c>stone-meteorite-iron</c>, то есть просимое СРЕДИ выпадений
    /// есть, и правило до обкапывания не доходит вовсе
    /// (<c>blocktypes/stone/meteorite.json</c>, drops).
    ///
    /// «ПРОСЯТ САМ БЛОК» — ЭТО РАВЕНСТВО КОДА, А НЕ ПОДСТРОКА, и вот живая
    /// цена этой разницы: <c>crackedrock-granite</c> содержит «rock-granite»,
    /// у него тоже BreakIfFloating, и падает с него тот же stone-granite. Пока
    /// мерка была подстрочной, «добудь rock-granite 20» приносило двадцать
    /// ТРЕСНУВШИХ блоков с докладом об успехе — счёт в сумке тоже подстрочный
    /// (см. <see cref="WholeStone.OnlyByIsolation"/>).
    ///
    /// Дальше в подписи «камень» остаётся как ГЛАВНЫЙ случай, потому что ради
    /// него ручку и просили.
    ///
    /// ЭТО ПРАВИЛО ИГРЫ, А НЕ ХИТРОСТЬ БОТА, и игра говорит его человеку сама.
    /// В справочнике каменного блока (assets/survival/blocktypes/stone/rock.json,
    /// attributes.handbook) написано: «Full block can be obtained by breaking
    /// all adjacent blocks». Обычный удар даёт ПРЕДМЕТ stone-… по две-три штуки
    /// (dropsByType того же файла), а поведение BreakIfFloating перебивает
    /// выпадение и отдаёт РОВНО ОДИН ЦЕЛЫЙ БЛОК — но лишь тогда, когда ни одна
    /// из шести граней не упирается в твердь. Инструмент на это не влияет
    /// вовсе: кирка решает только, поддастся ли камень и как быстро.
    ///
    /// СЛОВА ЗАКАЗЧИКА, ради которых ручка и появилась: «чтобы мы не копали из
    /// камня, когда слой толще 1, то нужно „шахматкой“ копать для добычи
    /// цельных блоков».
    ///
    /// ЧТО МЕНЯЕТСЯ, КОГДА ВКЛЮЧЕНО:
    ///   • поручение «добудь rock-granite 20» ОБКАПЫВАЕТ блок со всех сторон и
    ///     приносит целые блоки. Раньше оно било камень в лоб и не приносило
