    /// <summary>
    /// КОПАТЬ ШАХМАТКОЙ — «ЧЕРЕЗ ОДНУ», РАДИ ЦЕЛЫХ БЛОКОВ ВМЕСТО ЩЕБНЯ.
    ///
    /// СЛОВА ЗАКАЗЧИКА, ТРИЖДЫ. 28.08: «чтобы мы не копали из камня, когда слой
    /// толще 1, то нужно „шахматкой“ копать для добычи цельных блоков». 03.09:
    /// «копать шахматкой я имел в виду ВСЕГДА, ДЛЯ ЛЮБЫХ РАБОТ». И тогда же:
