    /// понимать и уметь».
    ///
    /// ЧЕМ ЭТО ОТЛИЧАЕТСЯ ОТ «ОбкапыватьРадиЦельногоБлока», С КОТОРОЙ ОНА
    /// СТОИТ РЯДОМ. Та — про ОДИН блок по поручению: снести вокруг него до
    /// шести чужих блоков, чтобы принести именно его. Эта — про ПОРЯДОК, когда
    /// объём и так снимается весь: яма карьера и оболочка вокруг жилы — это
    /// сотни клеток, и разница только в том, В КАКОЙ ОЧЕРЁДНОСТИ. Ни одна
    /// клетка из работы не выпадает, ни одного лишнего блока не ломается.
