    /// ЧТО МЕНЯЕТСЯ, КОГДА ВКЛЮЧЕНО. Сперва снимаются «жертвы» — клетки одной
    /// чётности и каждый второй поперечный слой; потом остальные. У этих
    /// остальных к их очереди не остаётся НИ ОДНОЙ твёрдой грани, а игра при
    /// шести свободных гранях отдаёт РОВНО ОДИН ЦЕЛЫЙ БЛОК вместо двух-трёх
