    /// ЖИЛЫ. Обе снимают ОБЪЁМ — тело с толщиной по всем трём осям, — а целый
    /// блок бывает только там: у клетки должны освободиться ВСЕ ШЕСТЬ граней,
    /// то есть каждый её сосед обязан либо быть воздухом, либо уйти вместе с
    /// ней в этот же заход.
    ///
    /// ДОРОГА, ШТОЛЬНЯ И УКРЫТИЕ ЦЕЛЫХ БЛОКОВ НЕ ДАЮТ — НИ ОДНОГО, И ЭТО НЕ
    /// НЕДОРАБОТКА. Они снимают породу СРЕЗАМИ: ряд дороги, шаг хода, одна-две
    /// клетки стены. У среза сосед ВПЕРЁД в заход не входит и стоит нетронутой
    /// породой, а одной твёрдой грани хватает, чтобы блок рассыпался щебнем.
    /// Проверено числами: ход 3×3×8 = 72 клетки, поданный ОБЪЁМОМ, даёт 3
