    ///
    /// ЗДЕСЬ СТОЯЛО «ХОТИТЕ ЦЕЛЫЕ БЛОКИ С ДОРОГИ ИЛИ ХОДА — СТАВЬТЕ ИМ ШИРИНУ
    /// ОТ 3», И ЭТО БЫЛА ЛОЖЬ ЧЕЛОВЕКУ. Поставивший тройку вынимал ВТРОЕ
    /// БОЛЬШЕ ПОРОДЫ и не получал ни одного целого блока: дело в размере
