    /// СКОЛЬКО МИНУТ ЗАПИСЬ СЧИТАЕТСЯ СВЕЖЕЙ. Свежий сундук осмотр пропускает:
    /// открывать шестнадцать сундуков, в которые заглядывали минуту назад, —
    /// та же беготня, только наоборот.
    /// </summary>
    [KnobPlace(Опись, Title = ОписьЗаголовок, About = ОписьОписание, Order = 2)]
    public double ОписьСвежаМинут { get; set; } = 5;

    /// <summary>
    /// ЧЕРЕЗ СКОЛЬКО МИНУТ ОТВЕТ «ЭТОГО ТАМ НЕТ» ПЕРЕСТАЁТ БЫТЬ ОТВЕТОМ.
    ///
    /// Мерка нужна только ОТРИЦАТЕЛЬНОМУ ответу: «там лежит шестерёнка»
    /// устаревает не страшно (сходил и не нашёл — потерял рейс), а «там
    /// шестерёнки нет» устаревает опасно — по старой записи бот откажется идти
    /// за вещью, которую хозяин положил в сундук десять минут назад.
    ///
    /// Политика: у бота, чей сундук трогает только он сам, запись живёт хоть
    /// сутки; у бота на людном сервере — минуты.
    /// </summary>
    [KnobPlace(Опись, Title = ОписьЗаголовок, About = ОписьОписание, Order = 3)]
    public double ОписьПротухаетЧерезМинут { get; set; } = 30;

    /// <summary>
    /// СКОЛЬКО СЕКУНД ОТВОДИТСЯ НА ОБХОД СКЛАДА. Потолок нужен затем, что без
    /// него опись съедала бы тот самый рейс, ради которого бот и пришёл.
    /// </summary>
    [KnobPlace(Опись, Title = ОписьЗаголовок, About = ОписьОписание, Order = 4)]
    public double СекундНаОбходСклада { get; set; } = 60;

    // ---------------- очередь задач на вечер ----------------

    /// <summary>
    /// СВОЙ РАЗДЕЛ ПАНЕЛИ ПОД ОЧЕРЕДЬ. Без него «секунд на дорогу» уехали бы во
    /// «Время и скорость», «бегать ли домой за материалом» — в «Работу», а
    /// «сколько брать» — в «Прочее»: четыре ручки одного дела в трёх ящиках.
    /// </summary>
    public const string Очередь = "очередь";

    /// <summary>Заголовок раздела «Очередь задач» — см. <see cref="Очередь"/>.</summary>
    public const string ОчередьЗаголовок = "Очередь задач";

    /// <summary>Строка «что внутри» для раздела «Очередь задач».</summary>
    public const string ОчередьОписание =
        "сколько давать на дорогу к задаче и стоит ли бегать домой за материалом";

    /// <summary>
    /// СКОЛЬКО СЕКУНД ДАВАТЬ НА ДОРОГУ К ТОЧКЕ ЗАДАЧИ. Не дошёл за это время —
    /// задача честно кончается словами «до точки работы не дошёл», а не стоит
    /// всю ночь.
    ///
    /// Политика: копателю, уходящему за триста блоков, пяти минут в обрез, а
    /// боту, работающему во дворе, они означают пять минут топтания перед
    /// запертой калиткой вместо честного отказа и следующей задачи.
    /// </summary>
    [KnobPlace(Очередь, Title = ОчередьЗаголовок, About = ОчередьОписание, Order = 1)]
    public double СекундНаДорогуКЗадаче { get; set; } = 300;

    /// <summary>
    /// БЕЖАТЬ ЛИ ДОМОЙ ЗА НЕДОСТАЮЩИМ МАТЕРИАЛОМ — общее решение на всю
    /// очередь. Отдельная задача вправе сказать своё («домойЗаМатериалом»), и
    /// её слово старше этого.
    ///
    /// Рейс бывает ТОЛЬКО когда своего склада у задания нет (человек не сказал,
    /// откуда брать) и когда работа сама назвала, чего ей не хватило. Живой
    /// случай — дорога, вставшая на середине с «мостить нечем», когда камня
    /// дома два сундука.
    ///
    /// Политика: у бота со складом за спиной рейс стоит полминуты, а у того,
    /// чей дом в трёхстах блоках, — половину смены, и хозяин вправе сказать
    /// «стой на месте и жди меня».
    /// </summary>
    [KnobPlace(Очередь, Title = ОчередьЗаголовок, About = ОчередьОписание, Order = 2, Main = true)]
    public bool БегатьДомойЗаМатериалом { get; set; } = true;

    /// <summary>
    /// СКОЛЬКО РАЗ ЗА ОДНУ ЗАДАЧУ ОТЛУЧАТЬСЯ ДОМОЙ. Два — потому что первый
    /// рейс лечит обычную нехватку, а второй бывает нужен, когда рецепту нужны
    /// два разных материала и первого хватило, а второй кончился следом. Третий
    /// подряд означает, что дома его тоже нет, и честнее сказать это вслух, чем
    /// бегать всю ночь. Ноль — не бегать вовсе (то же, что галочка выше).
    /// </summary>
    [KnobPlace(Очередь, Title = ОчередьЗаголовок, About = ОчередьОписание, Order = 3)]
    public int РейсовДомойЗаЗадачу { get; set; } = 2;

    /// <summary>
    /// НА СКОЛЬКО СБОРОВ РЕЦЕПТА БРАТЬ МАТЕРИАЛ ЗА ОДИН РЕЙС. Рецепт называет
    /// нехватку на ОДИН сбор («камня надо 4»), а дороге нужны сотни: без запаса
    /// бот бегал бы домой на каждый метр полотна.
    ///
    /// Политика с ценой в обе стороны: больше — реже бегать, но сумка занята
    /// материалом, и добычу класть некуда; меньше — сумка свободна, а рейсов
    /// вдвое.
    /// </summary>
    [KnobPlace(Очередь, Title = ОчередьЗаголовок, About = ОчередьОписание, Order = 4)]
    public int БратьМатериалНаСборов { get; set; } = 8;

    /// <summary>
    /// ДАЛЬШЕ ЭТОГО ЗА МАТЕРИАЛОМ НЕ ХОДИТЬ, блоков. 0 — порога нет.
    ///
    /// ЗАКАЗ 15.08: «порог „стоит ли идти“ (далеко ли, много ли времени) —
    /// настройкой роли». Это НЕ то же, что «СкладНеДальшеЧем»: та мерка
    /// говорит «склада там не бывает вовсе» (защита от опечатки в
    /// координатах), а эта — «склад мой, но за четырьмя камнями я в такую даль
    /// не пойду». Разгрузку полной сумки порог не трогает: её всё равно надо
    /// нести.
    ///
    /// Политика: у копателя в трёхстах блоках от дома рейс за камнем стоит
    /// половины смены, а у того, кто мостит двор, — полминуты.
    ///
    /// ПОЧЕМУ ЗАВОДСКОЕ ЗНАЧЕНИЕ — «ПОРОГА НЕТ». Беда, с которой заказчик
    /// пришёл 15.08, — это НЕ состоявшийся рейс: «там было всё для крафта
    /// дороги, а он не стал туда возвращаться». Поставить сюда число значило бы
    /// починить рейс и тут же завести вторую причину его не делать, о которой
    /// человек не просил. Порог — для того, кто его СПРОСИТ.
    /// </summary>
    [KnobPlace(Очередь, Title = ОчередьЗаголовок, About = ОчередьОписание, Order = 5)]
    public double ЗаМатериаломНеДальшеБлоков { get; set; }

    /// <summary>
    /// И НЕ ДОЛЬШЕ ЭТОГО — минут на дорогу туда-обратно. 0 — порога нет.
    ///
    /// Два порога, а не один, потому что блоки и минуты — разные вещи: сто
    /// блоков по ровному это полминуты, а сто блоков по горам через
    /// транслокатор — совсем не полминуты. Считается по той скорости шага,
    /// какой бот ходит на самом деле. Заводское значение — «порога нет», по той
    /// же причине, что и у соседней ручки.
    /// </summary>
    [KnobPlace(Очередь, Title = ОчередьЗаголовок, About = ОчередьОписание, Order = 6)]
    public double ЗаМатериаломНеДольшеМинут { get; set; }

    // ---------------- сеть транслокаторов ----------------

    /// <summary>
    /// СВОЙ РАЗДЕЛ ПАНЕЛИ ПОД СЕТЬ ПЕРЕХОДОВ. Без него адрес карты уехал бы в
    /// «Прочее», радиус — в «Безопасность» по слову «дальше», а цены пути — во
    /// «Время и скорость» по слову «секунд»: одна настройка на четыре ящика.
    /// Заголовок и строка «что внутри» повторены у каждой ручки нарочно —
    /// панель берёт их у первой встреченной (как и у «Снаряжения» выше).
    /// </summary>
    public const string Сеть = "транслокаторы";

    /// <summary>Заголовок раздела «Транслокаторы» — см. <see cref="Сеть"/>.</summary>
    public const string СетьЗаголовок = "Транслокаторы";

    /// <summary>Строка «что внутри» для раздела «Транслокаторы».</summary>
    public const string СетьОписание =
        "откуда брать карту переходов и во что считать дорогу по ней";

    /// <summary>
    /// АДРЕС КАРТЫ СЕРВЕРА, с которой брать сеть транслокаторов — ТОТ ЖЕ, что
    /// у окна управления («https://map.tops.vintagestory.at/»). Пусто — в
    /// интернет не ходить вовсе.
    ///
    /// ПОЧЕМУ ЭТО РУЧКА РОЛИ, А НЕ ЧИСЛО В БИБЛИОТЕКЕ. Закон проекта прямой:
    /// адреса и пороги — политика. Зашитый адрес работал бы ровно на одном
    /// сервере и молча врал бы на любом другом; а пока ручки не существовало
    /// вовсе, спросить маршрут было НЕОТКУДА — весь счёт по сети лежал мёртвым
    /// грузом, и человек об этом не узнавал ни словом.
    ///
    /// Второй адрес вписывать не нужно: сеть лежит внутри той же карты на
    /// известном месте (<see cref="TranslocatorNetRules.GeoJsonUrl"/>).
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 1, Main = true)]
    public string КартаТранслокаторов { get; set; } = "";

    /// <summary>
    /// ФАЙЛ СЕТИ РЯДОМ С БОТОМ (он же кеш скачанного). Пусто — файлом не
    /// пользоваться.
    ///
    /// Читается ПЕРВЫМ и работает без интернета — а боты живут на серверах, где
    /// выход наружу могут и закрыть. Скачанное с карты кладётся сюда же:
    /// назавтра сеть годится без единого запроса.
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 2)]
    public string ФайлСетиТранслокаторов { get; set; } = "";

    /// <summary>
    /// ЧЕРЕЗ СКОЛЬКО ЧАСОВ ИДТИ ЗА КАРТОЙ ЗАНОВО. По умолчанию сутки — столько
    /// же, сколько живёт сама выгрузка (WebCartographer перевыгружает мир не
    /// чаще раза в день).
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 3)]
    public double КартаУстареваетЧерезЧасов { get; set; } = new TlRouteSettings().StaleAfterHours;

    /// <summary>
    /// НА СКОЛЬКО БЛОКОВ БОТ ГОТОВ ОТОЙТИ ОТ СЕТИ ПЕШКОМ, чтобы попасть на
    /// ближайший транслокатор (и так же — с последнего до цели). Дальше этого
    /// круга сеть просто не помогает, и маршрут говорит об этом словами.
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 4)]
    public double ОтходитьОтСетиНеДальше { get; set; } = new TlRouteSettings().WalkRadius;

    /// <summary>
    /// ВО СКОЛЬКО СЕКУНД ОБХОДИТСЯ ОДНА ПЕРЕСАДКА — от «встал на пластину» до
    /// «стою на той стороне». Меньше — бот охотнее плетёт цепочки прыжков ради
    /// экономии шагов; больше — охотнее идёт ногами.
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 5)]
    public double СекундНаПересадку { get; set; } = new TlRouteSettings().TeleportSeconds;

    /// <summary>
    /// СКОЛЬКО СЕКУНД НА БЛОК ПУТИ ПО ЗЕМЛЕ. Число замерено ногами на живом
    /// сервере и нарочно стоит между шагом и бегом: граф меряет расстояние по
    /// прямой, а ноги идут в обход гор и озёр. Менять вслепую не надо —
    /// маршрут разойдётся с тем, что бот показывает часами.
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 6)]
    public double СекундНаБлокПешком { get; set; } = new TlRouteSettings().WalkSecondsPerBlock;

    /// <summary>
    /// КОГДА СЕТЬ ТОГО СТОИТ: сколько секунд она должна выигрывать НА КАЖДОЙ
    /// ПЕРЕСАДКЕ, чтобы бот шёл через неё, а не ногами.
    ///
    /// ЗАЧЕМ ЭТО ВООБЩЕ РЕШАТЬ, если маршрут и так считает самый быстрый путь.
    /// Потому что два его ответа стоят разного доверия. Пеший путь бот считает
    /// сам и ни от кого не зависит; путь по сети — по карте, которой может быть
    /// сутки, и каждая пересадка на нём это место, где план обрывается:
    /// транслокатор ломают, застраивают, у него отбирают пару. Выигрыш в
    /// полминуты такого не стоит, выигрыш в сорок минут — стоит.
    ///
    /// ПОЧЕМУ ПОЛИТИКА, А НЕ ЧИСЛО В БИБЛИОТЕКЕ. Это оценка ЧУЖОГО СЕРВЕРА:
    /// там, где сеть исправна и ухожена, порог не нужен вовсе (0), а там, где
    /// половина переходов разобрана, он нужен большим. Библиотека про этот
    /// сервер не знает ничего.
    ///
    /// По умолчанию — 15 с: ровно столько бот простоит на пластине, прежде чем
    /// узнает, что карта про неё соврала (см.
    /// <see cref="TlRouteSettings.MinNetGainSecondsPerTransfer"/>).
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 7)]
    public double ВыигрышНаПересадкуСекунд { get; set; } =
        new TlRouteSettings().MinNetGainSecondsPerTransfer;

    /// <summary>
    /// С КАКОЙ ДАЛЬНОСТИ ВООБЩЕ ИСКАТЬ ТРАНСЛОКАТОР, блоков по прямой. Ноль —
    /// не искать никогда: бот ходит только ногами.
    ///
    /// ЖИВАЯ ЖАЛОБА ЗАКАЗЧИКА (01.09): «мы же записываем в нашу постоянную
    /// память пары тл? а то бот побежал вместо тл». Он был прав дважды. Пары и
    /// правда писались, и маршрут по ним считался, и ходить по нему бот умел —
    /// но спрашивали всё это ровно в одном месте: щелчок по карте в окне
    /// управления. Задача, склад, дом, работа звали ноги напрямую, а ноги ходят
    /// по клеткам и про переходы не знают ничего. Эта ручка — тот выключатель,
    /// которым дальняя дорога наконец смотрит на сеть.
    ///
    /// ПОЧЕМУ ЭТО ПОЛИТИКА, А НЕ ЧИСЛО В БИБЛИОТЕКЕ. Порог зависит от того, как
    /// ЖИВЁТ этот бот. Копателю, который весь день ходит по своему карьеру,
    /// сеть не нужна вовсе; торговцу, бегающему между городами, она нужна с
    /// первой же сотни блоков. Библиотека про это не знает ничего и знать не
    /// может — она только считает (<see cref="TrekRules.WorthAskingNet"/>).
    ///
    /// ПОЧЕМУ ПОРОГ ВООБЩЕ ЕСТЬ, а не «спрашивать всегда». Ноги зовут очень
    /// часто: подойти к сундуку, шагнуть к двери, встать на соседнюю клетку.
    /// Считать ради трёх шагов маршрут по всей карте — работа впустую, а строка
    /// про это в журнале на каждый шаг топит собой настоящую беду.
    /// </summary>
    [KnobPlace(Сеть, Title = СетьЗаголовок, About = СетьОписание, Order = 8)]
    public double ИскатьТранслокаторОтБлоков { get; set; } = TrekRules.AskNetFromBlocks;

    // ---------------- добыча с убитых ----------------

    /// <summary>
    /// СВОЙ РАЗДЕЛ ПАНЕЛИ ПОД ДОБЫЧУ С УБИТЫХ. Без него «подбирать выпавшее»
    /// уехало бы в «Работу», «разделывать туши» — в «Безопасность» по слову
    /// «нож», а радиус — во что-нибудь третье: одна человеческая мысль в трёх
    /// ящиках. Заказчик просил про это ОТДЕЛЬНОЙ настройкой, а «отдельная» —
    /// это ещё и «которую видно, не зная, где искать».
    ///
    /// Заголовок и «что внутри» повторены у каждой ручки раздела нарочно:
    /// панель берёт их у первой встреченной (как в «Снаряжении» и «Описи»).
    /// </summary>
    public const string СУбитых = "добыча-с-убитых";

    /// <summary>Заголовок раздела — см. <see cref="СУбитых"/>.</summary>
    public const string СУбитыхЗаголовок = "Добыча: с убитых и своя";

    /// <summary>
    /// Строка «что внутри» для раздела.
    ///
    /// ПРО СВОЮ ВЫЛОМАННУЮ ДОБЫЧУ ЗДЕСЬ СКАЗАНО НАРОЧНО. Ручка
    /// <see cref="ЗаСвоейДобычейНеДальше"/> живёт в этом же разделе (мерка одна
    /// и та же — <see cref="Pickup.TooFarToGo"/>), а строка говорила только про
    /// бой и охоту. Человек, у которого бот уходит из дома за собственной рудой,
    /// искал бы ручку где угодно, только не под заголовком «Добыча с убитых», —
    /// и это ровно та жалоба, с которой начинался разбор настроек: «нефига не
    /// понятно, что делают некоторые».
    /// </summary>
    public const string СУбитыхОписание =
        "что делать после боя, охоты и своей же копки: подбирать ли выпавшее " +
        "из мобов, разделывать ли туши ножом и далеко ли ходить за добычей — " +
        "и за чужой, и за своей выломанной";

    /// <summary>
    /// ПОДБИРАТЬ ВЫПАВШЕЕ ИЗ УБИТЫХ. Прямые слова заказчика: «Нужно подбирать
    /// выпавшие вещи из мобов».
    ///
    /// Речь про то, что падает НА ЗЕМЛЮ в миг смерти: с саранчи — ржавая
    /// шестерёнка и обломки, со звонаря — то же, с рыбы — филе. Ходит за этим
    /// тот же подбор, что и после кирки (второго в проекте нет); эта галочка
