    /// дрифтера.
    ///
    /// ПОЧЕМУ ЭТОГО НЕ ЛОВИЛ НИКТО. Посторожено было ЗАВОДСКОЕ число
    /// (<c>СпасениеНеЖдётTests</c>), а ручка на то и ручка, что её крутят:
    /// приёмка опустила «ПаузаПередВозвратом» в пресете с 1 на 0 — и 139
    /// стендов пресетов, окна и спасения остались зелёными, а бот не сказал ни
    /// слова.
    ///
    /// ЧИСЛО НЕ ПЕРЕПИСАНО СЮДА, А СПРОШЕНО У МЕХАНИЗМА: ход способностей
    /// живёт у <c>BehaviorRunner</c>, и второй его копии в проекте быть не
    /// должно — разойдись они, и граница сторожила бы не то, что надо.
    ///
    /// ПОЛ — ДВА ХОДА, А НЕ ОДИН, И ЭТО НЕ ЗАПАС НА ГЛАЗОК. Ход боя мог
    /// начаться за миг ДО того, как тело освободилось: такой ход тела уже не
    /// возьмёт, и спасение спросит его лишь следующим — то есть через целый
    /// тик. Пауза обязана пережить этот целый тик, а не сравняться с ним;
    /// второй ход — та самая разница между «вровень» и «дольше», и он же
    /// покрывает дрожь потоков.
    ///
    /// ПРАВИЛО ПЕРЕЕХАЛО СЮДА ВМЕСТЕ СО СВОЕЙ РУЧКОЙ 09.09: пол стережёт
    /// «ПаузаПередВозвратом», и оставь мы его у одной роли — четыре остальные
    /// доносили бы паузу без пола, то есть вернули бы ступор себе.
    ///
    /// Возвращает пару: с каким числом идти в механизм и что сказать человеку
    /// (пусто — говорить нечего, число прошло как есть).
    /// </summary>
    /// <param name="заказано">что человек поставил в ручке</param>
    /// <param name="ходСпособностейСекунд">ход цикла способностей, секунд</param>
    public static (double Пауза, string? Жалоба) ПаузаВозвратаБезСтупора(
        double заказано, double ходСпособностейСекунд)
    {
        double пауза = Math.Max(0, заказано);
        double пол = Math.Max(0, ходСпособностейСекунд) * 2;
        if (пауза >= пол)
            return (пауза, null);
        return (пол,
            $"«{nameof(ПаузаПередВозвратом)}» {пауза:0.###} с короче двух ходов " +
            $"способностей ({ходСпособностейСекунд:0.###} с) — беру {пол:0.###} с. " +
            "С паузой короче перебитая работа берёт тело РАНЬШЕ хода боя, и бой " +
            "платит ей полную выдержку: это тот самый ступор, из-за которого " +
            "избитый бот не уходил от дрифтера даже по слову хозяина");
    }

