    //   • Scaffolding.LadderUpAsync — лестница наверх,
    //   • Scaffolding.LadderDownAsync — лестница вниз.
    // Все три спрашивают TempBlocks.MayPlace, а зовут их Scaffolding.GetOutAsync
    // и GetDownAsync — те самые, что VsBot подключает к Movement.ClimbOut и
    // Movement.GetDown. Выход из ямы и спуск с обрыва — общая механика с
    // общими ручками («ВыбиратьсяНаверх», «СпускатьсяСОбрывов»,
    // «ДобыватьМатериалНаСтолб» — все три в этом файле), и у ИИ с MCP
    // «ВыбиратьсяНаверх» заводски ВКЛЮЧЕНА. Уборку же спрашивает ещё и простой
    // (Unfinished.Of → BehaviorIdle), а он есть у всех пяти и доносится отсюда
    // же («ЗакрыватьХвостыВПростое»).
    //
    // НОМЕРА РАЗВЕДЕНЫ С 37 И 38 НА 41 И 42, И ЭТО СКАЗАНО ЧЕСТНО ДО КОНЦА.
    // У Выживальщика пара стояла на 37 и 38, а на 37 у него же стоит
    // «СекундНаШагВСторону» — ничья, поимённо замороженная в
    // ДвеРучкиНаОдномМестеTests. Останься леса на 37, храповик БЫ НЕ ПОКРАСНЕЛ:
    // сосед по номеру — ручка самого Выживальщика, и ничья так и осталась бы
    // его одного. То есть переезд ничего не ломал; но и не чинил.
    //
    // Развели номера потому, что ОБЩЕЙ ручке чужая ничья в наследство не
    // достаётся. Место занято — значит человек, выучивший «третья сверху»,
    // найдёт там соседку, а панель равные номера раскладывает как придётся.
    // 41 и 42 — ближайшие два подряд, свободные у ВСЕХ пяти ролей; пара
    // осталась парой, а замороженный долг убыл на одну строку (34 → 33 у
    // Выживальщика), и это вычеркнуто в самом храповике.
    //
    // Двигать вместо них «СекундНаШагВСторону» было нельзя: она третья в тройке
    // отхода с полотна (35, 36, 37), и рвать тройку ради чужого переезда — та
    // же беда с другого конца.

