    ///
    /// ЖИВОЙ СЛУЧАЙ, дословно (ночь 18.08, заказчик повторил дважды): «зачем
    /// ломать, если у него был выход из дома в виде двери и он мог просто
    /// побежать»; «и снова нет, зачем ломать, если был путь, ломать крайняя
    /// мера же». Журнал 00:41:16–00:41:49: поиск пути ответил «дороги нет», и
    /// следующей же строкой бот полез вверх сквозь стену дома — на ПЕРВОМ
    /// отказе поиска, не сделав ни шагу в обход.
    ///
    /// Отказ собственного поиска — это «я не нашёл», а не «пройти нельзя»:
    /// той же дорогой бот прошёл минутой раньше, открыв дверь. Поэтому ходьба
    /// перебирается до конца, и только потом берётся кирка
    /// (<see cref="Movement.DigForWayIsLastResort"/>). ОТКЛЮЧИТЬ САМО ПРАВИЛО
    /// нельзя ни этой ручкой, ни другой: ноль здесь означает «дальним обходом
    /// не ходить», а не «ломать сразу».
    ///
    /// ЗАСЛОНКА СТОИТ ЗДЕСЬ, А НЕ У ПРОВОДКИ, И ЭТО НЕ ПРИДИРКА. Число у ручки
    /// одно, и хранится оно в одном месте — в ней самой. Гаси описку в проводке
    /// (<c>Math.Max(0, …)</c> при доносе до движения) — и чисел станет ДВА:
    /// окно управления читает саму ручку (<c>RoleKnobs.Of</c>) и показало бы
    /// «−7», а бот в чат сказал бы «выключен (ноль блоков)». В этом проекте
    /// «окно показывает одно, бот делает другое» ловили уже не раз, и лечится
    /// это только так: одно число, одно место.
    /// </summary>
