    /// <summary>
    /// СМАХИВАТЬ ЛИ С ДОРОГИ И С ПРИЦЕЛА НИКЧЁМНУЮ МЕЛОЧЬ: снег, траву, цветок,
    /// папоротник. По умолчанию — ДА.
    ///
    /// ПРЯМОЙ ВОПРОС ЗАКАЗЧИКА (19.08): «а почему он увидел непроходимую
    /// преграду — снег — и решил лезть наверх, а не напрямик сломать и выйти
    /// из дома?» Бот полез НАВЕРХ НА ЧЕТЫРЕ БЛОКА (лестница, столб, ступени) и
    /// всё впустую. В тот же вечер, 21:12, снег восемь раз подряд за четыре
    /// секунды перекрыл ему ЛУЧ до найденного метеорита: «нет прямой
    /// видимости: мешает snowlayer-2».
    ///
    /// ГДЕ ГАЛОЧКА И ПРАВДА РЕШАЕТ (поправлено приёмкой по ассетам игры).
    /// На РОВНОЙ дороге снег бота не держит вовсе: коробка у слоя 0,125…0,25
    /// при шаге тела 0,6, и поиск пути ведёт сквозь снежную клетку. Галочка
    /// решает на ЛУЧЕ (тот самый метеорит), на СТУПЕНИ (занесённая лесенка) и
    /// на дороге — там, где мелочь и правда непроходима (сагуаро, куст).
    ///
    /// ЭТО НЕ «ЛОМАТЬ ЧУЖОЕ» И НЕ КРАЙНЯЯ МЕРА. Снести чужую постройку ради
    /// прохода — совсем другое дело, у него своя ручка
    /// (<see cref="ЛоматьЧужоеРадиВыхода"/>) и своё правило, и эта галочка их
    /// не касается. Здесь только природная мелочь, у которой по РЕЕСТРУ ИГРЫ
    /// нет ни цены, ни времени: игра сама зовёт её заменяемой (под такое не
    /// подкапываются, его затирают, ставя блок), выпадений с неё нет, и
    /// ломается она голыми руками за доли секунды. Чьё это — по-прежнему
