    // ---------------- чужие владения ----------------
    //
    // ЧЕТЫРЕ РУЧКИ, ПРИЕХАВШИЕ 09.09 ОТ ВЫЖИВАЛЬЩИКА. Механизм
    // (<see cref="Claims"/>) заводится КАЖДОМУ боту в самом BotClient, а
    // спрашивают его все, кто сам выбирает клетку: поручение
    // (<c>Errands.MineSourceAsync</c>), наряд за рудой, разведка и память руды.
    // Поручения и очередь задач общие всем живущим ролям — значит и ручки
    // общие, а стояли они у одного копателя: стражнику, продавцу и ИИ окно про
    // чужие приваты не говорило НИ СЛОВА, хотя бот их обходил (закон 1).
    //
    // ЗАВОДСКИЕ ЗДЕСЬ РОВНО ТЕ ЖЕ, ЧТО У МЕХАНИЗМА (500 / 30 мин / 5 мин), и
    // это проверено полем в поле, а не обещано: Claims.KeepAway 500,
    // Claims.Remember 30 мин, Claims.RememberPlayers 5 мин. Значит четырём
    // ролям, у которых этих ручек не было вовсе, переезд не переменил НИ
    // ОДНОГО числа — им лишь стало чем крутить. Разведка волны опасалась
    // обратного («500 запретит стражнику ломать в полукилометре от чужой
    // заявки»); опасение не подтвердилось дважды: числу и так 500, а ломкой
    // распоряжается застава (<c>BreakGuard</c>), которая этих ручек не читает.
    //
    // МЕСТО В ОКНЕ ПРЕЖНЕЕ (20…23) — раскладку этого ящика человек выучил. И
    // ЧЕСТНО ПРО НОМЕР 20: на нём же стоит «НоситьБроню». Ничья эта не новая и
    // не наша — у выживальщика обе ручки жили на двадцатом и до переезда, —
    // но теперь её видят все пять ролей. Двигать ради неё «ДержатьсяОтЧужого»
    // значило бы увезти главную ручку из-под руки человека, который её выучил;
    // сказано об этом вслух здесь и в отчёте волны, а развести номера должен
    // тот, кто возьмётся за раскладку окна целиком.

    /// <summary>
    /// На сколько блоков держаться от чужих заявок и чужого жилья, когда бот
    /// сам ищет, где работать. 0 — не держаться вовсе (проверка выключается
    /// целиком).
    ///
    /// Границы заявок сервер присылает сам, все и сразу (пакет 75) — тем же
    /// списком, по которому разметка приватов рисуется на карте живому игроку.
    ///
    /// ЧТО ЭТА РУЧКА НЕ ДЕЛАЕТ, И ЭТО ВАЖНЕЕ ТОГО, ЧТО ОНА ДЕЛАЕТ. Она про
    /// АВТОПОИСК места («где копать», «где взять доску»), а не про запрет
    /// ломать: удар по чужому блоку судит застава (<c>BreakGuard</c>) и ручка
    /// «ЛоматьЧужоеРадиВыхода». Роль, которая ничего не ищет сама (стражник на
    /// посту, продавец за прилавком), этого числа не почувствует вовсе, пока
    /// ей не дадут поручение.
    ///
    /// ЧИСЛО ЗДЕСЬ ПРО ЗАЯВКИ. Для ПОДМЕЧЕННОГО САМИМ (отказ сервера, запертая
    /// дверь, чужой сундук, встреченный игрок) у механизма своя, куда более
    /// короткая мерка — <c>Claims.KeepAwaySeen</c>, 32 блока, — и ручки у неё
    /// нет нарочно: примета это догадка, и пятьсот блоков вокруг неудачно
    /// поставленного факела выключили бы работу вместе со складом и домом.
    /// </summary>
    [KnobPlace("безопасность", Order = 20, Main = true)]
    public int ДержатьсяОтЧужого { get; set; } = 500;

    /// <summary>
    /// Сколько минут помнить подмеченное самим: отказ сервера на слом или
