    /// </summary>
    [KnobPlace("безопасность", Order = 22)]
    public int ПомнитьИгроковМинут { get; set; } = 5;

    /// <summary>
    /// Считать чужим местом и то, где бот видел живого игрока. По умолчанию
    /// нет: при 500 блоках один прохожий выгоняет бота с половины карты.
    ///
    /// ВАЖНО: людей бот замечает в одном-единственном месте — там же, где
    /// здоровается. Значит эта настройка работает, только пока включено
    /// «МахатьИгрокам»; если это не так, бот скажет об этом в журнал, а не
    /// промолчит.
    ///
    /// ЧТО ЭТО СТОИТ РОЛИ, СТОЯЩЕЙ НА МЕСТЕ. Место человека помнится КОРОТКОЙ
    /// меркой примет (<c>Claims.KeepAwaySeen</c> — 32 блока), а не пятьюстами.
    /// Стражнику у ворот этого хватает, чтобы каждый прохожий на пять минут
    /// объявлял его собственный пост непригодным для работы: он там стоит, и
    /// круг ложится ровно на него. Поэтому «нет» здесь — не осторожность ради
    /// осторожности, а разобранный случай.
    ///
    /// СПОРА С ЛИЧНЫМ РАЗБОРОМ ЧУЖИХ У СТРАЖНИКА ЗДЕСЬ НЕТ, И ЭТО ПРОВЕРЕНО.
    /// «ЧужиеНики», «Пост» и «ОхранятьВРадиусе» отвечают на обратный вопрос —
    /// кого НЕ ПУСКАТЬ на свою землю, — и ходят в свою способность
    /// (<c>BehaviorGuardGate</c>). Эта ручка отвечает «куда МНЕ не соваться» и
    /// ходит в чужие владения. Одного механизма на двоих нет, и второй копии
