    /// </summary>
    [KnobPlace("безопасность", Order = 23)]
    public bool ИзбегатьИгроков { get; set; }

    /// <summary>
    /// НИЖЕ КАКОЙ ДОЛИ СЫТОСТИ БРОСАТЬ ПОГОНЮ И ИДТИ ЕСТЬ: 0,25 — четверть.
    /// Гнаться за обидчиком, когда сам умираешь, — плохая идея.
    ///
    /// Библиотека прямо отдаёт это число роли («роль может поднять его сторожу
    /// и опустить охотнику», см. <see cref="BehaviorAttackHostiles.VitalNeedsFraction"/>),
    /// а повернуть его до сегодня было НЕЧЕМ: ручки не существовало ни у одной
    /// роли, и число сидело в библиотеке одно на всех. Приёмка доказала это
    /// подменой — стёрла чтение ручки, и весь прогон остался зелёным.
    /// </summary>
    [KnobPlace("безопасность", Order = 24)]
    public double БроситьПогонюПриСытостиНиже { get; set; } = 0.25;

    /// <summary>
    /// КОГДА НОСИТЬ БРОНЮ — И, ТЕМ САМЫМ, КОГДА ЕЁ СНИМАТЬ.
    ///
    /// «Никогда» — не надевать вовсе; «ВБою» — только на время размена ударов;
    /// «ПокаРядомОпасно» — пока тварь поблизости, свежа обида или идёт временная
    /// буря; «Всегда» — не снимать.
    ///
    /// ЖИВОЙ СЛУЧАЙ ЗАКАЗЧИКА: «не снимал броню после шторма и опасности». Бот
    /// восемь минут просидел в укрытии среди дрифтеров, а снятие висело на самой
    /// узкой ветке боя — «врагов не видно вовсе», — и не сработало ни разу.
    /// Решений про броню в библиотеке было ТРИ разных (надеть в бою, снять после
    /// боя, снять убегая), и повернуть их роль не могла ни одним способом:
    /// ручки не существовало вовсе. Теперь решение одно
    /// (<see cref="ArmorKit.NeedArmor"/>), и оно здесь.
    ///
    /// ЧЕГО ЭТО СТОИТ, В ЧИСЛАХ ИГРЫ. Броня отнимает скорость и добавляет
    /// голода: полный комплект лат — это −42 % скорости и +72 % расхода еды
    /// (walkSpeed −0,14 и hungerrate +0,24 на каждую из трёх частей, ассеты
    /// 1.22.6 armor.json; складывает их ModSystemWearableStats из
    /// VSSurvivalMod.dll). Кольчуга дешевле впятеро. Поэтому «Всегда» —
    /// осознанный выбор для сторожа на посту, а не «пусть будет».
    /// </summary>
    [KnobPlace("безопасность", Order = 20)]
    public WearArmor НоситьБроню { get; set; } = WearArmor.ПокаРядомОпасно;

    /// <summary>
    /// КОГДА НОСИТЬ ЩИТ — И, ТЕМ САМЫМ, КОГДА ЕГО УБИРАТЬ:
    /// «Никогда», «ВБою», «ПокаРядомОпасно», «Всегда».
    ///
    /// Слова названы ЗДЕСЬ, а не отосланы к соседней ручке, и это не
    /// многословие. В окне управления человек выбирает из списка, а В ПРЕСЕТ
    /// он пишет слово РУКОЙ — и написанное мимо перечисления бот отвергает.
    /// Ровно на этом уже горели дважды: подпись «Мстить» называла
    /// «Never / Nearby / Chase», которых в перечислении нет с тех пор, как его
    /// перевели на русский, и человек, поверивший подписи, получил бы отказ.
    ///
    /// Шкала та же, что у брони, и правило под ней ТО ЖЕ САМОЕ
    /// (<see cref="ArmorKit.NeedGear"/>), а не второе такое же: заказчик просил
    /// щит, который «надевается только в момент угрозы как и броня».
    ///
    /// ГДЕ ОН ЖИВЁТ. Щит — НЕ броня: в игре это обычный предмет в ЛЕВОЙ РУКЕ
    /// (storageFlags 257 = General|Offhand, слот 11 хотбара) — в той самой, где
    /// у бота фонарь. Значит фонарь и щит ДЕРУТСЯ за один слот, и спор решён
    /// явно: при угрозе рука у щита (разбор и цена обеих сторон — в
    /// <see cref="Shielding.WhoNeedsOffHand"/>), а перевернуть решение можно
    /// ручкой «ВТемнотеФонарьВажнееЩита».
    ///
    /// ЧЕГО ЭТО СТОИТ, В ЧИСЛАХ ИГРЫ. Скорости щит не отнимает вовсе — в
    /// отличие от лат. Зато ЛЮБОЙ предмет в левой руке даёт +20 % расхода еды
    /// (<c>InventoryPlayerHotbar.OffHandHungerPenalty = 0.2f</c>), и он же
    /// занимает руку под фонарь. Что даёт: грубый щит списывает 3 хп с удара и
    /// 3 со стрелы, черностражий — 5,5 и 12, при полном запасе здоровья в 15.
    /// Срабатывает не всегда: просто в руке — в 20 % случаев, с поднятым
    /// щитом — в 90 % (см. «ПодниматьЩитВБою»).
    ///
    /// «Всегда» — осознанный выбор для сторожа на посту; для копателя это
    /// круглосуточная треть лишнего хлеба и рука без фонаря.
    /// </summary>
    [KnobPlace("безопасность", Order = 40)]
    public WearArmor НоситьЩит { get; set; } = WearArmor.ПокаРядомОпасно;

    /// <summary>
    /// ПОДНИМАТЬ ЩИТ В РАЗМЕНЕ УДАРОВ.
    ///
    /// «Поднять» в игре значит ровно одно — ЗАЖАТЬ ПРИСЕД. Единственная строка
    /// защиты, которая на что-то смотрит, такая:
    /// <c>(Controls.Sneak &amp;&amp; Attributes["aiming"] != 1) ? "active" : "passive"</c>,
    /// и разница между этими словами — шанс перехвата 0,9 против 0,2. То есть
    /// поднятый грубый щит спасает в среднем 2,7 хп с удара вместо 0,6.
    /// Анимация поднятого щита — косметика клиента и не значит НИЧЕГО.
    ///
    /// ЧЕМ ПЛАТИМ, ЧЕСТНО: на присяде тело идёт 0,35 обычной скорости.
    /// Поэтому щит поднимается ровно на время размена вплотную и опускается
    /// перед отскоком и погоней — иначе «ударил и отскочил» превратилось бы в
    /// топтание на месте. Выключите, если ваш бот больше бегает, чем стоит.
    ///
    /// И ЕЩЁ ОДНО, ЧЕГО НЕ ОБОЙТИ НИКОМУ: НАТЯГ ЛУКА САМ СБРАСЫВАЕТ ЩИТ В
    /// «passive» (то же <c>aiming != 1</c>). Стрелять и держать щит поднятым
    /// одновременно игра не даёт — ни боту, ни живому игроку.
    /// </summary>
    [KnobPlace("безопасность", Order = 41)]
    public bool ПодниматьЩитВБою { get; set; } = true;

    /// <summary>
    /// В ТЕМНОТЕ ФОНАРЬ ВАЖНЕЕ ЩИТА.
    ///
    /// РУКА ОДНА, И ЭТО НЕ НЕДОСМОТР ИГРЫ: и факел, и щит живут в слоте 11
