    /// фонаря, а щит ждёт в сумке — и об этом будет сказано в журнал, а не
    /// молча.
    /// </summary>
    [KnobPlace("безопасность", Order = 42)]
    public bool ВТемнотеФонарьВажнееЩита { get; set; }

