    /// (aimingRandPitch/aimingRandYaw синхронизируются на клиент) — вычесть их
    /// и попадать всегда технически можно, и это ровно тот чит, которого мы не
    /// делаем: живой игрок получает те же числа и воспользоваться ими не может.
    /// Что бот делает честно: считает падение стрелы (на 20 бл она проседает
