    ///
    /// ЗАЧЕМ ЭТА РУЧКА ЕСТЬ. Разброс бот считал и печатал давно, но решения по
    /// нему не принимал: с восьми блоков по дрифтеру и с тридцати четырёх по
    /// нему же он стрелял ОДИНАКОВО охотно, хотя во втором случае промахивался
    /// четыре раза из пяти. Теперь доля считается числом — по конусу разброса,
    /// по дальности и по КОРОБКЕ ЦЕЛИ из реестра сервера (дрифтер 0,6 бл
    /// шириной, волк 1,2 — это вдвое разный шанс с одного и того же места), — и
