    /// ворот стрелы девать некуда, он стоит у сундука с ними: ему и 0,15 не
    /// жалко, лишь бы отогнать. Копателю в шахте каждая стрела — это ходка
    /// наверх за кузницей, и ему разумно 0,45: не попал — подойди и ударь
