    /// дороже любой стрелы. Об этом говорится в журнал той же строкой.
    ///
    /// РАЗМЕР ЦЕЛИ СЕРВЕР НЕ НАЗВАЛ (реестр типов не пришёл, тип незнаком) —
    /// порог не спрашивается, бот стреляет и честно говорит, почему счёта не
