    /// </summary>
    [KnobPlace("безопасность", Order = 48)]
    public double СтрелятьПриШансеНеНиже { get; set; } = 0.3;

    /// <summary>
    /// С КАКОГО РАССТОЯНИЯ ВРАГ СЧИТАЕТСЯ НАПАДАЮЩИМ — то есть когда бот
    /// берётся за оружие сам, ещё не получив удара. Ближе — бой, дальше —
