    ///
    /// ПОЧЕМУ ЭТО РУЧКА ТОЛЬКО ТЕПЕРЬ. Число стояло ЖЁСТКО в трёх ролях
    /// (<c>SurvivorRole</c>, <c>GuardRole</c>, <c>HelperRole</c> — везде 4) и не
    /// встречалось НИ В ОДНОМ пресете: для заказчика его не существовало. Ровно
    /// тот случай, на котором проект уже горел 23.08.
    ///
