    /// ближе, чем позволено стрелять. Живьём 26.08 это повторилось в каждой
    /// естественной стычке («он в 2,4 бл — ближе ручки „СтрелятьНеБлижеЧем“
    /// (5)»), и единственный выстрел за смену вышел только после того, как
    /// человек серверной командой отодвинул цель на 12 блоков.
    ///
    /// ЗАВОДСКОЕ ЧИСЛО НЕ ТРОНУТО (4), И ЭТО НАРОЧНО. Расширить оборонительный
    /// радиус — значит начинать больше драк, а такое решение принимает человек,
    /// а не сборщик волны. Бот теперь ГОВОРИТ ОБ ЭТОМ ВСЛУХ, когда два числа
    /// друг другу мешают, и называет обе ручки — вместо того чтобы молча
    /// печатать «слишком близко» в каждой стычке.
    ///
    /// Отдельно от этого работает МЕСТЬ: получив настоящий удар, бот отвечает
