    /// </summary>
    [KnobPlace("безопасность", Order = 49)]
    public double ВступатьВБойСРасстояния { get; set; } = 4;

    /// <summary>
    /// ВСТРЕЧАТЬ ЛУКОМ ИЗДАЛЕКА, А НЕ ПОДПУСКАТЬ ВПЛОТНУЮ.
    ///
    /// ЖАЛОБА ЗАКАЗЧИКА ДОСЛОВНО: «На дальних мобов снова не агрится, просто
    /// броню надевает, а нужно сделать интеллектуально: допустим если есть лук,
    /// то логично расстрелять моба».
    ///
    /// ЧТО ЭТА РУЧКА ДЕЛАЕТ. Пока лук и стрелы при себе (и «СтрелятьИзЛука»
    /// стоит), враг берётся в бой с «СтрелятьНеДальше», а не с
    /// «ВступатьВБойСРасстояния»: бить его начнут оттуда, значит и встречать
    /// надо оттуда. Это и есть ответ на спор двух чисел, из-за которого лук в
    /// обычной стычке молчал: 4 бл оборонительного радиуса меньше пяти, с
    /// которых лук вообще стреляет, — и к тому мигу, как враг попадал в список
    /// целей, он был уже слишком близко.
    ///
    /// НЕТ ЛУКА — НИЧЕГО НЕ МЕНЯЕТСЯ: остаётся «ВступатьВБойСРасстояния», и
    /// дальнего врага бот встречает прежним способом — сходится ногами внутри
    /// стычки и мстит обидчику в радиусе «РадиусМести». Второго способа бить
    /// дальних тут не заведено.
    ///
    /// СНИМАЮТ ЭТУ РУЧКУ ТАМ, ГДЕ СТРЕЛЫ ДОРОГИ ИЛИ ШУМ НЕ НУЖЕН: бот перестаёт
    /// начинать дальние стычки и ведёт себя как до 26.08.
    /// </summary>
    [KnobPlace("безопасность", Order = 50, Main = true)]
    public bool ВстречатьЛукомИздалека { get; set; } = true;

    /// <summary>
    /// ЗОВУЩИХ ПОДМОГУ БИТЬ ИЗДАЛИ, НЕ ПОДХОДЯ.
    ///
    /// Заказчик: «луком предпочтительно, если есть, с далека убивать колокола».
    /// ПОЧЕМУ ИЗДАЛИ — спрошено у самой игры, а не придумано: у колокола
    /// СВОЕГО УДАРА НЕТ ВОВСЕ (в его задачах нет ни meleeattack, ни seekentity),
    /// зато задача «bellalarm» на шум рядом каждые 1…5 с вызывает до ШЕСТИ
    /// глубинных тварей в двенадцати блоках вокруг — drifter-deep,
    /// drifter-tainted, drifter-corrupt, shiver-deep, bowtorn-deep,
    /// locust-corrupt. Стоять рядом с ним и махать мечом — значит драться со
    /// всеми, кого он успеет позвать, пока с него сходят сто хп.
    ///
    /// КОГО СЧИТАТЬ ТАКИМ — РЕШАЕТ РЕЕСТР СЕРВЕРА, А НЕ СПИСОК ИМЁН: бот
    /// спрашивает КЛАСС сущности (у колокола это «EntityBell» — класс самой
    /// игры, заведённый ровно под сирену тревоги). Модовый колокол попадёт сюда
    /// сам; переименованный — тоже.
    ///
    /// БЕЗ ЛУКА РУЧКА МОЛЧИТ: держаться поодаль, не имея чем бить оттуда, —
    /// это «стою и смотрю», а не бой. Тогда бот сходится как со всеми.
    /// </summary>
    [KnobPlace("безопасность", Order = 51)]
    public bool ЗовущихПодмогуБитьИздали { get; set; } = true;

    /// <summary>
    /// ДРАТЬСЯ ТОЛЬКО С ТЕМИ, КТО ДО МЕНЯ ДОЙДЁТ.
    ///
    /// Заказчик дословно: «не имеет смысл агриться на врагов за стенами дома,
    /// если двери закрыты». Так и было: тварь снаружи ВИДНО через окно, а
    /// «что между нами» бот мерил лучом — луч сквозь окно проходит, преграды
    /// нет, и бот бросал работу, надевал броню («42 % скорости и 72 % лишнего
    /// голода») и лез к ней. В журнале это и есть «бежит в окно и дерётся попой».
    ///
    /// ЧТО ЭТА РУЧКА ВКЛЮЧАЕТ. Врага меряют не расстоянием и не взглядом, а
    /// вопросом «есть ли У НЕГО дорога КО МНЕ»: тот же поиск пути, которым
    /// ходит сам бот, только закрытая дверь в нём — глухая стена. Так оно и в
    /// игре: дверь поворачивает только игрок, а поиск пути тварей про двери не
    /// знает вовсе и меряет проходимость настоящими коробками коллизий.
    ///
    /// ЧЕГО ОНА НЕ ЗАПРЕЩАЕТ (и это оговорено заказчиком отдельно):
    /// <list type="bullet">
    /// <item>ВЫСТРЕЛ ИЗ ОКНА. Живой игрок так может, и бот может: отказ
    /// касается только ног. Стрелять сквозь блоки лук и так отказывается сам;</item>
    /// <item>ОТВЕТ НА УДАР. Он меня ударил — значит дошёл, что бы ни думал
    /// поиск пути: дверь мог открыть человек, тварь могла оказаться летающей.
    /// Тогда бой идёт как прежде, со всеми числами;</item>
    /// <item>месть обидчику и оборону вплотную — вплотную вопрос о дороге снят.</item>
    /// </list>
    ///
    /// СНИМАЮТ ЕЁ ТАМ, где поиск пути дорог или миру не верят (чужой сервер,
    /// мод с летающими тварями): тогда бот меряет одним лучом, как до 28.08.
    /// </summary>
    [KnobPlace("безопасность", Order = 52)]
    public bool ДратьсяСТемиКтоДоМеняДойдёт { get; set; } = true;

    /// <summary>
    /// СТРЕЛЯТЬ ЛИ В ТОГО, КОМУ ДО МЕНЯ НЕ ДОЙТИ. Заводское — НЕТ.
    ///
    /// ЗАЧЕМ ОНА ЕСТЬ И ПОЧЕМУ ЗАВОДСКОЕ ИМЕННО «НЕТ». Заказчик написал: «не
    /// имеет смысл агриться на врагов за стенами дома, если двери закрыты».
    /// Соседняя ручка запрещает ХОДИТЬ к такому врагу, а вот выстрел из окна
    /// живому игроку доступен — и пока это «доступен» стояло в библиотеке без
    /// спроса, выходило хуже прежнего: у боя с недостижимым врагом цена ноль,
    /// оценка сто, у «занимаюсь своим» тоже сто, а при равных побеждает драка.
    /// Бот с луком бросал работу, забирал тело и обстреливал каждого видимого
    /// в окно дрифтера, пока не кончатся стрелы. Ровно та жалоба, только сбоку.
    ///
    /// КОМУ ВКЛЮЧАТЬ: стражнику на стене, лучнику у бойницы — тому, чья работа
    /// и есть отстрел. Цена включения: бот бросает дело ради каждого, кого
    /// видит и достаёт стрелой, и тратит на него стрелы.
    ///
    /// СКВОЗЬ БЛОКИ ЭТА РУЧКА НЕ СТРЕЛЯЕТ НИ ПРИ КАКОМ ЗНАЧЕНИИ: там своя
    /// мерка — луч, и лук отказывается сам («между нами debarkedlog-oak-ud»).
    /// </summary>
    [KnobPlace("безопасность", Order = 53)]
    public bool СтрелятьВТехКтоДоМеняНеДойдёт { get; set; }

    /// <summary>
    /// СКОЛЬКО КЛЕТОК ВОЗДУХА ОБОЙТИ, РЕШАЯ «ЗАПЕРТ ЛИ Я». Заводское — 8000.
    ///
    /// ЧТО РЕШАЕТ ЭТО ЧИСЛО. Бот обводит воздух вокруг себя, пока тот не
    /// упрётся в стены и закрытые двери. Замкнулось — значит внутрь хода нет
    /// никому, и тот, кто снаружи, до бота не дойдёт: бот занимается своим
    /// делом. Не замкнулось за это число клеток — ответ «не знаю», и бот
    /// считает врага опасным. То есть числом двигается граница между «не
    /// связываюсь» и «дерусь», а не одна лишь скорость.
    ///
    /// ЦЕНА ЗДЕСЬ МАЛЕНЬКАЯ, И ЭТО ГЛАВНАЯ РАЗНИЦА С ПРЕЖНЕЙ МЕРКОЙ. Раньше
    /// здесь стоял ПОИСК ПУТИ за тварь, и один исчерпанный потолок в 8000
    /// клеток стоил около 0,7 с — на каждого врага. Обход воздуха на те же
    /// 8000 клеток — это восемь тысяч вопросов «сплошная ли клетка», доли
    /// миллисекунды, и он ОДИН на всех врагов сразу: стены вокруг меня не
    /// зависят от того, кто стоит снаружи.
    ///
    /// Мало ставить нельзя, но иначе, чем прежде: маленькое число не даст
    /// области замкнуться даже в комнате, ответом станет вечное «не знаю», и
    /// бот будет драться со всеми — то есть вернётся к поведению до 28.08.
    /// </summary>
    [KnobPlace("безопасность", Order = 54)]
    [KnobWasNamed("СколькоКлетокСмотретьПроЧужуюДорогу")]
    public int СколькоКлетокСмотретьПроЗапертоеМесто { get; set; } = 8000;

    // ЗАПАСА СТРЕЛ ОТДЕЛЬНОЙ РУЧКОЙ ЗДЕСЬ НЕТ, И ЭТО СНЯТО НАРОЧНО (закон 2).
    //
    // Стояли две: «ДержатьСтрел» (неподвижное число) и «КакиеСтрелыДержать»
    // (конкретный вид, заводское arrow-flint). Обе делали ровно то же, что
    // «ЗапасПоРасходу» строкой «arrow к bow», только хуже:
    //   • число неподвижное — а заказ был дословно «чтобы бот сам понимал,
    //     чего ему не достаёт», то есть по РАСХОДУ, а не «64 всегда»;
    //   • вид выбирался руками — а «что именно делать под род» уже решает
    //     Stock.WhatToMake/PlanFor по реестру сервера;
    //   • жили они в разделе «Безопасность», а запас по расходу — в
    //     «Снаряжении»: человек получал ДВЕ настройки запаса стрел в двух
    //     разных местах окна и не знал, какая из них главная;
    //   • в пресете копателя стояло «СтрелятьИзЛука: true» при «ДержатьСтрел: 0»
    //     — то есть заказчик, запускающий --preset digger, стрелял подобранным
    //     и не пополнял НИКОГДА.
    // Сам спор механизм ловил и говорил вслух («просят двое»), но правильный
    // ответ на спор — убрать одного, а не разнимать их каждый тик.

    /// <summary>
    /// НА СКОЛЬКО БЛОКОВ СЧИТАТЬ, ЧТО ОТОРВАЛСЯ. Уйти — значит уйти ДАЛЬШЕ хотя
    /// бы на столько: без этого числа стрелок с двадцати блоков (порог отрыва —
    /// восемнадцать) давал «бежать ноль блоков», и побег выходил бесплатным на
    /// бумаге, а на деле не начинался.
    ///
    /// Больше — бот уходит дальше и надёжнее, но дороже платит временем и
    /// брошенным местом; меньше — отрывается коротко и чаще возвращается.
    /// </summary>
    [KnobPlace("безопасность", Order = 25)]
    public double ОтрыватьсяНеБлижеЧемНа { get; set; } = CombatPlan.DefaultFleeGainAtLeast;

    // ---------------- когда бежать и чем закрыться ----------------
    //
    // ДВЕ РУЧКИ ПЕРЕЕХАЛИ СЮДА 08.09 ОТ ВЫЖИВАЛЬЩИКА. Половина семьи была тут
    // и раньше: порог отрыва («ОтрыватьсяНеБлижеЧемНа», номер 25 прямо выше),
    // цена ухода (13), цена закладывания (14) и радиус самообороны
    // («ВступатьВБойСРасстояния», 49) — общие. А «с какого расстояния вообще
    // начинать побег» и «закладываться ли, когда загнали» оставались у одной
    // роли, хотя бой (BehaviorAttackHostiles) собирается КАЖДОМУ боту: у
    // стражника, продавца и ИИ эти два решения принимала библиотека, и
    // повернуть их человеку было нечем.
    //
    // ПОЧЕМУ НОМЕРА НЕ ПРЕЖНИЕ (БЫЛО 11 И 12) — ЕДИНСТВЕННЫЙ СЛУЧАЙ ВО ВСЕЙ
    // ЭТОЙ ВОЛНЕ, И ОН НАЗВАН ВСЛУХ. В «безопасности» одиннадцатый и
    // двенадцатый номера здесь ЗАНЯТЫ, причём дважды каждый:
    // «ПробоватьКостёрСноваЧерезМин» (11, главная) с «МолчатьНеДольшеСек» (11)
    // и «ГретьсяДоТемпературы» (12, главная) с «ЛоматьЧужоеРадиВыхода» (12).
    // Приехав со старыми номерами, пара разошлась бы: панель равные номера
    // раскладывает как придётся (KnobHelp.PlaceOf — при равном порядке строй
    // держит место объявления), и человек искал бы «закладываться в углу»
    // между костром и чужой стеной. Это дословно та беда, из-за которой
    // соседний куст ушёл на 26…29 («две ручки с одним номером панель
    // раскладывала как придётся», см. «УходитьПриНизкойСтабильности»).
    //
    // ПОЧЕМУ ИМЕННО 36 И 37. Во-первых, ПАРА ОСТАЛАСЬ ПАРОЙ: номера соседние,
    // как были 11 и 12, — «бежать» и «закрыться» человек читает вместе.
    // Во-вторых, это ближайшие свободные ДВА ПОДРЯД во всём разделе: 13…25
    // заняты ценами боя, отступлением, местью и отрывом сплошь, 26…35 — уходом
    // от нестабильности, весами и огнём, 40…54 — щитом, луком и «кого бить».
    // 36 и 37 лежат ровно перед боевым кустом 40…54 — то есть пара встала не
    // «куда влезло», а перед той самой роднёй, вместе с которой её крутят.
    // В-третьих, свободны они у ВСЕХ ПЯТИ ролей, а не только здесь: у
    // выживальщика в «безопасности» стоят 1, 10, 20…23, у продавца — 1, у
    // роли на нейросети — 40, у стражника и MCP своих чисел в этом разделе
    // нет вовсе. Двигать чужие выученные номера, чтобы освободить 13…25,
