    /// <summary>
    /// СКОЛЬКО СЕКУНД ПОМНИТЬ, ЧТО ОТСЮДА ТУДА НЕ ДОЙТИ. Ноль — не помнить
    /// вовсе, спрашивать дорогу заново на каждый вопрос.
    ///
    /// ЖИВОЙ СЛУЧАЙ (журнал 16.08, 20:30:06–20:32:48). Подбор целился в камень
    /// на дне ямы, движение честно отвечало «не дойти» — и через секунду его
    /// спрашивали о том же. За две с половиной минуты: 15 полных походов на
    /// ПЯТЬ разных клеток, 363 строки в журнале и 45 раз подряд одна и та же
    /// строка «эту клетку отсюда я уже не смог достать … с назад». Бот сам
    /// говорил «второй раз перебирать то же самое незачем» — и шёл перебирать.
    ///
    /// ПОЧЕМУ ЧИСЛО МАЛЕНЬКОЕ. Это не приговор клетке, а защита от повтора
    /// одного и того же расчёта в одну и ту же секунду: память и так забывается
    /// сама, стоит боту сдвинуться с места или миру перемениться по факту от
    /// сервера. Больше минуты ставить незачем — за минуту в мире меняется
    /// слишком многое; меньше пяти секунд возвращает тот самый круг.
    ///
    /// Число одно на обе памяти движения (отказ целого похода и отказ перебора
    /// обходов) — так они и заведены в библиотеке, и разводить их двумя ручками
    /// значило бы дать одному смыслу разъехаться на два числа.
    /// </summary>
    [KnobPlace(Путь, Title = ПутьЗаголовок, About = ПутьОписание, Order = 33)]
    public double ПомнитьОтказДорогиСекунд { get; set; } = 20;

    // ---------------- проводка ----------------

    /// <summary>
    /// Роль собрана — можно доносить общие ручки до способностей.
    /// Зовётся ОДИН раз, в конце <c>Configure</c> роли.
    ///
    /// Заодно подписываемся на вход в мир: перевода игровых координат в мировые
    /// до входа НЕ СУЩЕСТВУЕТ (сдвиг берётся из точки спавна, а она приходит
    /// пакетом уже в мире), поэтому дом доносится ещё раз после входа.
    /// </summary>
    protected void ОбщиеНастройкиГотовы(VsBot bot)
    {
        бот = bot;

        // «!ДОМ [ТУТ]» — У ВСЯКОЙ ЖИВУЩЕЙ РОЛИ, А НЕ У ОДНОГО КОПАТЕЛЯ.
        //
        // Ручка «Дом» общая, записывающий общий, ответ словами общий — а СЛОВО,
        // которым её крутят, сидело внутри копателя. Живьём это стоило вот
        // чего: готовый бот стражника велит заполнить «Дом» (иначе не будет
        // «кушать со склада»), а сказать «!дом тут» стражнику нельзя — команды
        // у него нет. Тот же файл трижды советовал команды, которых у роли нет,
        // и это пришлось вычищать как враньё.
        bot.Commands.Add("дом", "дом [тут] — где мой дом и что с возрождением", async a =>
        {
            if (a.Text.Trim() is "тут" or "здесь")
            {
                // ЧАТ МЕНЯЕТ САМУ НАСТРОЙКУ РОЛИ, а не мимо неё. Дом, взятый
                // словом, обязан быть виден в панели и обязан пережить
                // следующий поворот любой соседней ручки — иначе «где дом»
                // живёт в двух местах и они разъезжаются молча
                await a.ReplyAsync(ЗапомнитьДомЗдесь(bot) + ". " +
                                   (ОтмечатьДом
                                       ? "Точку возрождения поставлю временной шестерёнкой — она при этом тратится"
                                       : "Точку возрождения не ставлю: «ОтмечатьДом» выключено"));
                return;
            }
            string где = Дом is { } д ? д.ToString() : "не задан";
            string точка = bot.Sleeping.RespawnPoint is { } с
                ? $"({bot.PlayerCoords(с.X, с.Y, с.Z)})"
                : "сервер её не присылал";
            await a.ReplyAsync($"Дом: {где}; точка возрождения по словам сервера: {точка}; " +
                               bot.Deaths.Report());
        });

        // «!СКЛАД [ТУТ]» — ТОЖЕ У ВСЯКОЙ ЖИВУЩЕЙ РОЛИ.
        //
        // Слово переехало сюда вслед за самой ручкой «Склад» и по той же
        // причине, по какой сюда переехало «!дом»: наш собственный каталог
        // ролей обещает стражнику «сундук с едой рядом с постом — или скажите
        // в чате „!склад тут“» (Roles.ТолькоНаши), а команды этой у стражника
        // не было — она сидела внутри копателя. Обещание, которого роль не
        // держит, — то же враньё, что и молчаливый отказ.
        bot.Commands.Add("склад", "где склад / взять сундуки рядом под склад", async a =>
        {
            if (a.Text.Trim() is "тут" or "здесь")
            {
                // СЛОВО ЧЕЛОВЕКА: он стоит у своих сундуков — меряем тем, что
                // видно ему самому, и запоминаем надолго
                await a.ReplyAsync(ВзятьСкладЗдесь(bot, СундукиВокругВРадиусе, запомнить: true));
                return;
            }
            // Отказ и состав склада спрашиваем у самого склада: он знает, чем
            // каждая точка плоха («в … стоит rock-granite, а не сундук»), и
            // это не то же самое, что перечислить координаты
            await a.ReplyAsync(bot.Depot.Known
                ? "Склад: " + string.Join("; ", bot.Depot.Verify().Select(p => p.Reason)) +
                  $"; мест в сумке {bot.Self.FreeCarrySlots()}"
                : bot.Depot.WhyNoDepot() + ". Поставьте сундук рядом и скажите «!склад тут»");
        });

        // ЧУЖИЕ ЛЮДИ КАК ЧУЖОЕ МЕСТО — У ВСЯКОЙ ЖИВУЩЕЙ РОЛИ, А НЕ У ОДНОГО
        // КОПАТЕЛЯ. Механизм умеет запоминать (Claims.NotePlayer), но КОГДА его
        // звать — решает роль: при 500 блоках один прохожий выгонит бота с
        // половины карты, поэтому по умолчанию не зовём вовсе.
        //
        // МЕСТО, ГДЕ БОТ ЗАМЕЧАЕТ ЛЮДЕЙ, У НЕГО ОДНО — то же, где он
        // здоровается (BehaviorGreetPlayers): второго обхода людей в боте нет,
        // и заводить его ради этой галочки значило бы платить лучом зрения
        // дважды за один и тот же взгляд. Отсюда и оговорка в самой ручке, и
        // жалоба в журнал, когда приветствие выключено.
        //
        // ПОДПИСКА ЗДЕСЬ, А НЕ В ДонестиОбщее: то зовётся на КАЖДЫЙ поворот
        // любой ручки, и подписка копилась бы там десятками — один встреченный
        // человек ложился бы в память двадцать раз. Читается ручка живьём, в
        // теле обработчика, поэтому снятая галочка действует сразу же
        if (bot.Behaviors.Get<BehaviorGreetPlayers>() is { } встречи)
            встречи.OnMet += (встреча, _) =>
            {
                if (ИзбегатьИгроков)
                    bot.Claims.NotePlayer(
                        new BlockPos(встреча.X, встреча.Y, встреча.Z), встреча.Name);
            };

        bot.OnJoined += Донести;
        Донести();
    }

    /// <summary>
    /// ЕДИНСТВЕННАЯ ДВЕРЬ, ЧЕРЕЗ КОТОРУЮ РОЛЬ ДОНОСИТ СВОИ РУЧКИ ДО МЕХАНИЗМОВ.
    /// Звать надо ЕЁ, а перекрывать — <see cref="ДонестиОбщее"/>.
    ///
    /// ЗАЧЕМ ДВЕРЬ ОТДЕЛЬНО ОТ ТЕЛА. Всё, что роль кладёт в поля бота, обязано
    /// лечь в её след (<see cref="СледРоли"/>) — иначе при смене роли оно
    /// останется на НОВОМ боте чужой настройкой, и смена честно скажет
    /// «вернулось всё», не вернув ничего. Приёмка поймала это на живом: роль
    /// пишет поле из <c>OnJoinedAsync</c>, смена роли отвечает
    /// «Целиком = True, НеВернулось = []», а поле чужое.
    ///
    /// Мимо следа шли ЧЕТЫРЕ живых места: подписка на вход у этой самой базы,
    /// донесение копателя после входа, «!дом тут» и «!пост тут» у стражника.
    /// Дом и склад в поля бота вообще НЕ ПИШУТСЯ до входа в мир
    /// (<see cref="ОтнестиДомБоту"/> отказывается без <c>CoordsKnown</c>), то
    /// есть в разнице вокруг <c>Configure</c> их нет по устройству — и без
    /// этой двери они не снялись бы никогда.
    /// </summary>
    protected void Донести()
    {
        // Роль ещё не надета на бота (пресет крутит её ручки ДО Configure) —
        // доносить некуда, и тело донесения само отвечает на это молчанием.
        // Второй ветки «а тогда позовём напрямую» тут нет НАРОЧНО: прямой вызов
        // и есть та дыра, которую дверь закрывает, и оставленный «на всякий
        // случай» он стал бы образцом для следующего.
        бот?.ЗаписатьВСлед(ДонестиОбщее);
    }

    /// <summary>
    /// Ручку повернули снаружи (панель, пресет, чат) — доносим ВСЕ общие
    /// настройки заново. Роль со своими ручками перекрывает этот метод и
    /// зовёт <c>base.ДонестиОбщее()</c>.
    /// </summary>
    public override void OnKnobsChanged() => Донести();

    /// <summary>Донести общие ручки до способностей. Идемпотентно: это присваивания порогов.</summary>
    protected virtual void ДонестиОбщее()
    {
        if (бот is not { } bot)
            return;

        // ВЫДЕРЖКА НАЧАТОГО ДЕЛА. Механизм в распорядителе тела, здесь только
        // число роли и ЧЕЛОВЕЧЕСКОЕ ИМЯ ручки: оно уходит прямо в отказ («даю
        // ему доработать ещё 3 с (ручка …)»), иначе человек читает секунды и не
        // знает, где их убавить. Ниже нуля не пускаем — отрицательная выдержка
        // означала бы фору наоборот, и молча
        bot.Context.Turn.SettleSeconds = Math.Max(0, ВыдержкаНачатогоДелаСекунд);
        bot.Context.Turn.SettleKnob = nameof(ВыдержкаНачатогоДелаСекунд);

        // УПРАВЛЕНИЕ ИЗ ЧАТА. Механизм в ChatCommands, здесь только решение
        // роли. Окна управления это не касается: оно зовёт RunAsync напрямую
        bot.Commands.AcceptFromChat = КомандыИзЧата;

        // РАДИОТИШИНА — ДРУГАЯ РУЧКА И ДРУГОЙ МЕХАНИЗМ. Та, что выше, про уши;
        // эта про рот, и стоит она на единственной двери в чат (BotVoice).
        // Обе доносятся здесь, рядом, нарочно: заказчик 16.08 принял их за одну
        bot.Voice.ReportWork = ПисатьВЧатОСвоихДелах;

        // ДЛИНА СТРОКИ В ЧАТЕ — ТУДА ЖЕ, НА ЕДИНСТВЕННУЮ ДВЕРЬ. Отчёты бота
        // от этого не беднеют: в журнал и в окно они уходят целыми
        bot.Voice.MaxChatLength = ДлинаСтрокиВЧате;

        // ЛОТОК. Механизм в Panning, здесь только числа роли. «Мыть ли вообще»
        // ручкой не переключается внутри механизма нарочно: механизм умеет мыть
        // всегда, а решает «стоит ли» тот, кто его зовёт (см. Stock и команду
        // «!промой»), — иначе выключенная галочка выглядела бы поломкой лотка
        bot.Panning.SearchRadius = Math.Max(1, ЛотокИщетВодуДо);
        bot.Panning.PansPerVisit = Math.Max(1, ПромывокЗаЗаход);
        bot.Panning.Allowed = МытьЛоткомКогдаИначеНегде;

        // РАДИУС СОСЕДЕЙ — ПЕРЕД САМОЙ ТОЧКОЙ. Склад держит ОДНУ заданную
        // человеком клетку, а сколько сундуков под ней окажется, решает этот
        // радиус: соседей ищут заново каждый обход (Depot.Points), потому что
        // сундук могли сломать. Сними радиус — и «!склад тут», взявший
        // шестнадцать сундуков, оставит один
        bot.Depot.NeighbourRadius = Math.Max(0, СоседниеСундукиВРадиусе);

        // ДВЕ ТОЧКИ ЧЕЛОВЕКА — РЯДОМ И В ОДНОМ МЕСТЕ. В окне они стоят одна под
        // другой (раздел «склад», номера 1 и 2), и доносятся тоже рядом: обе
        // ждут одного и того же — точки спавна, без которой перевода игровых
        // координат в мировые не существует
        ОтнестиСкладБоту(bot);
        ОтнестиДомБоту(bot);

        if (bot.Behaviors.Get<BehaviorKeepHomeSpawn>() is { } точка)
        {
            точка.Enabled = ОтмечатьДом;
            // ЦЕНА ДОРОГИ ЗА ТОЧКОЙ. Галочка выше говорит «следить», а эти два
            // числа — «сколько за это платить»: как далеко идти и с какого
            // расстояния считать, что точка уже дома. Раньше галочку доносила
            // база, а цену — один выживальщик, и у четырёх ролей из пяти
            // включённая в окне отметка ходила по библиотечным числам.
            // Ниже нуля не пускаем: отрицательная дорога означала бы «не ходить
            // никогда», и молча — а «не ходить» человек пишет нулём сам
            точка.MaxDistance = Math.Max(0, ДомДальше);
            точка.Spawn.Tolerance = Math.Max(0, ДопускДома);
        }

        // СОН. Способность есть у всех и была не донесена НИКУДА: повернуть её
        // можно было только правкой кода. Радиус поиска кровати нарочно не
        // отдельная ручка — он берётся из «как далеко хожу» (BehaviorSleepAtNight
        // .LookAround): одна человеческая мерка не должна крутиться двумя полями
        if (bot.Behaviors.Get<BehaviorSleepAtNight>() is { } сон)
        {
            сон.Enabled = СпатьНочью;
            сон.MaxBedDistance = Math.Max(1, ЗаКроватьюНеДальше);
            // ДОМОЙ ЗА КРОВАТЬЮ — СИЛЬНЕЕ ПОТОЛКА ВЫШЕ. «Главное кровать в его
            // доме»: до своего дома бот идёт без оглядки на «ЗаКроватьюНеДальше»,
            // ровно как в бурю и от безделья
            сон.GoHomeForBed = ДомойЗаКроватью;
            // СЕКУНДА НА БЛОК — заведомо щедрый запас: бот проходит несколько
            // блоков в секунду. Коротким сроком дорога обрывалась бы на полпути,
            // и бот честно, но впустую докладывал бы «до кровати не дотянуться»
            сон.TravelSeconds = Math.Max(30, сон.MaxBedDistance);
        }

        if (bot.Behaviors.Get<BehaviorGreetPlayers>() is { } привет)
        {
            привет.Enabled = МахатьИгрокам;
            привет.GreetEveryMinutes = Math.Max(0, МахатьРазВМинут);
            привет.Radius = Math.Max(1, РадиусПриветствия);

            // ЧЕМ И КАК ЗДОРОВАТЬСЯ — вторая половина той же семьи, приехавшая
            // 08.09 от выживальщика. Включение, частота и радиус стоят строкой
            // выше; эмоция, слова и книга встреч жили у одной роли, и у
            // стражника с продавцом «махать игрокам: да» махало библиотечным
            // wave, о котором в окне не было сказано ни слова.
            //
            // ПУСТАЯ СТРОКА ВОЗВРАЩАЕТ ЗАВОДСКОЕ, А НЕ ГАСИТ ПРИВЕТСТВИЕ:
            // пустое имя эмоции сервер отверг бы, а пустой текст ушёл бы в чат
            // пустой строкой — и бот считал бы, что поздоровался. Выключают
            // приветствие галочкой «МахатьИгрокам», для этого есть своя ручка
            привет.Emote = string.IsNullOrWhiteSpace(ЭмоцияПриветствия) ? "wave" : ЭмоцияПриветствия;
            привет.SayHelloWhenNoEmote = ЗдороватьсяСловомБезЭмоции;
            привет.HelloText = string.IsNullOrWhiteSpace(ТекстПриветствия)
                ? "Привет, {0}!" : ТекстПриветствия;
            привет.ForgetAfterDays = Math.Max(0, ПомнитьВстречиДней);
            привет.RememberAtMost = Math.Max(0, ПомнитьЛюдейНеБольше);
        }

        if (bot.Behaviors.Get<BehaviorCarryLight>() is { } фонарь)
        {
            фонарь.Enabled = ФонарьВРуке;
            фонарь.PreferOffHand = ФонарьВЛевойРуке;
            фонарь.OnlyWhenDark = ФонарьТолькоВТемноте;
            фонарь.PutAwayWhenLight = УбиратьФонарьДнём;
            фонарь.TakeUnderground = ФонарьВПещере;
            // Ноль и минус означали бы «поверхность и есть пещера» — с ними
            // бот зажигал бы фонарь, стоя в яме на один блок. Ниже единицы
            // не пускаем, а разумную глубину выбирает человек
            фонарь.UndergroundDepth = Math.Max(1, ПещераГлубжеБлоков);

            // ПОРОГИ РАЗВЕДЕНЫ НА ДВА НАПРАВЛЕНИЯ — иначе бот дребезжит рукой.
            // Живой случай 16.08, полдень: наклонный ход вверх, глубина ходит
            // вокруг шести, и полсотни пар «взял → убрал» подряд.
            //
            // Порог отпускания не пускаем ЗА порог срабатывания: наоборот
            // разведённые числа дали бы отрицательную полосу, и запас работал бы
            // против себя — дёргал бы чаще, чем вовсе без него. Человеку это
            // видно по числам в окне, а боту молчать про такое нельзя
            фонарь.SurfaceDepth = Math.Clamp(ПоверхностьНеГлубжеБлоков, 0, фонарь.UndergroundDepth);
            фонарь.LightThreshold = Math.Max(фонарь.DarkThreshold, ФонарьУбиратьПриСветеОт);
            фонарь.DawnMarginHours = Math.Max(0, ДержатьФонарьПослеРассветаЧасов);
            // Ноль здесь означал бы «переигрывать решение каждый тик», то есть
            // по нескольку раз в секунду; секунда — самый короткий срок, при
            // котором решение вообще успевает дойти до сервера и вернуться
            фонарь.RetrySeconds = Math.Max(1, НеТрогатьФонарьСекунд);
        }

        if (bot.Behaviors.Get<BehaviorIdle>() is { } безДела)
        {
            безДела.WhenIdle = БезДела;
            безДела.IdleSeconds = Math.Max(5, ПорогБезделья);
            безДела.WanderRadius = Math.Max(2, РадиусПрогулки);
            безДела.Farewell = ПрощатьсяПередУходом ?? "";
            безДела.FinishLooseEnds = ЗакрыватьХвостыВПростое;
            безДела.RunJobs = ОчередьЗадачВПростое;
            // Ноль минут означал бы «пробовать без передышки»: незакрытое, за
            // которое не берётся мир (непрогруженный чанк, палки нет нигде),
            // перебиралось бы раз в минуту до утра
            безДела.Hopeless.TryAgainAfter =
                TimeSpan.FromMinutes(Math.Max(1, НеБратьсяЗаБезнадёжноеМинут));
            // ОЧЕРЕДЬ ДОНОСИМ И ОТСЮДА. Бегун собирается ПОСЛЕ роли и знакомится
            // с ней сам (UseRunner); но ручки роли доносятся на каждый поворот
            // любой соседней, и без этой строки цикл задач в простое остался бы
            // без очереди у всякого, кто повернул ручку до сборки бегуна
            if (очередь is { } бегун)
                безДела.Works = бегун;
        }

        // ВЕЩИ ПОСЛЕ СМЕРТИ. Способность есть у всех и намертво выключена
        // пресетом — включает её роль. Пока этих двух строк не было, у
        // Продавца и ИИ вещи оставались на месте гибели навсегда
        if (bot.Behaviors.Get<BehaviorRecoverLoot>() is { } вещи)
        {
            вещи.Enabled = ЗабиратьВещи;
            вещи.MaxDistance = Math.Max(0, ЗаВещамиНеДальше);
        }

        // ДОБЫЧА С УБИТЫХ. Обе галочки доносятся сюда, потому что решение
        // «подбирать» и решение «разделывать» принимает роль, а не библиотека,
        // и крутить их человек будет уже в мире — настройка, прочитанная один
        // раз при сборке, до первого дрифтера не доехала бы.
        // Отрицательный предел — описка: «не ходить никуда» выражается снятыми
        // галочками, а не числом со знаком
        if (bot.Behaviors.Get<BehaviorLootKills>() is { } сУбитых)
        {
            сУбитых.PickUpDrops = ПодбиратьДобычуСУбитых;
            сУбитых.Butcher = РазделыватьТуши;
            сУбитых.Radius = Math.Max(0, ЗаДобычейСУбитыхНеДальше);
            // ПЕРЕБИВАТЬ ЛИ РАБОТУ РАДИ ТУШИ. Доносится живьём, как и обе
            // галочки выше: человек, увидевший в журнале «разделка ждёт; туша
            // сгниёт через 4,1 мин», крутит ручку тут же, а не при следующем
            // запуске бота
            сУбитых.PreemptWork = РазделкаПеребиваетРаботу;
        }

        // СВОЯ ВЫЛОМАННАЯ ДОБЫЧА. Предел похода за пометкой мерит роль тем же
        // числом, что и поход за тушей: у библиотеки нет ответа на вопрос
        // «стоит ли овчинка выделки»
        if (bot.Behaviors.Get<BehaviorPickUpDrops>() is { } свояДобыча)
            свояДобыча.WalkLimit = Math.Max(0, ЗаСвоейДобычейНеДальше);

        // ПРОПИТАНИЕ. Способы, которыми бот закрывает голод, — политика роли до
        // последнего: библиотека знает, КАК приготовить и КАК добыть зверя, но
        // не знает, стоит ли лавочнику уходить за оленем.
        //
        // ДОНОСИТЬ ИХ НАДО ИМЕННО ЗДЕСЬ, а не при сборке: настройка, прочитанная
        // один раз, до первого голода не доехала бы — человек крутит эти галочки
        // уже в мире, глядя на журнал
        if (bot.Behaviors.Get<BehaviorForageWhenNoFood>() is { } пропитание)
        {
            // ГЛАВНЫЙ ВЫКЛЮЧАТЕЛЬ — ПЕРВОЙ СТРОКОЙ: он гасит разом всё, что
            // ставится ниже. Строка эта жила у одного Выживальщика, а способность
            // стоит у всех пяти ролей (Presets.Survive), и четверо не могли
            // выключить сбор ничем
            пропитание.Enabled = СобиратьЕду;
            // ЧТОБЫ ОТКАЗ МОГ НАЗВАТЬ РУЧКУ. Без имени человек читал бы «бот не
            // пошёл» и не знал бы, какую галочку искать
            пропитание.Отключатель = nameof(СобиратьЕду);
            пропитание.FromStores = ЕдаИзКладовых;
            пропитание.Cook = ГотовитьЕду;
            пропитание.Hunt = Охотиться;
            пропитание.HuntRadius = Math.Max(1, ОхотитьсяНеДальше);
            пропитание.HuntSeconds = Math.Max(1, СколькоДержатьТелоЗаОхоту);
            пропитание.CookWaitSeconds = Math.Max(1, СколькоЖдатьГотовки);
        }

        // ВЫБРОС ЛИШНЕГО — последняя ступень «некуда взять X». Мерку «что
        // дёшево» держит реестр игры (Hands.WorthOf), здесь только разрешение
        // и список исключений хозяина
        bot.Hands.MayDropJunk = ВыбрасыватьЛишнее;
        bot.Hands.DropJunkForFood = ВыбрасыватьРадиЕды;
        bot.Hands.NeverDrop.Clear();
        foreach (string часть in (НеВыбрасывать ?? "").Split(',',
                     StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
            bot.Hands.NeverDrop.Add(часть);

        // УХОД ОТ НЕСТАБИЛЬНОСТИ. Механизм в BehaviorSeekStability, здесь
        // только решение роли: бежать ли, с какого числа и до какого отпускает.
        // Порог отпускания не даём опустить ниже порога ухода — иначе бот
        // «убежал бы и остался бежать» навсегда
        if (bot.Behaviors.Get<BehaviorSeekStability>() is { } стабильность)
        {
            стабильность.Enabled = УходитьПриНизкойСтабильности && УходитьПриСтабильностиНиже > 0;
            стабильность.RunBelow = Math.Clamp(УходитьПриСтабильностиНиже, 0, 1);
            стабильность.CalmAt = Math.Clamp(
                Math.Max(СтабильностьОтпускаетНа, стабильность.RunBelow), 0, 1);
            стабильность.LookAround = Math.Max(4, ЗаСтабильностьюНеДальше);
        }

        // УЙТИ ИЗ ОГНЯ. Механизм в BehaviorLeaveHarm, здесь только решение
        // роли. Радиус не даём опустить до нуля: «уходить, но никуда» — это
        // молчаливое выключение способности, а выключать её надо галочкой,
        // чтобы это было видно человеку
        if (bot.Behaviors.Get<BehaviorLeaveHarm>() is { } огонь)
        {
            огонь.Enabled = УходитьИзОгня;
            огонь.LookAround = Math.Max(1, КудаУходитьОтОгняБлоков);
        }

        // ДИКИЕ ПОСЕВЫ И ЧУЖИЕ ГРЯДКИ
        bot.Foraging.HarvestWildCrops = СобиратьПосевы;
        bot.Foraging.SkipFarmland = !ТрогатьЧужиеГрядки;

        // КАК ДАЛЕКО ОТХОДИТЬ ЗА ЕДОЙ — ОДНО МЕСТО НА ВСЕ РОЛИ (закон 2).
        // Приёмка 27.08 нашла эту механику В ЧЕТЫРЁХ местах разом: ручка
        // «РадиусСбораЕды» у копателя, ДРУГОЕ ИМЯ той же вещи «РадиусЗаЕдой» у
        // роли мода, и жёсткие числа в коде у стражника (12) и у продавца (24)
        // — причём над обоими стоял комментарий «Жёсткого числа здесь больше
        // нет — его не было ни в одном пресете (закон 1)», и он был неправдой
        // ровно на следующей строке. Теперь ручка одна, у всех, и в пресете
        // каждой роли стоит её собственное число.
        //
        // Заслонка снизу: круг в ноль блоков означал бы «ходи за едой, но
        // никуда» — это молчаливое выключение сбора, а выключать его надо
        // галочкой «СобиратьЕду», чтобы это было видно человеку
        if (bot.Behaviors.Get<BehaviorForageWhenNoFood>() is { } сборЕды)
            сборЕды.Radius = Math.Max(8, РадиусСбораЕды);

        // УКРЫТИЕ, ХОДЬБА И ШУМ ПРО РАЗЛОМЫ. Все три числа были заведены в
        // библиотеке и не донесены НИКУДА: ни роль, ни пресет, ни панель их не
        // трогали, и повернуть их можно было только правкой кода. Это ровно та
        // беда, которую проект уже ловил на «ДальностьРудыСквозьСтены», —
        // «ручка есть, а пользоваться ею некому».
        //
        // Заслонки снизу разные и не случайные: радиус укрытия в ноль блоков
        // означал бы «спрятался, только пока стою на том же полу-блоке»;
        // перехватов можно стерпеть и ноль — это законный выбор «уступать
        // сразу»; ноль секунд молчания — это «показывай каждую строку», то
        // есть тоже настоящий выбор человека, разбирающего живой прогон
        bot.Shelter.HideHoldRadius = Math.Max(1, УкрытиеДержитсяВРадиусе);
        bot.Movement.MaxBodyLosses = Math.Max(0, СтерпетьПерехватовХодьбы);

        // --- ПРЕРВАЛИ — ВЕРНИСЬ И ДОДЕЛАЙ ---
        //
        // Пять строк переехали сюда 09.09 от выживальщика вместе со своими
        // ручками. До переезда четыре роли из пяти не доносили до Resume
        // НИЧЕГО: механизм жил своими заводскими, а окно не показывало их
        // вовсе. Числа при этом не переменились ни у кого — заводские ручки
        // выживальщика побуквенно совпадают с умолчаниями механизма (3, 20, 1,
        // 180, 5), — переменилось то, что теперь их есть чем крутить.
        bot.Resume.MaxReturns = Math.Max(0, ВозвращатьсяКПрерванному);
        bot.Resume.ProgressSeconds = Math.Max(1, ЗачётЗаходаСекунд);
        // ПАУЗА ВОЗВРАТА — ЕДИНСТВЕННОЕ ЧИСЛО РОЛИ, КОТОРЫМ МОЖНО ВЕРНУТЬ УЖЕ
        // ЗАКРЫТЫЙ СТУПОР, И ПРЕЖДЕ ОНО ШЛО СЮДА КАК ЕСТЬ: Math.Max(0, …) ноль
        // разрешал. Разбор, цена и почему пол именно такой — у самого правила
        // (ПаузаВозвратаБезСтупора); ход способностей спрашиваем у механизма,
        // а не переписываем числом сюда
        // ИМЯ «жалобаНаПаузу», А НЕ ПРОСТО «жалоба»: в этом же теле ниже стоит
        // такая же пара у порогов боя, и одноимённые местные переменные C# в
        // одной области не пускает — а разводить их номером в разных методах
        // значило бы дробить донесение
        var (пауза, жалобаНаПаузу) = ПаузаВозвратаБезСтупора(ПаузаПередВозвратом,
            bot.Behaviors.TickMs / 1000.0);
        bot.Resume.PauseSeconds = пауза;
        // МОЛЧАТЬ НЕЛЬЗЯ. Человек повернул ручку и вправе знать, что его число
        // не взяли и почему: тихий зажим тут неотличим от «настройка не
        // работает» (правило 4 проекта)
        if (жалобаНаПаузу != null)
            СказатьЕслиНовое("пауза возврата", жалобаНаПаузу);
        bot.Resume.WaitForBodySeconds = Math.Max(1, ЖдатьТелаСекунд);
        // ЖДЁМ ПЕРЕМЕНЫ МИРА, А НЕ ОСВОБОЖДЕНИЯ ТЕЛА, — и потому число своё.
        // Разбор у самой ручки; ноль тут законен и значит «пробовать сразу»
        bot.Resume.WorldPauseSeconds = Math.Max(0, ЖдатьПеременыМираСекунд);

        // ЗА СКОЛЬКО СБАВИТЬ ШАГ. Заслонки здесь нет НАРОЧНО: она стоит у самой
        // ручки, и второй быть не должно — иначе окно управления покажет одно
        // число, а бот пойдёт по другому (этим уже обжигались на «ОбходитьПередЛомкойБлоков»)
        bot.Movement.SprintDistance = СбавитьШагЗаБлоковДоЦели;
        // СКОЛЬКО НЕ ДОВЕРЯТЬ СПРЯМЛЕНИЮ — та же беда «ручка есть, а
        // пользоваться ею некому»: шестьдесят секунд жили в движении и не
        // доносились ниоткуда. Заслонка — у самой ручки, второй тут не должно
        // быть по той же причине, что и у «сбавить шаг»
        bot.Movement.SmoothingDistrustSeconds = НеДоверятьСпрямлениюСекунд;
        // ДВЕРИ ЗА СОБОЙ — та же беда «ручка есть, а пользоваться ею некому»:
        // CloseDoorsBehind жила в движении с заводским «да» и не доносилась
        // ниоткуда. Заслонки снизу тут нет и быть не может: «нет» — это
        // законный выбор человека, и он будет слышен по каждой двери
        bot.Movement.CloseDoorsBehind = ЗакрыватьЗаСобойДвери;
        // Отрицательный отход — описка: «закрывать сразу» выражается нулём
        bot.Movement.CloseDoorsStepAway = Math.Max(0, ОтойтиОтДвериПередЗакрытием);
        bot.Stability.QuietRepeatSeconds = Math.Max(0, ПовторыПроРазломыРежеСекунд);
        // СТОРОЖ МОЛЧАНИЯ. Заслонки снизу нет и быть не может: ноль — это
        // законный выбор «молчи сколько хочешь», как было до этой правки.
        // Заслонка сверху не нужна тоже: молчание длиной в час человек
        // выбирает сам и читает его последствия сам
        bot.Pulse.QuietSeconds = Math.Max(0, МолчатьНеДольшеСек);
        // ЧУЖОЕ РАДИ ВЫХОДА. Ручка донесена и до штольни (она рубит ступени
        // выхода), и до дороги с карьером — все они ломают через один и тот же
        // шов Tunnel.ClearAsync, и второй копии решения тут взяться неоткуда
        bot.Tunnel.BreakForeignToGetOut = ЛоматьЧужоеРадиВыхода;
        // В СКОЛЬКИХ БЛОКАХ ИСКАТЬ ПРИМЕТЫ ПОСТРОЙКИ. Число тоже переносится
        // как есть: описку гасит сама ручка, в своём же set. Своя заслонка у
        // штольни остаётся — она защищает механизм от тех, кто ставит число
        // мимо роли (стенды, чужой код), а не второе число человеку
        bot.Tunnel.BuiltAroundRadius = ПриметыПостройкиИскатьВРадиусе;
        // ДВОР ХОЗЯИНА — РАДИУС ОТ ЕГО ЖЕ ОТМЕТОК. Доносится прямо до заставы:
        // «дом» и «склад» берёт она сама у Depot, а «насколько вокруг» —
        // человеческий выбор, и до этой правки повернуть его было нечем, хотя
        // отказ бота уже называл ручку по имени. Заслонка снизу — у самой
        // ручки, второй тут не заводим
        bot.Context.Break.KeepRadius = ДомИСкладБерегуВРадиусе;

        // ЧУЖИЕ ВЛАДЕНИЯ. Механизм (Claims) слушает пакет 75 сам и заводится
        // каждому боту; здесь только решения роли — на сколько держаться и
        // долго ли верить подмеченному. Приехали 09.09 от выживальщика: чужое
        // спрашивает КАЖДЫЙ автопоиск, а поручения и очередь задач есть у
        // всякой живущей роли.
        //
        // ЗАСЛОНКИ РАЗНЫЕ И НЕ СЛУЧАЙНЫЕ. Ноль блоков — законный выбор («не
        // держаться вовсе», так стоит в quarry-only и resident), поэтому снизу
        // ноль. А ноль МИНУТ памяти означал бы «забыл в тот же миг, как
        // подметил», то есть выключенную память под видом включённой: такое
        // человек пишет опиской, и снизу стоит минута
        bot.Claims.KeepAway = Math.Max(0, ДержатьсяОтЧужого);
        bot.Claims.Remember = TimeSpan.FromMinutes(Math.Max(1, ПомнитьЧужоеМинут));
        bot.Claims.RememberPlayers = TimeSpan.FromMinutes(Math.Max(1, ПомнитьИгроковМинут));

        // ЧЕСТНО ПРО СВЯЗКУ ДВУХ РУЧЕК. Людей бот замечает ровно там, где
        // здоровается, — другого места нет. Молча не работающая настройка хуже
        // отсутствующей, поэтому о несоответствии говорится вслух и один раз на
        // каждую перемену
        bool чужиеЛюдиМолчат = ИзбегатьИгроков && !МахатьИгрокам;
        if (чужиеЛюдиМолчат != жаловалсяНаИзбеганиеЛюдей)
        {
            жаловалсяНаИзбеганиеЛюдей = чужиеЛюдиМолчат;
            if (чужиеЛюдиМолчат)
                bot.Log("«ИзбегатьИгроков» включено, но людей я замечаю только когда включено " +
                        "«МахатьИгрокам» — сейчас чужих мест по людям не копится");
        }
        // ЛОМАТЬ — КРАЙНЯЯ МЕРА, и эти две ручки про то, СКОЛЬКО ходьбы бот
        // переберёт до кирки, а не про то, ломать ли вообще. Само правило
        // (Movement.DigForWayIsLastResort) ручкой не снимается — иначе она и
        // была бы тем «первым ответом на отказ поиска», который заказчик
        // забраковал дважды.
        //
        // ЧИСЛО ПЕРЕНОСИТСЯ КАК ЕСТЬ, БЕЗ ВТОРОЙ ЗАСЛОНКИ: описку гасит сама
        // ручка, в своём же set. Гаси её ещё и здесь — и в окне осталось бы
        // одно число, а в чате звучало другое
        // ЦЕНА СОСЕДСТВА С ОГНЁМ. Заслонка — у самой ручки, второй тут не
        // должно быть по той же причине, что и у «сбавить шаг»: иначе окно
        // покажет одно число, а маршрут ляжет по другому
        bot.Movement.PathOptions.LavaProximityCost = ЦенаШагаВплотнуюКОгню;
        bot.Movement.DetourReach = ОбходитьПередЛомкойБлоков;
        bot.Movement.ApproachRadius = ПодходКЦелиИскатьВРадиусе;
        // МЕЛОЧЬ С ДОРОГИ. Одно человеческое решение — и оно доносится до ДВУХ
        // выключателей библиотеки нарочно: добыча решает, ломать ли мелочь
        // руками (Mining.ClearGrowth, через него же судит и правило
        // JudgeGrowth), а движение — вести ли сквозь неё маршрут
        // (Movement.ClearGrowthOnWay, оттуда же кормится PathOptions.IsLeaves).
        // Разреши одно и запрети другое — и бот пошёл бы в куст лбом; ровно об
        // этом предупреждает разбор в VsBot, где эти два шва связаны
        bot.Mining.ClearGrowth = СметатьМелочьСДороги;
        bot.Movement.ClearGrowthOnWay = СметатьМелочьСДороги;
        // А это МЕРКА никчёмности по времени. Заслонка снизу стоит у самой
        // ручки, в её же set: гаси описку ещё и здесь — и окно управления
        // показало бы одно число, а бот считал бы по другому
        bot.Mining.GrowthSeconds = МелочьЛомаетсяНеДольшеСек;
        // ШУМ ПРО ЗДОРОВЬЕ — та же беда и та же заслонка: ноль значит «показывай
        // каждую строку журнала урона», и это законный выбор разбирающего прогон
        bot.Damage.QuietRepeatSeconds = Math.Max(0, ПовторыПроЗдоровьеРежеСекунд);
        // КОСТЁР, КОТОРЫЙ НЕЧЕМ РАЗВЕСТИ. Механизм — общая безнадёга
        // (Fire.Гиблое), здесь только СРОК: сколько ждать чужой руки с
        // поленьями. Заслонки снизу нет — ноль значит «пробуй каждый раз»,
        // и это законный выбор того, кто разбирает живой прогон
        bot.Fire.Гиблое.TryAgainAfter =
            TimeSpan.FromMinutes(Math.Max(0, ПробоватьКостёрСноваЧерезМин));
        // ДОКУДА ГРЕТЬСЯ. Человек называет градусы ТАК, КАК ИХ ПИШЕТ ИГРА, а
        // правило считает сырыми — перевод один на весь проект и живёт в
        // BodyHeat. Заслонки снизу и сверху тут нет и не должно быть: она
        // стоит у самого правила (BehaviorKeepWarm.WarmUpTo), и вторая копия
        // означала бы, что окно показывает одно число, а бот греется по другому
        if (bot.Behaviors.Get<BehaviorKeepWarm>() is { } тепло)
        {
            тепло.WarmUpTo = BodyHeat.RawTemperature((float)ГретьсяДоТемпературы);
            // НА СКОЛЬКО ПОДХОДИТЬ. Заслонки снизу тут нет НАРОЧНО, и это не
            // недосмотр: она стоит у самого правила
            // (BehaviorKeepWarm.NeverCloserToFire — граница, за которой игра
            // жжёт), а вторая копия значила бы, что окно показывает одно, а бот
            // подходит по другому
            тепло.WarmDistance = ПодходитьККостру;
        }

        ОтнестиНастройкиСклада(bot);
        ОтнестиНастройкиОчереди();
        ОтнестиСетьТранслокаторов(bot);

        // ЧЕМ ДОРОЖИМ В СТЫЧКЕ. Сам выбор («догоню ли», «выживу ли») считает
        // библиотека, а вот цены ответов — решение роли, и они доносятся сюда
        // же, куда и всё прочее: панель крутит ручки уже в мире, и настройка,
        // прочитанная один раз при сборке, до боя не доехала бы.
        // Отрицательная цена означала бы «мне ПЛАТЯТ за бегство» — это не
        // настройка, а описка, поэтому снизу ноль
        if (bot.Behaviors.Get<BehaviorAttackHostiles>() is { } бой)
        {
            бой.FleePrice = Math.Max(0, ЦенаУхода);
            бой.SealPrice = Math.Max(0, ЦенаЗакладывания);
            // Ноль секунд терпения означал бы «стоять под ударами бесплатно»:
            // вариант «не связываться» стал бы самым дешёвым всегда, и бот
            // спокойно дал бы себя забить, не бросив кирки
            бой.IgnoreSeconds = Math.Max(0.5, ТерпетьУдарыСекунд);

            // КОГДА БОЙ СЧИТАТЬ ПРОИГРАННЫМ И КОГДА ВОЗВРАЩАТЬСЯ. Связка двух
            // порогов — чистое правило библиотеки (HealthGates), роль его не
            // повторяет; здесь только жалоба вслух, если человек вписал
            // «возвращаться» ниже «отступать»
            var (отступать, обратно, жалоба) =
                BehaviorAttackHostiles.HealthGates(ОтступатьНижеЗдоровья, ВозвращатьсяВБойПри);
            бой.RetreatHealthFraction = отступать;
            бой.ResumeHealthFraction = обратно;
            СказатьЕслиНовое("пороги боя", жалоба ??
                $"отступаю ниже {отступать:P0} здоровья, возвращаюсь в бой при {обратно:P0}");

            // КОМУ МСТИТЬ И КАК ДАЛЕКО ГНАТЬСЯ. Библиотека прямо отдаёт это
            // роли — торговцу от прилавка отходить незачем, охотнику наоборот,
            // — а повернуть было нечем: ручки не существовало
            бой.Revenge = Мстить;
            бой.RevengeRadius = Math.Max(0, РадиусМести);

            // КОГДА ГОЛОД ОТМЕНЯЕТ ПОГОНЮ. Доля, а не хиты: у разных сущностей
            // разный запас сытости, и мерить надо тем же, чем меряет игра.
            // Единица означала бы «мстить только на полный желудок», то есть
            // никогда, — зажимаем в 0..1
            бой.VitalNeedsFraction = Math.Clamp(БроситьПогонюПриСытостиНиже, 0, 1);

            // НА СКОЛЬКО СЧИТАТЬ, ЧТО ОТОРВАЛСЯ. Ноль означал бы «побег
            // бесплатен»: уйти на ноль блоков ничего не стоит по числам, и бот
            // выбирал бы побег всегда, никуда при этом не убегая
            бой.FleeGainAtLeast = Math.Max(0.5, ОтрыватьсяНеБлижеЧемНа);

            // С КАКОГО РАССТОЯНИЯ НАЧИНАТЬ ПОБЕГ — И ЧЕМ ЗАКРЫТЬСЯ, КОГДА
            // ЗАГНАЛИ. Приехали 08.09 от выживальщика; порог отрыва строкой
            // выше — ДРУГОЕ число, и держать их разными и есть смысл этих двух
            // строк (при одном числе побег кончался, не начавшись, семьдесят
            // раз за полминуты).
            //
            // Ноль здесь не зажимаем нижним краем нарочно: «БежатьБлиже: 0» —
            // законный выбор человека («не убегать вовсе, драться до конца»),
            // а не описка, и подпирать его снизу значило бы отменить сказанное
            // в окне. Чем закладываться, бою отдаёт пресет выживания
            // (Presets.Survive: combat.Refuge = bot.Shelter) — одному на всех,
            // и второй такой строки в ролях быть не должно
            бой.FleeStartDistance = БежатьБлиже;
            бой.SealWhenCornered = ЗакладыватьсяВУглу;

            // КОГДА НОСИТЬ БРОНЮ. Библиотека решает это ОДНИМ правилом на все
            // ветки боя, а «когда» — политика, и до сегодня она была зашита в
            // три булевых признака библиотеки, до которых роль не дотягивалась
            // ничем. Та же беда, что была у «ДальностьРудыСквозьСтены»
            бой.Armor = НоситьБроню;

            // ЛУК. Числа доносятся ЖИВЬЁМ, как и всё прочее: панель крутит
            // ручки уже в мире, и настройка, прочитанная один раз при сборке,
            // до боя не доехала бы.
            //
            // КАЖДОЕ ЧИСЛО ЗАЖАТО ТАМ, ГДЕ ИГРА ВСЁ РАВНО ОТКАЖЕТ, и молчать об
            // этом нельзя: тетива короче 0,3 с — это ВООБЩЕ НЕ ВЫСТРЕЛ (порог
            // сервера 0,65 «раздутых» секунд), и человек, вписавший 0,1,
            // получил бы бота, который целится и не стреляет, без единого слова
            // в журнале
            бой.UseBow = СтрелятьИзЛука;
            бой.ShootMaxRange = Math.Max(0, СтрелятьНеДальше);
            бой.ShootMinRange = Math.Max(0, СтрелятьНеБлижеЧем);
            бой.DrawSeconds = Math.Max(0.35, ТянутьТетивуСекунд);
            // ДОЛЯ ПОПАДАНИЯ ЗАЖАТА В [0; 1] ПОТОМУ, ЧТО ЭТО ДОЛЯ, а не число
            // блоков: вписанная единица с хвостиком означала бы «не стрелять
            // никогда», и бот молчал бы об этом всю сессию
            бой.ShootMinChance = Math.Clamp(СтрелятьПриШансеНеНиже, 0, 1);
            бой.DefendRadius = Math.Max(0, ВступатьВБойСРасстояния);

            // КОГО СЧИТАТЬ ВРАГОМ. Набор был в библиотеке и не доносился НИ
            // ОДНОЙ ролью — то есть по закону 1 для заказчика его не
            // существовало: ни метку под свой мод добавить, ни bellmini снять.
            // Список разбираем ТЕМ ЖЕ разбором, что и прочие человеческие
            // списки (Stock.ParseList), второго тут заводить незачем
            бой.HostileTags.Clear();
            foreach (var метка in Stock.ParseList(ВражескиеМетки))
                бой.HostileTags.Add(метка);
            бой.PeacefulCodes.Clear();
            foreach (var код in Stock.ParseList(МирныеКоды))
                бой.PeacefulCodes.Add(код);
            бой.MeetWithBow = ВстречатьЛукомИздалека;
            бой.RangedFirstForSummoners = ЗовущихПодмогуБитьИздали;
            бой.OnlyWhoReachesMe = ДратьсяСТемиКтоДоМеняДойдёт;
            бой.ShootWhoCannotReachMe = СтрелятьВТехКтоДоМеняНеДойдёт;
            // Ниже сотни воздух не замкнётся даже в комнате, ответом станет
            // вечное «не знаю», и ручка «ДратьсяСТемиКтоДоМеняДойдёт» умрёт
            // молча. Ошибаться она будет в безопасную сторону, но осознанно
            бой.ReachSearchNodes = Math.Max(100, СколькоКлетокСмотретьПроЗапертоеМесто);

            // С КАКОГО РАССТОЯНИЯ БОТ ВСТРЕТИТ ВРАГА — СКАЗАТЬ ЧИСЛОМ, А НЕ
            // ОСТАВИТЬ ЧЕЛОВЕКУ СВОДИТЬ ДВЕ РУЧКИ В УМЕ.
            //
            // До 26.08 здесь стояла жалоба «лук в обычной стычке молчит»: четыре
            // блока оборонительного радиуса меньше пяти, с которых лук вообще
            // стреляет, и до лука дело не доходило ни разу. Жалоба была честной,
            // но чинить её человеку приходилось руками. Теперь круг встречи
            // считает правило (CombatReach.MeetFrom): есть лук — встречаю с
            // «СтрелятьНеДальше». Осталось назвать, что вышло, и с чем именно
            // бот выйдет навстречу.
            double кругСЛуком = CombatReach.MeetFrom(бой.DefendRadius, true,
                бой.ShootMaxRange, ВстречатьЛукомИздалека);
            СказатьЕслиНовое("лук-окно", !СтрелятьИзЛука
                ? $"дальнего врага не встречаю: ручка «СтрелятьИзЛука» снята, беру " +
                  $"его с {бой.DefendRadius:0.#} бл («ВступатьВБойСРасстояния») и " +
                  "схожусь ногами"
                : !ВстречатьЛукомИздалека
                    ? $"лук в обороне молчит: ручка «ВстречатьЛукомИздалека» снята, " +
                      $"врага беру с {бой.DefendRadius:0.#} бл " +
                      $"(«ВступатьВБойСРасстояния»), а стреляю не ближе " +
                      $"{бой.ShootMinRange:0.#} («СтрелятьНеБлижеЧем») — к тому мигу он " +
                      $"уже ближе. Стреляю тогда только в ответ на удар (радиус " +
                      $"{бой.RevengeRadius:0.#} бл, ручка «РадиусМести»)"
                    : $"пока лук и стрелы при мне, врага встречаю с {кругСЛуком:0.#} бл " +
                      $"(«СтрелятьНеДальше») и расстреливаю, пока идёт; без стрел — " +
                      $"с {бой.DefendRadius:0.#} бл («ВступатьВБойСРасстояния») и схожусь " +
                      "ногами");

            СказатьЕслиНовое("дойдёт-ли", ДратьсяСТемиКтоДоМеняДойдёт
                ? "к тому, кому до меня не дойти (я в доме, двери закрыты), не лезу: " +
                  "обвожу воздух вокруг себя, и если он замкнулся стенами да закрытыми " +
                  "дверями, то стоящий снаружи мне не опасен. Ударит — отвечаю как " +
                  "всегда. ДВОР БЕЗ КРЫШИ запертым не считаю: воздух над ним уходит " +
                  "в небо (ручка «ДратьсяСТемиКтоДоМеняДойдёт»)"
                : "на всякого врага в кругу встречи иду как прежде: ручка " +
                  "«ДратьсяСТемиКтоДоМеняДойдёт» снята — учтите, что дрифтер за стеной " +
                  "дома при закрытых дверях всё равно оторвёт меня от работы и заставит " +
                  "надеть броню");

            СказатьЕслиНовое("стрелять-в-недостижимых", СтрелятьВТехКтоДоМеняНеДойдёт
                ? "в того, кому до меня не дойти, всё равно стреляю из окна: ручка " +
                  "«СтрелятьВТехКтоДоМеняНеДойдёт» включена — учтите, что ради такого " +
                  "выстрела я бросаю работу и трачу стрелы"
                : $"в того, кому до меня не дойти, НЕ СТРЕЛЯЮ и работу ради него не " +
                  $"бросаю (ручка «СтрелятьВТехКтоДоМеняНеДойдёт» снята — то есть выстрел " +
                  $"из окна сейчас запрещён). Воздух вокруг себя обвожу на " +
                  $"{бой.ReachSearchNodes} клеток " +
                  "(«СколькоКлетокСмотретьПроЗапертоеМесто»); не замкнулся — считаю, что дойдёт");

            СказатьЕслиНовое("колокола", ЗовущихПодмогуБитьИздали
                ? "к тем, кто созывает подмогу (в игре это колокол), не подхожу: " +
                  "бью с дальности выстрела, пока есть стрелы " +
                  "(ручка «ЗовущихПодмогуБитьИздали»)"
                : "к колоколам подхожу как ко всем: ручка «ЗовущихПодмогуБитьИздали» " +
                  "снята — учтите, что на шум колокол зовёт до шести глубинных тварей");

            СказатьЕслиНовое("лук", СтрелятьИзЛука
                ? $"стреляю с {бой.ShootMinRange:0.#} до {бой.ShootMaxRange:0.#} бл, " +
                  $"тетиву держу {бой.DrawSeconds:0.##} с, " +
                  (бой.ShootMinChance <= 0
                      ? "берусь за любой выстрел (ручка «СтрелятьПриШансеНеНиже» — 0)"
                      : $"берусь, когда попаду не реже {бой.ShootMinChance:0.##} " +
                        "(«СтрелятьПриШансеНеНиже»); в углу и без ближнего оружия " +
                        "стреляю с любым шансом") +
                  (ТянутьТетивуСекунд < 0.35
                      ? " (вписано меньше 0,3 с — столько игра выстрел не засчитывает вовсе, поднял)"
                      : ТянутьТетивуСекунд < 0.55
                          ? " (меньше 0,55 с — точность не успевает набраться, промахов будет много)"
                          : "")
                : "из лука не стреляю: ручка «СтрелятьИзЛука» снята");

            // ЩИТ. Поднятие — тоже сюда: это присед, а присед стоит 65 %
            // скорости, и решать такое за человека нельзя
            бой.RaiseShield = ПодниматьЩитВБою;
        }

        // ЩИТ ЖИВЁТ У БОТА, А НЕ У БОЯ (слот у него общий с фонарём, и
        // спрашивают его трое). Поэтому ручки щита едут ТУДА ЖЕ, где живёт
        // механизм, а не в способность
        bot.Shield.When = НоситьЩит;
        bot.Shield.LightWinsInDark = ВТемнотеФонарьВажнееЩита;
        СказатьЕслиНовое("щит", НоситьЩит == WearArmor.Никогда
            ? "щит не ношу: ручка «НоситьЩит» — «Никогда»"
            : $"щит ношу: {НоситьЩит}; в темноте рука " +
              (ВТемнотеФонарьВажнееЩита ? "у фонаря" : "у щита") +
              " (ручка «ВТемнотеФонарьВажнееЩита»)");

        // ---- ПУТЬ И ПРЕПЯТСТВИЯ ----
        //
        // ПРОВОДКА ЕДЕТ ВМЕСТЕ С РУЧКАМИ, И ЭТО НЕ ПОРЯДОК РАДИ ПОРЯДКА. Ручка,
        // вставшая в окне без проводки, НЕ ДЕЛАЕТ НИЧЕГО — а окно при этом
        // обещает человеку, что делает; по закону 4 такое обещание дороже
        // ошибки в коде. Стояли эти строки у одного Выживальщика, а ходят все:
        // стражник идёт к посту, продавец обходит прилавки, ИИ ходит своими
        // умениями — и спотыкаются об один и тот же обрыв.

        // --- выбраться из ямы ---
        bot.Movement.ClimbOutWhenTrapped = ВыбиратьсяНаверх;
        bot.Movement.ClimbOutTries = Math.Max(1, ПопытокПодъёма);
        bot.Movement.MaxBreakOutUp = Math.Max(1, ПробиватьсяВверхДо);
        bot.Scaffolding.CarveSteps = ВыбиратьсяНаверх;
        bot.Scaffolding.MineForPillar = ДобыватьМатериалНаСтолб;
        // СПЕРВА К СТЕНЕ. На дне широкого карьера над головой чистое небо, и
        // прежний ответ был «пробиваться наверх некуда»: столб посреди ямы
        // выводит на верх палки 1×1, откуда не слезть
        bot.Movement.WallSearchRadius = ВыбиратьсяНаверх ? Math.Max(0, ИскатьСтенуВРадиусе) : 0;
        bot.Movement.WallHeightToClimb = Math.Max(1, ВысотаСтеныДляПодъёма);
        // ВЫСОТА СТОЛБА И КРУГ, В КОТОРОМ ЕГО ВООБЩЕ СТОИТ СТРОИТЬ. Обе жили в
        // библиотеке заводскими числами, и повернуть их человек не мог ничем —
        // разбор у самих ручек. «Строить ли столб к позвавшему» (AllowPillar)
        // сюда НЕ ЕДЕТ: этот механизм роль зовёт своим умением, и у общей родни
        // его нет — ручка встала бы в окно пустой
        bot.Climbing.MaxPillar = Math.Max(1, МаксимальныйСтолб);
        bot.Climbing.PillarWithin = Math.Max(1, СтолбитьсяВРадиусе);

        // --- временные леса ---
        //
        // ЗАДВИЖКА ОДНА НА ВСЕХ, КТО СТАВИТ ЛЕСА, и стоит она ЗДЕСЬ, потому что
        // ставят их на дороге ходьбы: столб под собой (Mining.PillarUpAsync),
        // лестница наверх и лестница вниз (Scaffolding.LadderUp/LadderDownAsync)
        // — все трое спрашивают TempBlocks.MayPlace, и зовут их выход из ямы и
        // спуск с обрыва, то есть строки двумя абзацами выше. Заведи каждый
        // свою — и «можно ли мне ставить свои блоки» пришлось бы выключать в
        // трёх местах, а забытое третье выглядело бы как самовольство бота.
        //
        // Уборку спрашивают, сверх того, работа (карьер, дорога, возврат) и
        // простой (Unfinished.Of → BehaviorIdle) — а простой есть у всех пяти
        // ролей и доносится отсюда же
        bot.Temp.Allowed = СтроитьВременныеЛеса;
        bot.Temp.TakeDownAfterWork = УбиратьЛесаПослеРаботы;

        // --- через пропасть и вниз с обрыва ---
        // Швы к стройке подключены в самом боте (VsBot): движение замечает
        // разрыв, а строит тот, чьё это дело. Здесь только «стоит ли»
        bot.Movement.BridgeGaps = МоститьРазрывы;
        bot.Movement.MaxBridgeSpan = Math.Max(1, МоститьРазрывДо);
        bot.Movement.MaxBridgeTries = Math.Max(0, ПопытокМоста);
        // Присед — политика («ходить ли пригнувшись»), а механика (померить
        // просвет, дожать шифт, дождаться, пока тело сядет) лежит в движении
        // и в физике игры
        bot.Movement.CrouchThroughGaps = ХодитьВПрисяде;
        bot.Movement.MaxSquatCells = Math.Max(1, НизкийХодДлинойДо);
        bot.Movement.SquatLookAhead = Math.Max(1, ЗамечатьНизкийХодЗа);
        bot.Movement.DescendCliffs = СпускатьсяСОбрывов;
        bot.Movement.MaxDescendDrop = Math.Max(1, СпускатьсяСВысотыДо);
        bot.Movement.MaxDescendTries = Math.Max(0, ПопытокСпуска);
        bot.Movement.AskAboutWaterBeforeStraightRun = СмотретьВодуПередПрямымХодом;
        // ЧЕСТНЫЙ ОТКАЗ ОБЯЗАН ДЕРЖАТЬ, И СРОК ЭТОМУ НАЗНАЧАЕТ ЧЕЛОВЕК. Число
        // жило в библиотеке (Movement.RefusalMemorySeconds) и повернуть его
        // было нечем — а именно оно решает, сколько бот не будет долбить дорогу,
        // которой нет. Обе памяти движения берут его отсюда: у них один смысл
        bot.Movement.RefusalMemorySeconds = Math.Max(0, ПомнитьОтказДорогиСекунд);
        bot.Scaffolding.MaxBridgeSpan = Math.Max(1, ПределМостаСтройки);
        bot.Scaffolding.MaxDescend = Math.Max(1, ПределСпускаСтройки);
        bot.Tunnel.SecondsPerStair = Math.Max(0.5, СекундНаСтупень);
        // ПРОКОПАТЬ ИЛИ ЗАСТРОИТЬ. Порог один и доносится в одно место: и выход
        // наверх, и спуск с обрыва спрашивают его у штольни (Tunnel.StepsOutMaxDepth),
        // и второй копии этого числа в проекте быть не должно — разойдись они,
        // и бот выходил бы ступенями, а слезал бы лестницей без всякой причины
        bot.Tunnel.StepsOutMaxDepth = Math.Max(0, ВыходитьСтупенямиДо);

        // ИНСТРУМЕНТЫ ПРИ СЕБЕ. Требования перекладываются ЦЕЛИКОМ на каждый
        // поворот ручки (снятое из списка снимается и из требований), а вот
        // говорить об этом стоит только когда ответ переменился: иначе на
        // каждое движение любого ползунка в журнал падало бы по две строки
        СказатьЕслиНовое("инструменты", bot.Stock.RequireTools(ЧтоДержатьВРуках()));

        ДонестиЗапасы(bot);

        // ВЕСА — В САМОМ КОНЦЕ И НАРОЧНО: ApplyWeights сбрасывает ВСЕ веса к
        // умолчаниям и применяет строку целиком. Роль, которая ставит вес
        // программно (Behaviors.SetWeight<T>), обязана делать это ПОСЛЕ
        // base.ДонестиОбщее() — иначе её решение сотрётся следующим же
        // поворотом соседней ручки.
        //
        // «Кто над кем» печатается тут же: человек, крутящий веса вслепую,
        // должен видеть названия способностей и их числа, а не подбирать их.
        // Планирование наперёд ставится ПЕРЕД отчётом — Report при револьвере
        // говорит другое («Ближайшее …»), и напечатать надо то, что вышло.
        // Горизонт доносится ВСЕГДА, а не только при включённой галочке: иначе
        // человек, покрутивший его при выключенном планировании и включивший
        // галочку следом, работал бы со старым числом и об этом не узнал
        bot.Behaviors.UseRevolver = ПланироватьНаперёд;
        // Ноль секунд горизонта — это «вперёд не смотреть вовсе», то есть
        // выключенное планирование под видом включённого. Такое человек
        // вписывает опиской, поэтому снизу секунда
        bot.Behaviors.HorizonSeconds = Math.Max(1, ГоризонтПланированияСекунд);
        СказатьЕслиНовое("веса",
            bot.Behaviors.ApplyWeights(ВесаВажности) +
            ". Кто над кем: " + bot.Behaviors.Report() +
            (ПланироватьНаперёд
                ? ". Планирую наперёд: вес растёт со временем, выбор по «вес × сколько займёт»"
                : ". Планирования наперёд нет: беру то, что важнее прямо сейчас"));
    }

    /// <summary>
    /// ЧТО ИМЕННО ПОЕДЕТ В ТРЕБОВАНИЯ ЗАПАСОВ — список из ручки плюс лук, если
    /// он велен галочкой «НуженЛук».
    ///
    /// ОТДЕЛЬНЫМ МЕТОДОМ, А НЕ ДВУМЯ СТРОКАМИ НА МЕСТЕ, РАДИ ЖИВОГО СЛУЧАЯ.
    /// Требования инструментов роль доносит НЕ В ОДНОМ месте: второй раз это
    /// делает Копатель, когда решил не ходить за вещами после смерти и
    /// собирается заново (<c>Recover.OnGaveUp</c>). Впиши мы прибавку лука
    /// прямо в <see cref="ДонестиОбщее"/> — бот, потерявший лук вместе с телом,
    /// пересобрался бы БЕЗ лука и молча, а починка выглядела бы работающей.
    /// Ровно этот класс беды в проекте уже стоил волны.
    ///
    /// ЗОВЁТСЯ ЛУК ТЕМ ЖЕ СЛОВОМ, ЧТО И В САМОЙ ИГРЕ, и слово это не написано
    /// здесь буквами: оно берётся из перечисления игры
    /// (<c>EnumTool.Bow</c>) — того самого, по которому запасы и узнают
    /// инструмент (<see cref="Stock.WhatToolIs"/>). Перепиши игра своё
    /// перечисление — у нас сломается сборка, а не поведение молча.
    /// </summary>
    public static string ЧтоДержатьВРуках(string? список, bool нуженЛук)
    {
        var есть = Stock.ParseList(список).ToList();
        if (!нуженЛук)
            return string.Join(", ", есть);
        string лук = Vintagestory.API.Common.EnumTool.Bow.ToString();
        // ДВАЖДЫ ОДНО И ТО ЖЕ НЕ ПРОСИМ: человек мог написать «Bow» в списке
        // руками. Две записи на один вид — это два голоса на одно требование,
        // и запасы честно поругались бы на спор, которого никто не заводил
        if (!есть.Any(с => string.Equals(с, лук, StringComparison.OrdinalIgnoreCase)))
            есть.Add(лук);
        return string.Join(", ", есть);
    }

    /// <summary>То же, но по своим ручкам. См. <see cref="ЧтоДержатьВРуках(string?, bool)"/>.</summary>
    public string ЧтоДержатьВРуках() => ЧтоДержатьВРуках(ДержатьИнструменты, НуженЛук);

    /// <summary>
    /// ДОНЕСТИ РЕШЕНИЯ РОЛИ ДО ЗАПАСОВ И СНАБЖЕНИЯ: что держать при себе и чем
    /// это пополнять — сделать или сходить взять.
    ///
    /// ОДНО МЕСТО НА ВСЕ ТРИ МЕХАНИЗМА, И ЭТО НАХОДКА ЭТОЙ ВОЛНЫ. Крафт по
    /// потребности спрашивают трое: запасы, снабжение и дорога. Ручка
    /// доносилась до двоих — до снабжения её не довели вовсе, потому что
    /// цепочка «где взять недостающее» завелась позже ручки. Снятая в панели
    /// галочка при этом НИЧЕГО НЕ ВЫКЛЮЧАЛА в третьем: снабжение крафтило по
    /// своему заводскому «да», и человек справедливо решил бы, что настройка не
    /// работает. Теперь адресат один, и забыть четвёртого будет негде.
    /// </summary>
    private void ДонестиЗапасы(VsBot bot)
    {
        // ДЕЛАТЬ И ДОБЫВАТЬ — обе ручки во все три механизма разом
        bot.Stock.MayCraft = КрафтитьНедостающее;
        bot.Stock.MayFetch = ДобыватьНедостающее;
        bot.Supply.MayCraft = КрафтитьНедостающее;
        bot.Supply.MayFetchNearby = ДобыватьНедостающее;
        bot.Roads.MayCraft = КрафтитьНедостающее;

        // ЛЕСТНИЦЫ. Код лестницы НЕ ВЫДУМАН и не написан здесь: его знает
        // стройка (Scaffolding.LadderCode), она же по нему их и вешает. Заведи
        // мы тут второе имя — «держу лестницы» и «строю лестницу» однажды
        // разошлись бы, и бот носил бы не то, что вешает.
        //
        // БЕЗ «если больше нуля» нарочно: ноль у запасов означает «не требовать
        // вовсе» и СНИМАЕТ требование. С проверкой выставленный в панели ноль
        // не снимал бы ничего, и бот до конца смены искал бы лестницы, которых
        // у него больше не просят.
        //
        // fetch: false — лестницу в мире не добывают: выломать её можно только
        // из чужой шахты. Делают или берут из сундука
        bot.Stock.Require(bot.Scaffolding.LadderCode, Math.Max(0, ДержатьЛестниц), fetch: false);

        // ФАКЕЛЫ — ТЕМ ЖЕ ПОРЯДКОМ И ПО ТОЙ ЖЕ ПРИЧИНЕ, что лестницы; до 09.09
        // эта строка стояла у одного Выживальщика, а запас общий у всех пяти.
        //
        // БЕЗ «если больше нуля» нарочно: ноль у запасов означает «не требовать
        // вовсе» и СНИМАЕТ требование. С проверкой выставленный в панели ноль
        // не снимал бы ничего, и бот до конца смены искал бы факелы, которых
        // у него больше не просят.
        //
        // fetch: false — расходник ДЕЛАЮТ, а не выкапывают: поручение ищет
        // источник по реестру блоков и на «нужен факел» уходило искать
        // НАСТЕННЫЕ ДЕРЖАТЕЛИ факелов (разбор — у Upkeep.Поставить)
        bot.Stock.Require("torch", Math.Max(0, ДержатьФакелов), fetch: false);

        // СТРЕЛЫ. Заказчик: «больше бы логики, чтобы бот сам понимал чего ему не
        // достает и крафтил, например стрелы». Понимает и пополняет это ОДИН
        // механизм на весь проект — запас (Stock): он и считает недостачу, и
        // зовёт крафт, и ходит в кладовые. Второй такой счётчик специально под
        // стрелы был бы ровно тем, что запрещает правило 2.
        //
        // fetch: false — стрелу в мире не выкапывают: её делают из наконечника,
        // палки и ПЕРА (рецепт сетевой, из реестра сервера) либо покупают.
        // Подобрать выпущенную с земли бот при этом умеет и без требования.
        //

        // ЗАПАС ПО РАСХОДУ. Числа доносятся ПЕРВЫМИ, строка — последней: строка
        // тут же пересчитывает требования, и донеси мы её раньше, первый
        // пересчёт прошёл бы по вчерашним числам, а человек прочитал бы в
        // журнале не то, что выставил.
        //
        // Ноль минут означал бы «расхода не помню вовсе» — вечная первая горсть
        // под видом умного запаса; снизу минута. У «первого раза» ноль законен:
        // это «ничего заранее не держу, только по расходу».
        bot.Upkeep.WindowMinutes = Math.Max(1, ЗапасНаМинутРасхода);
        bot.Upkeep.FirstTime = Math.Max(0, ЗапасНаПервыйРаз);

        // СКОЛЬКО ДЕРЖАТЬ СВЕРХ ЗАПАСА. Доносится в ЗАПАСЫ, а не в склад, и это
        // не мелочь: число говорит про требования («сколько из этого моё»), а
        // склад лишь спрашивает его перед рейсом. Положи мы его на склад — у
        // «сколько держать» стало бы два хозяина, и окно управления показывало
        // бы одно, а рейс считал по другому.
        //
        // Отрицательные проценты означали бы «держи МЕНЬШЕ, чем велено», то
        // есть спор с собственным требованием: бот сдавал бы стрелы на склад и
        // тут же шёл делать новые
        bot.Stock.KeepExtraPercent = Math.Max(0, ДержатьСверхЗапасаПроцентов);
        // Пустая строка СНИМАЕТ всё, что правило держало: иначе вычеркнутые из
        // панели стрелы жили бы в требованиях до перезапуска
        СказатьЕслиНовое("запас по расходу", bot.Upkeep.Watching(ЗапасПоРасходу));

        // ГДЕ ИСКАТЬ МАТЕРИАЛ. Одно число на двоих: по нему поручение ищет, что
        // ломать, и по нему же разбор «что из чего» решает, обещать ли поход
        // (Errands.NearbyNow). Ноль означал бы «мира вокруг нет вовсе», и бот
        // отказывался бы идти за камнем под ногами
        bot.Errands.SearchRadius = Math.Max(1, ИскатьМатериалВРадиусе);

        // ЦЕЛЬНЫЙ КАМЕНЬ ВМЕСТО ЩЕБЁНКИ — сюда же, к поручениям, и по той же
        // причине: «чем добывать материал» — один вопрос, и двух хозяев у него
        // быть не должно. Карьер копателя ходит тем же выключателем, но своей
        // строкой (SurvivorRole): у ямы есть ещё и вид, а это отдельный разговор
        bot.Errands.TakeWhole = ОбкапыватьРадиЦельногоБлока;
        // ЦЕНА ОБКАПЫВАНИЯ — той же строкой и тому же хозяину: сколько чужих
        // блоков вокруг цели бот вправе снести ради одного целого. Зажим в
        // единицу — не вкус: нулём заходов не освободить ни одной грани, и
        // обкапывание молча превратилось бы в отказ
        bot.Errands.WholeStoneRoundsPerFace = Math.Max(1, ЗаходовНаГраньОбкапывая);

        // ШАХМАТКА — К САМОМУ УДАРУ, А НЕ К РАБОТАМ. Одна строка, и порядок
        // «через одну» получают разом карьер, дорога, штольня и всё, что
        // родится после: они спрашивают очередь у Mining, а не считают её
        // сами. Отдельные строки на каждую работу — это ровно та беда
        // «сделали в одном месте, забыли в другом», которой проект уже
        // трижды горел
        bot.Mining.ЧерезОдну = ШахматкойРадиЦельныхБлоков;

        // ДОДЕЛАТЬ НАЧАТОЕ. Доносится сюда же, а не отдельной строкой в
        // Configure роли, ровно по причине этого метода: «чем пополнять запасы»
        // — один вопрос, и адресатов у него не должно быть в двух местах.
        //
        // «И крафтить разрешено» — не перестраховка, а честность: доделывать
        // начатое нечем, если собирать по рецепту запрещено вовсе, и способность
        // тогда крутилась бы вхолостую, раз в минуту разбирая рецепты ради
        // отказа. Пусть лучше стоит выключенной и молчит
        if (bot.Behaviors.Get<BehaviorFinishStarted>() is { } доделка)
            доделка.Enabled = ДоделыватьНачатое && КрафтитьНедостающее;

        // СБОРЫ НЕ ТРЕБУЮТ КРАФТА, И В ЭТОМ ВСЯ РАЗНИЦА С ДОДЕЛКОЙ: кирка
        // может просто лежать в сундуке склада. Запрет собирать по рецепту
        // не повод не сходить за готовой
        if (bot.Behaviors.Get<BehaviorEquipSelf>() is { } сборы)
            сборы.Enabled = СнаряжатьсяВПростое;
    }

    /// <summary>
    /// ДОНЕСТИ РЕШЕНИЯ РОЛИ ДО СКЛАДА: что оставлять при себе, сколько давать
    /// на рейс, возвращаться ли в забой и как жить с описью сундуков.
    ///
    /// ПОЧЕМУ ЭТО ЗДЕСЬ, А НЕ В БИБЛИОТЕКЕ. Сам рейс — механика и живёт в
    /// <see cref="Depot"/>: дойти, открыть, переложить, вернуться. А «что моё»,
    /// «сколько это стоит по времени» и «долго ли верить своей памяти» —
    /// решения роли, и у ролей они разные: рудокопу кирка нужна при себе,
    /// продавцу нет; у одного склад в трёхстах блоках, у другого за спиной.
    /// Все эти числа лежали в библиотеке одними на всех, и повернуть их в окне
    /// управления было нечем.
    ///
    /// Ответ про «что моё» говорится вслух и только когда переменился:
    /// ДонестиОбщее зовётся на каждый поворот ЛЮБОЙ ручки.
    /// </summary>
    private void ОтнестиНастройкиСклада(VsBot bot)
    {
        var склад = bot.Depot;

        // ЧТО ОСТАВЛЯТЬ ПРИ СЕБЕ. Порядок важен: сперва две галочки, потом
        // список, — потому что ответ механизма про список называет и их
        // («…и всё, у чего есть прочность»), и с прошлыми значениями он был бы
        // враньём на один поворот ручки
        склад.KeepTools = ОставлятьВсеИнструменты;
        склад.KeepFood = ОставлятьЕду;
        СказатьЕслиНовое("при себе", склад.KeepAtHand(ОставлятьПриСебе));

        // СКОЛЬКО ДАВАТЬ НА РЕЙС. Ноль означал бы «рейс не начинать вовсе», и
        // выглядело бы это как молча сломанный склад: бот с полной сумкой
        // стоит и ничего не делает. Минута — нижняя честная мерка: меньше не
        // хватает даже на сундук под ногами
        склад.MaxSeconds = Math.Max(60, СекундНаРейс);
        // Ноль расстояния означал бы «склада не бывает нигде»: любая точка
        // дальше нуля блоков считалась бы опиской, и бот отказывался бы идти
        // даже к сундуку под ногами
        склад.MaxDistance = Math.Max(1, СкладНеДальшеЧем);
        склад.ReturnToFace = ВозвращатьсяВЗабой;

        // ОПИСЬ СКЛАДА. «Свежесть» и «протухание» — две разные мерки одной
        // памяти, и путать их нельзя: первая решает, стоит ли открывать сундук
        // заново, вторая — можно ли ВЕРИТЬ ответу «этого там нет». Отрицательные
        // числа сюда не пускаем: они означали бы «запись протухла раньше, чем
        // сделана»
        склад.ScanOnHaul = ОписыватьСкладПриРейсе;
        склад.ScanFreshMinutes = Math.Max(0, ОписьСвежаМинут);
        склад.ScanStaleMinutes = Math.Max(0, ОписьПротухаетЧерезМинут);
        // Пять секунд — тот же порог, по которому сам рейс решает «времени
        // почти не осталось, опись не обновляю»: обход, которому дали меньше,
        // не успевает открыть и один сундук
        склад.ScanSeconds = Math.Max(5, СекундНаОбходСклада);

        // РЕЙС ЗА МАТЕРИАЛОМ ДЛЯ КРАФТА. Числа стоят ЗДЕСЬ, а не у очереди
        // задач, хотя ручки живут в её разделе: за материалом ходит склад, и к
        // нему же обращается крафт, идущий вовсе без очереди (снаряжение,
        // панель, чат). Стой они у очереди — бот без очереди работал бы по
        // заводским умолчаниям, а человек видел бы в окне свои значения
        склад.SupplyForCraft = БегатьДомойЗаМатериалом;
        склад.SupplyRuns = Math.Max(0, РейсовДомойЗаЗадачу);
        // Ноль сборов означал бы «принести нуль камня»: рейс состоялся бы,
        // сумка осталась пустой, а работа встала бы на том же месте — и так по
        // кругу до потолка рейсов
        склад.SupplyBatch = Math.Max(1, БратьМатериалНаСборов);
        // Отрицательный порог — это «не ходить никогда», но сказанное опиской:
        // ноль уже значит «порога нет», и второго способа выключить рейс
        // заводить незачем — на то есть галочка выше
        склад.SupplyMaxBlocks = Math.Max(0, ЗаМатериаломНеДальшеБлоков);
        склад.SupplyMaxMinutes = Math.Max(0, ЗаМатериаломНеДольшеМинут);

        // САМ ИДУ НА СКЛАД, КОГДА СУМКИ ПОЛНЫ — ТРИ РУЧКИ ОДНОЙ СЕМЬИ И В
        // ОДНОМ МЕСТЕ. Приехали 09.09 от выживальщика: способность подключает
        // КАЖДОМУ боту пресет выживания, а включить её могла одна роль из пяти.
        //
        // ПОРОГ «ПОРА НА СКЛАД» — ОДИН НА ВЕСЬ БОТ, и потому он стоит в складе,
        // а не в способности: по нему ходят оба — и рейс, и наряд за рудой
        // (MiningOrder спрашивает Depot.TimeToHaul на каждом круге). Заведи мы
        // второй порог у способности, «когда сумка полна» означало бы у них
        // разное, и объяснить это человеку было бы нечем.
        //
        // Ноль мест — законный выбор («иду, только когда забита начисто»),
        // поэтому снизу ноль, а не единица.
        склад.HaulWhenFreeSlots = Math.Max(0, РазгружатьсяПриСвободныхМестах);
        if (bot.Behaviors.Get<BehaviorHaulWhenFull>() is { } рейс)
        {
            рейс.Enabled = РазгружатьсяСам;
            // Пять секунд — нижняя честная мерка повтора: неудача рейса не
            // проходит сама (сумка как была полной, так и осталась), и без
            // паузы бот отбирал бы тело у работы каждые полсекунды, а возврат
            // к прерванному бросил бы карьер на третьем заходе как безнадёжный
            рейс.RetrySeconds = Math.Max(5, ПовторРазгрузкиЧерезСекунд);
        }
    }

    /// <summary>
    /// Бегун очереди задач на вечер; null — очередь к боту не подключена
    /// (так живёт бот под внешним управлением и любой запуск без неё).
    /// </summary>
    private WorkRunner? очередь;

    /// <summary>
    /// БЕГУН ОЧЕРЕДИ ПРЕДСТАВИЛСЯ. Собирает его не роль и не бот, а программа,
    /// поэтому знакомство идёт с его стороны (<see cref="IWorkRunnerRole"/>) —
    /// иначе ручки очереди доносить было бы НЕКУДА.
    ///
    /// Доносим сразу же: бегун мог собраться и после того, как человек накрутил
    /// ручки в пресете, — и тогда его умолчания молча перебили бы решения роли.
    /// </summary>
    public void UseRunner(WorkRunner runner)
    {
        очередь = runner;
        ОтнестиНастройкиОчереди();

        // И ПРОСТОЮ — ТОЖЕ. Цикл задач в простое гоняет ЭТУ ЖЕ очередь, второй
        // не заводя; а способность безделья собирается раньше бегуна и знать
        // про него ниоткуда не может
        if (бот?.Behaviors.Get<BehaviorIdle>() is { } безДела)
            безДела.Works = runner;
        // И ЧИСЛА СКЛАДА ЗАОДНО. Ручки рейса за материалом живут в разделе
        // очереди, а сами числа — у склада (см. ОтнестиНастройкиСклада); бегун
        // же собирается ПОСЛЕ роли, и человек, покрутивший ручку до его сборки,
        // иначе не увидел бы ни следа — ровно та беда, ради которой этот шов и
        // заводился
        if (бот is { } b)
            ОтнестиНастройкиСклада(b);
    }

    /// <summary>
    /// ДОНЕСТИ РЕШЕНИЯ РОЛИ ДО ОЧЕРЕДИ ЗАДАЧ: сколько давать на дорогу и как
    /// быть с нехваткой материала.
    ///
    /// Очереди может не быть вовсе — молчим: это не беда, а способ запуска
    /// (внешнее управление поднимает бота без очереди). Жаловаться на каждый
    /// поворот ручки там, где всё в порядке, — тот же шум, что и молчание там,
    /// где беда.
    /// </summary>
    private void ОтнестиНастройкиОчереди()
    {
        if (очередь is not { } бегун)
            return;

        // Ноль секунд на дорогу означал бы «ни одна задача с точкой не
        // начинается»: бот отказывал бы всем, не сделав ни шага, и причина
        // («не дошёл за 0 с») выглядела бы поломкой ног, а не настройкой
        бегун.TravelSeconds = Math.Max(1, СекундНаДорогуКЗадаче);

        // «БЕГАТЬ ЛИ ДОМОЙ», «СКОЛЬКО РАЗ» И «СКОЛЬКО НЕСТИ» СЮДА БОЛЬШЕ НЕ
        // ДОНОСЯТСЯ — и это не пропажа. Рейс за материалом делает склад, и
        // числа живут у него (ОтнестиНастройкиСклада); ручки бегуна остались
        // дверьми к тем же числам. Донеси их и здесь — они доезжали бы ТОЛЬКО
        // при собранной очереди, а крафт, зовущий склад напрямую, работал бы по
        // заводским умолчаниям вопреки повёрнутой ручке
    }

    /// <summary>
    /// ДОНЕСТИ РЕШЕНИЯ РОЛИ ДО СЕТИ ТРАНСЛОКАТОРОВ: откуда её брать и во что
    /// считать дорогу.
    ///
    /// ПОЧЕМУ ЭТО ЗДЕСЬ, А НЕ В БИБЛИОТЕКЕ. Механизм (чтение карты, граф,
    /// Дейкстра) живёт в <see cref="TranslocatorRouting"/> и не знает ни одного
    /// адреса; адреса и цены — политика роли. Пока этих строк не было, ручек не
    /// существовало ни у одной роли, механизм не звался НИОТКУДА, и заказчик,
    /// вписавший карту сервера, получал картинку без единого маршрута.
    ///
    /// Ответ говорится вслух и только когда переменился: ДонестиОбщее зовётся
    /// на каждый поворот любой ручки.
    /// </summary>
    private void ОтнестиСетьТранслокаторов(VsBot bot)
    {
        var сеть = bot.Routes;
        сеть.Source.MapAddress = (КартаТранслокаторов ?? "").Trim();
        сеть.Source.FilePath = (ФайлСетиТранслокаторов ?? "").Trim();
        // Срок протухания живёт у источника и у цен маршрута: первый решает,
        // когда идти за картой заново, второй — когда сказать «маршрут по ней
        // остаётся планом». Число ОДНО, ручка одна
        сеть.Source.StaleAfterHours = Math.Max(0, КартаУстареваетЧерезЧасов);
        сеть.Settings = сеть.Settings with
        {
            // Отрицательный радиус означал бы «к сети не подходить вовсе», а
            // ноль — «садиться только на транслокатор под ногами». И то и
            // другое человек вписывает опиской, поэтому снизу ноль
            WalkRadius = Math.Max(0, ОтходитьОтСетиНеДальше),
            // Бесплатная пересадка превратила бы граф в «прыгать всегда»:
            // цепочка из шести прыжков ради двух шагов выигрывала бы поиск
            TeleportSeconds = Math.Max(0, СекундНаПересадку),
            // Ноль секунд на блок означал бы «ходьба бесплатна» — тогда сеть
            // не нужна вовсе, и бот пошёл бы пешком через полмира
            WalkSecondsPerBlock = Math.Max(0.01, СекундНаБлокПешком),
            StaleAfterHours = Math.Max(0, КартаУстареваетЧерезЧасов),
            // Отрицательный порог означал бы «через сеть даже когда она
            // МЕДЛЕННЕЕ» — это не настройка, а описка. Ноль законен: так
            // говорят «сеть тут исправна, верю ей как своим ногам»
            MinNetGainSecondsPerTransfer = Math.Max(0, ВыигрышНаПересадкуСекунд),
        };

        // И САМОЕ ГЛАВНОЕ: С КАКОЙ ДАЛЬНОСТИ ДОРОГА ВООБЩЕ СМОТРИТ НА СЕТЬ.
        // Без этой строки весь счёт по переходам оставался бы виден только в
        // окне управления, а бот бегал бы ногами — ровно то, на что заказчик и
        // пожаловался 01.09. Отрицательное — та же описка, что и всюду выше:
        // считаем нулём, то есть «не искать вовсе», и говорим об этом словами
        bot.Movement.ByNetFromBlocks = Math.Max(0, ИскатьТранслокаторОтБлоков);

        // КАРТЫ НЕТ — ЭТО ЕЩЁ НЕ «МАРШРУТОВ НЕ БУДЕТ». Заказ 17.08: «а если
        // вебкарты нет у нас, то мы можем сами запоминать какие пары у тл и
        // куда идут?» — теперь можем (TlMemory), и отказ обязан об этом
        // сказать: иначе человек читает «маршрутов по транслокаторам не будет»
        // у бота, который как раз ходит по ним своей памятью
        string? нетКарты = TranslocatorNetSource.WhyNoNet(сеть.Source.MapAddress,
            сеть.Source.FilePath, File.Exists(сеть.Source.FilePath ?? ""));
        if (нетКарты is { } безКарты)
            нетКарты = безКарты + ". " + (сеть.Memory is { Count: > 0 } моя
                ? $"Зато {моя.Tell()} — по ним маршруты строю"
                : "Своей памяти о парах пока тоже нет: она копится сама — что увижу " +
                  "рядом и чем пройду ногами, то и запомню, и переживёт перезапуск");

        СказатьЕслиНовое("сеть транслокаторов",
            нетКарты
            ?? $"беру сеть переходов" +
               (сеть.Source.MapAddress is { Length: > 0 } а ? $" с карты {а}" : "") +
               (сеть.Source.FilePath is { Length: > 0 } ф ? $", файл «{ф}»" : "") +
               $"; пересадка {СекундНаПересадку:0.#} с, пешком {СекундНаБлокПешком:0.##} с/бл, " +
               $"от сети отхожу не дальше {ОтходитьОтСетиНеДальше:0} бл, " +
               (ВыигрышНаПересадкуСекунд > 0
                   ? $"через сеть иду, только если она выигрывает от " +
                     $"{ВыигрышНаПересадкуСекунд:0.#} с на пересадку"
                   : "через сеть иду при любом выигрыше: порога нет"));

        // ОТДЕЛЬНОЙ СТРОКОЙ, А НЕ ХВОСТОМ К ПРЕДЫДУЩЕЙ. Порог «искать переход
        // от» решает не то, ОТКУДА брать сеть, а то, СМОТРИТ ЛИ на неё обычная
        // дорога вообще, — и он одинаково важен и с картой, и без неё, на одной
        // своей памяти. Спрячь его в ветку «карта есть» — и человек, у которого
        // карты нет, читал бы отказ про карту и не узнал бы, что его бот к тому
        // же не ищет переходы вовсе
        СказатьЕслиНовое("транслокаторы перед дорогой",
            ИскатьТранслокаторОтБлоков > 0
                ? $"перед дальней дорогой смотрю на переходы: от " +
                  $"{ИскатьТранслокаторОтБлоков:0} бл по прямой и дальше"
                : "перед дорогой переходы НЕ ИЩУ вовсе: порог «искать транслокатор от» " +
                  "стоит на нуле — хожу только ногами, сколько бы ни было до цели");
    }

    /// <summary>Что уже сказано про эту настройку — чтобы не повторяться.</summary>
    private readonly Dictionary<string, string> сказано = new();

    /// <summary>
    /// Сказать вслух, но только если ответ переменился.
    ///
    /// Молчать нельзя: человек повернул ручку и вправе знать, что вышло
    /// («„топорик“ — такого инструмента игра не знает»). Но ДонестиОбщее
    /// зовётся на КАЖДЫЙ поворот любой ручки, и без этой проверки одна и та же
    /// строка про инструменты падала бы в журнал десятками.
    ///
    /// Открыт наследнику НАРОЧНО: у роли со своими ручками ровно та же беда, и
    /// вторая такая же память («что уже сказано») означала бы, что одна и та же
    /// строка может прозвучать дважды — по разу из каждой половины роли.
    /// </summary>
    protected void СказатьЕслиНовое(string про, string строка)
    {
        if (бот is not { } bot)
            return;
        if (сказано.TryGetValue(про, out string? было) && было == строка)
            return;
        сказано[про] = строка;
        bot.Log($"[{про}] {строка}");
    }

    /// <summary>
    /// Уже сказано, что «ИзбегатьИгроков» без «МахатьИгрокам» ничего не даёт.
    /// Приехало 09.09 от выживальщика вместе с самой ручкой: жалоба обязана
    /// звучать у всякой роли, а не у одной.
    /// </summary>
    private bool жаловалсяНаИзбеганиеЛюдей;

    /// <summary>Уже пожаловались, что координаты дома перевести нечем.</summary>
    private bool жаловалсяНаДом;

    /// <summary>Уже пожаловались, что координаты склада перевести нечем.</summary>
    private bool жаловалсяНаСклад;

    /// <summary>
    /// Донести точку склада до механизма. Зовётся из <see cref="ДонестиОбщее"/>,
    /// то есть на каждый поворот любой ручки и после входа в мир — потому что
    /// раньше входа перевода координат НЕ СУЩЕСТВУЕТ: сдвиг берётся из точки
    /// спавна, а она приходит пакетом уже в мире. Молчать в этом случае нельзя:
    /// со стороны «задал и ничего не произошло» неотличимо от «настройка не
    /// работает».
    ///
    /// ЗДЕСЬ, А НЕ У КОПАТЕЛЯ: точка склада — ручка всякой живущей роли
    /// (<see cref="Склад"/>), и вторая копия этой работы означала бы, что у
    /// стражника и продавца склад доезжает до Depot по другой дороге, чем у
    /// копателя, — а разъехались бы они молча.
    /// </summary>
    private void ОтнестиСкладБоту(VsBot bot)
    {
        if (Склад is not { } точка)
        {
            // Пустая ручка = «склада нет». Молчать нельзя: снять склад и не
            // узнать об этом — то же самое, что задать его и не узнать
            if (bot.Depot.Known)
            {
                bot.Depot.Forget();
                bot.Log("склад роли снят — сдавать теперь некуда");
            }
            return;
        }
        if (!bot.CoordsKnown())
        {
            // Одна жалоба, а не одна на каждый поворот любой ручки: настройки
            // доносятся до механизмов целиком, и до входа в мир их доносят
            // столько раз, сколько человек крутит панель
            if (!жаловалсяНаСклад)
            {
                жаловалсяНаСклад = true;
                bot.Log($"склад {точка} запомнил, но перевести в мировые координаты пока нечем — " +
                        "точка спавна приходит только после входа в мир; донесу, как войду");
            }
            return;
        }
        жаловалсяНаСклад = false;
        var клетка = bot.WorldCell(точка);
        // Уже стоит ровно там — молчим. Иначе журнал заливает строкой «склад:
        // …» на каждый поворот соседней ручки
        if (bot.Depot.Chests.Count == 1 && bot.Depot.Chests[0] == клетка)
            return;
        bot.Log("склад: " + bot.Depot.SetChest(клетка));
    }

    /// <summary>
    /// Донести точку дома до укрытия, бури, точки возрождения И СНАБЖЕНИЯ. Дом
    /// в боте живёт ОДИН — в <see cref="Shelter.Home"/>; и буря, и «иди домой
    /// без дела», и отметка точки возрождения спрашивают именно его.
    ///
    /// Снабжение — ЕЩЁ ОДИН потребитель той же самой точки, а не второе понятие
    /// дома: заказчик просил «если для проекта не отмечен склад с ресурсами, то
    /// смотреть дома недостающие», и «дома» тут значит ровно эту клетку с её
    /// сундуками (<see cref="Depot.HomePoints"/>).
    /// </summary>
    private void ОтнестиДомБоту(VsBot bot)
    {
        if (Дом is not { } точка)
        {
            if (bot.Shelter.Home != null)
            {
                bot.Shelter.Home = null;
                bot.Depot.Home = null;
                if (bot.Behaviors.Get<BehaviorShelterFromStorm>() is { } буря)
                    буря.Home = null;
                bot.Log("дом роли снят — прятаться в бурю и возрождаться теперь негде, " +
                        "а за недостающим я схожу только на склад");
            }
            return;
        }
        if (!bot.CoordsKnown())
        {
            // Одна жалоба, а не одна на каждый поворот любой ручки: молчать
            // тут нельзя — «задал дом и ничего не произошло» со стороны
            // неотличимо от «настройка не работает»
            if (!жаловалсяНаДом)
            {
                жаловалсяНаДом = true;
                bot.Log($"дом {точка} запомнил, но перевести в мировые координаты пока нечем — " +
                        "точка спавна приходит только после входа в мир; донесу, как войду");
            }
            return;
        }
        жаловалсяНаДом = false;
        var клетка = bot.WorldCell(точка);
        if (bot.Shelter.Home == клетка)
            return;
        bot.Shelter.Home = клетка;
        // Та же клетка — снабжению: сундуки дома оно ищет вокруг неё
        bot.Depot.Home = клетка;
        if (bot.Behaviors.Get<BehaviorShelterFromStorm>() is { } гроза)
            гроза.Home = клетка;
        bot.Log($"дом: ({bot.PlayerCoords(клетка.X, клетка.Y, клетка.Z)})");
    }

    /// <summary>
    /// Запомнить клетку, где бот стоит, как дом — для команды «!дом тут».
    /// Возвращает ответ человеку словами; молчания тут быть не должно.
    ///
    /// «ЗАПОМНИЛ» ЗНАЧИТ И НА СЛЕДУЮЩИЙ ЗАПУСК ТОЖЕ. Жалоба заказчика дословно:
    /// «запоминание не работает у дома и склада». Дом ложился в ручку роли и
    /// доносился до укрытия, бури и точки возрождения — то есть работал весь
    /// вечер, — но в ФАЙЛ готового бота его не писал никто: записывать ручки
    /// умело только окно управления, а тут их крутят словом. Бот отвечал
    /// «Запомнил дом», человек перезапускал бота, и дома не было.
    /// </summary>
    protected string ЗапомнитьДомЗдесь(VsBot bot)
    {
        // ДО ВХОДА В МИР ПЕРЕВОДИТЬ НЕЧЕМ, И МОЛЧАТЬ ОБ ЭТОМ НЕЛЬЗЯ. Этой
        // проверки здесь НЕ БЫЛО: сказанное до входа «!дом тут» клало в ручку
        // МИРОВЫЕ числа (512061…) и отвечало «Запомнил дом» — человек получал
        // дом за полмиллиона блоков от себя, и ни одной строки о том, почему
        if (!bot.CoordsKnown())
            return "не знаю начала отсчёта мира — точка спавна приходит только после входа " +
                   "в мир. Скажите «!дом тут» ещё раз, когда я войду";
        // ОДНА ДВЕРЬ НА «КЛЕТКУ, ГДЕ Я СТОЮ, ИГРОВЫМИ ЧИСЛАМИ» (GamePosHere).
        // Здесь СТОЯЛА своя копия floor-а и перевода — та самая, ради сведения
        // которой дверь и заводилась; свести её поток забыл, и копий осталось
        // две, только одна из них называлась «общим механизмом»
        if (bot.GamePosHere() is not { } здесь)
            return "не знаю, где я — дом запомнить не от чего";
        Дом = здесь;
        // ЧЕРЕЗ ТУ ЖЕ ДВЕРЬ, ЧТО И ОКНО. Слово в чате крутит ручку так же, как
        // мышь в браузере, и след роли обязан узнать об этом одинаково: иначе
        // дом, заданный «!дом тут», при смене роли остался бы на новом боте
        // чужой точкой, а заданный в окне — не остался
        Донести();
        // Тем же самым записывающим, каким пишет окно управления, — второго
        // здесь не заводится (см. VsBot.ЗапомнитьРучкиРоли)
        return $"Запомнил дом: ({bot.PlayerCoordsHere()}). {bot.ЗапомнитьРоль()}";
    }

    /// <summary>
    /// НАСКОЛЬКО ДАЛЕКО СМОТРЕТЬ ПО СЛОВУ «!СКЛАД ТУТ», блоков. Не ручка
    /// нарочно: «тут» — это не настройка, а слово человека, который СТОИТ
    /// у своих сундуков. Восемь блоков — расстояние, с которого он их видит и
    /// сам.
    ///
    /// ЧИСЛО ЭТО — ПРО СЛОВО, А НЕ ПРО ВСЯКИЙ ПОИСК СУНДУКОВ, и с 29.08 оно
    /// больше никуда не расползается. Самопоиск при входе в мир зовёт тот же
    /// <see cref="ВзятьСкладЗдесь"/>, но со СВОИМ радиусом: там никто нигде не
    /// стоит нарочно, там бот только что вошёл в мир, и мерить его «тем, что
    /// человек видит вокруг себя» нечем. Когда самопоиск переехал на общий
    /// механизм, он МОЛЧА взял и это число — с двенадцати блоков ушёл на
    /// восемь, и ни один стенд не покраснел. Поэтому радиус теперь приходит
    /// снаружи, называется у каждого зовущего вслух и сторожится стендом
    /// (СамопоискСкладаОднимПравиломTests).
    /// </summary>
    private const int СундукиВокругВРадиусе = 8;

    /// <summary>
    /// ВЗЯТЬ СКЛАД ЗДЕСЬ — для слова «!склад тут». Возвращает ответ человеку
    /// словами; молчания тут быть не должно.
    ///
    /// ЧТО СКАЗАНО — ТО И ОСТАНЕТСЯ. Прежде тут был ВТОРОЙ способ взять склад
    /// вокруг себя (жил он в самом складе; где он стоял и почему его больше
    /// нет, записано на его месте — конец <c>Depot</c>). Он клал в склад ВСЕ
    /// найденные сундуки и отвечал «Взял под склад сундуков: 16» — а «где
    /// склад» у роли живёт ОДНОЙ точкой, которая переживает перезапуск. На
    /// первый же поворот любой ручки в панели (и на следующий вход в мир)
    /// донесение сводило склад к этой одной точке, и стражник, кормившийся с
    /// шестнадцати сундуков, оставался с одним. Число в ответе было правдой
    /// ровно до следующего мига.
    ///
    /// ПОЭТОМУ СЧИТАЕМ ПОСЛЕ ДОНЕСЕНИЯ, А НЕ ДО. Ближний сундук становится
    /// точкой склада, остальные приходят соседями
    /// (<see cref="СоседниеСундукиВРадиусе"/> → <c>Depot.Points</c>), и
    /// названное число — это то самое, которое человек увидит и завтра.
    /// Соседи не запоминаются нарочно: сундук могли сломать, и список, снятый
    /// один раз, врал бы до перезапуска.
    ///
    /// ЧЕГО НЕ ВИДНО — О ТОМ ГОВОРИМ ВСЛУХ. Сундук, стоящий дальше радиуса
    /// соседей от ближней точки, под склад не пойдёт, и молчать об этом нельзя:
    /// человек поставил его нарочно. Ответ называет и число, и ручку, которой
    /// это чинится.
    /// </summary>
    /// <param name="радиус">
    /// НАСКОЛЬКО ДАЛЕКО СМОТРЕТЬ, блоков. Приходит снаружи, потому что зовущих
    /// двое и мерка у них РАЗНАЯ: слово «!склад тут» меряет тем, что человек
    /// видит вокруг себя (<see cref="СундукиВокругВРадиусе"/>), самопоиск при
    /// входе в мир — своим числом. Пока число было одно на обоих, переезд
    /// самопоиска на этот механизм молча ужал его радиус.
    /// </param>
    /// <param name="запомнить">
    /// ПИСАТЬ ЛИ НАЙДЕННОЕ В ПРЕСЕТ. Разница не в удобстве, а в том, чьё это
    /// решение.
    ///
    /// «!склад тут» — СЛОВО ЧЕЛОВЕКА: он стоит у своих сундуков и просит
    /// запомнить их надолго. Не записать — это та самая половина жалобы
    /// «запоминание не работает у дома и склада».
    ///
    /// САМОПОИСК ПРИ ВХОДЕ В МИР — ДОГАДКА БОТА, и записывать её в пресет
    /// нельзя. Живьём 29.08 записанная догадка выглядела так: в файле роли
    /// появлялось «"Склад": {65,112,257}», со следующего запуска
    /// <c>Depot.Known</c> уже истинно — и поиск не повторялся НИКОГДА, а
    /// выключение галки «ИскатьСундукиРядом» чужой сундук из пресета уже не
    /// убирало. Догадка живёт ровно один заход: сломали сундук — на следующем
    /// входе бот поищет заново; выключили галку — не поищет вовсе.
    /// </param>
    protected string ВзятьСкладЗдесь(VsBot bot, int радиус, bool запомнить)
    {
        // ДО ВХОДА В МИР ПЕРЕВОДИТЬ НЕЧЕМ, И МОЛЧАТЬ ОБ ЭТОМ НЕЛЬЗЯ — тот же
        // довод, что у «!дом тут»: без точки спавна игровые координаты не
        // отличить от мировых
        if (!bot.CoordsKnown())
            return "не знаю начала отсчёта мира — точка спавна приходит только после входа " +
                   "в мир. Скажите «!склад тут» ещё раз, когда я войду";

        var рядом = bot.Depot.StorageNear(радиус, out int мимо, out string нечем);
        if (нечем.Length > 0)
            return "сундуки вокруг не искал: " + нечем;
        if (рядом.Count == 0)
            return $"сундуков в радиусе {радиус} вокруг не вижу" +
                   (мимо > 0 ? $" (ещё {мимо} блок-сущностей рядом складом не признаны)" : "") +
                   ". Поставьте сундук рядом и скажите «!склад тут»";

        // БЛИЖНИЙ КО МНЕ — И ЭТО «ТУТ». Прежде точкой становился
        // <c>Depot.Chests[0]</c>, то есть при уже заданном складе — СТАРАЯ,
        // далёкая точка: «!склад тут» отвечал бодро и не двигал ничего
        Склад = bot.GameOf(рядом[0]);
        // ЧЬЁ ЭТО ЗНАЧЕНИЕ — ГОВОРИМ СРАЗУ, А НЕ ТОЛЬКО СЛОВАМИ В ОТВЕТЕ.
        //
        // Обещание «догадка живёт один заход» до сих пор держалось на том, что
        // самопоиск САМ не звал записывающего. Этого мало: пресет снимается с
        // ЖИВОЙ роли целиком, и первый же поворот любой другой ручки уносил
        // догадку в файл молча — вместе с чужим соседским сундуком. Приёмка
        // проверила живьём: поворот «ВысотаШтольни» уложил в пресет заодно
        // «Дом». Пометка эта — единственная дверь, и снимет её любой
        // человеческий поворот той же ручки (разбор — BotRole.ПометитьДогадку)
        ПометитьДогадку(nameof(Склад), догадка: !запомнить);
        // ЧЕРЕЗ ТУ ЖЕ ДВЕРЬ, ЧТО И ОКНО (см. «!дом тут»): слово в чате крутит
        // ручку так же, как мышь в браузере
        Донести();

        int всего = bot.Depot.Points().Count;
        string хвост = всего < рядом.Count
            ? $" Ещё {рядом.Count - всего} вижу рядом, но они дальше " +
              $"{СоседниеСундукиВРадиусе} бл от этой точки — поднимите " +
              "«СоседниеСундукиВРадиусе», если нужны и они."
            : "";
        // …А ЗАПОМНИТЬ НАДОЛГО — тем же записывающим, каким пишет окно
        // управления. Без этой строки «!склад тут» доживал до перезапуска и
        // пропадал: половина жалобы «запоминание не работает у дома и склада»
        // — ровно про него.
        //
        // ЗАПИСЬ — ТОЛЬКО ПО СЛОВУ ЧЕЛОВЕКА (см. «запомнить»): догадка бота в
        // пресет не идёт и говорит об этом вслух, иначе молчание неотличимо от
        // «записал» — а человек, прочитав «взял под склад», вправе спросить,
        // доживёт ли это до завтра. Держит это обещание не молчание здесь, а
        // пометка выше: сам-то самопоиск не писал никогда, писал за него
        // первый же поворот чужой ручки
        return $"Взял под склад сундуков: {всего}. Ближний — {Склад}.{хвост} " +
               (запомнить
                   ? bot.ЗапомнитьРоль()
                   : "В пресет не пишу: это моя догадка, а не ваше слово — скажите " +
                     "«!склад тут» или задайте «Склад» в окне, и запомню надолго.");
    }
}
